/* ─── UTILIDADES Y CONSTANTES ─── */
function escapeHTML(str) {
  if (typeof str !== 'string') return str === undefined || str === null ? '' : String(str);
  return str
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

const DIAS_ORDEN_SEMANAL = ['Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes', 'Sábado', 'Domingo'];

function ordenarDiasCronologico(diasArray) {
  if (!Array.isArray(diasArray)) return [];
  return [...diasArray].sort((a, b) => {
    const idxA = DIAS_ORDEN_SEMANAL.indexOf(a);
    const idxB = DIAS_ORDEN_SEMANAL.indexOf(b);
    return (idxA === -1 ? 99 : idxA) - (idxB === -1 ? 99 : idxB);
  });
}

function getModoDocenteDia(turno, dia) {
  const key = turno === 'hum' ? 'cea_hum_modo_dia' : 'cea_tec_modo_dia';
  const modos = lsGet(key, {});
  if (modos[dia]) return modos[dia];
  return (['Miércoles', 'Jueves', 'Viernes', 'Sábado'].includes(dia)) ? 'multi' : 'mono';
}

function cambiarModoDocenteDia(turno, dia, nuevoModo) {
  const key = turno === 'hum' ? 'cea_hum_modo_dia' : 'cea_tec_modo_dia';
  const modos = lsGet(key, {});
  modos[dia] = nuevoModo;
  lsSet(key, modos);
  cargarHorariosMatriz(turno);
  mostrarToastLive(`Día ${dia} configurado como ${nuevoModo === 'multi' ? 'Multi-docente (4 Paralelos)' : 'Mono-docente (1 Docente)'}`);
  enviarGoogleSheet({
    action: 'guardar-contenido-vivo',
    key: turno === 'hum' ? 'hum_modo_dia_json' : 'tec_modo_dia_json',
    valor: JSON.stringify(modos)
  });
}

