// 6 Carreras Técnicas Oficiales y Registradas del CEA Madre Marie Poussepín
const CARRERAS_OFICIALES_KEYS = ['tec-agropecuaria', 'tec-sis', 'tec-gas', 'tec-bel', 'tec-tex', 'tec-sec'];
const AREAS_TEC_DEFAULT = CARRERAS_OFICIALES_KEYS.map(k => BASE_CARRERAS_20.find(c => c.key === k)).filter(Boolean);

/* ─── ASIGNADOR AUTOMÁTICO DE ÍCONOS VECTORIALES CON RELLENO SÓLIDO PARA CARRERAS ─── */
function obtenerIconoCarreraTec(key, nombre, size = 20) {
  const k = (key || '').toLowerCase();
  const n = (nombre || '').toLowerCase()
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "");

  // 1. Sistemas Informáticos / Tecnología Digital / Computación / Programación / Redes
  if (k.includes('sis') || k.includes('tid') || n.includes('sistema') || n.includes('informa') || n.includes('computa') || n.includes('software') || n.includes('program') || n.includes('digital') || n.includes('redes')) {
    return `<svg viewBox="0 0 24 24" width="${size}" height="${size}" fill="currentColor"><path d="M20 18c1.1 0 1.99-.9 1.99-2L22 6c0-1.1-.9-2-2-2H4c-1.1 0-2 .9-2 2v10c0 1.1.9 2 2 2H0v2h24v-2h-4zM4 6h16v10H4V6z"/></svg>`;
  }

  // 2. Gastronomía / Cocina / Alimentos / Repostería / Panadería
  if (k.includes('gas') || n.includes('gastro') || n.includes('cocin') || n.includes('alimen') || n.includes('repost') || n.includes('panad') || n.includes('culinar')) {
    return `<svg viewBox="0 0 24 24" width="${size}" height="${size}" fill="currentColor"><path d="M12 3c-2.76 0-5 2.24-5 5 0 .28.03.55.08.81C5.84 9.4 5 10.6 5 12c0 1.93 1.57 3.5 3.5 3.5h7c1.93 0 3.5-1.57 3.5-3.5 0-1.4-.84-2.6-2.08-3.19.05-.26.08-.53.08-.81 0-2.76-2.24-5-5-5zM6 17h12v4H6v-4z"/></svg>`;
  }

  // 3. Belleza Integral / Estética / Peluquería / Cosmetología / Capilar
  if (k.includes('bel') || n.includes('belleza') || n.includes('estetic') || n.includes('cosmet') || n.includes('peluqu') || n.includes('capilar') || n.includes('peinado') || n.includes('manicur')) {
    return `<svg viewBox="0 0 24 24" width="${size}" height="${size}" fill="currentColor"><path d="M9.64 7.64c.23-.5.36-1.05.36-1.64 0-2.21-1.79-4-4-4S2 3.79 2 6s1.79 4 4 4c.59 0 1.14-.13 1.64-.36L10 12l-2.36 2.36C7.14 14.13 6.59 14 6 14c-2.21 0-4 1.79-4 4s1.79 4 4 4 4-1.79 4-4c0-.59-.13-1.14-.36-1.64L12 14l7 7h3v-1L9.64 7.64zM6 8c-1.1 0-2-.9-2-2s.9-2 2-2 2 .9 2 2-.9 2-2 2zm0 12c-1.1 0-2-.9-2-2s.9-2 2-2 2 .9 2 2-.9 2-2 2zm6-7.5c-.28 0-.5-.22-.5-.5s.22-.5.5-.5.5.22.5.5-.22.5-.5.5zM19 3l-6 6 2 2 7-7V3h-3z"/></svg>`;
  }

  // 4. Confección Textil / Corte y Confección / Moda / Sastrería / Prendas
  if (k.includes('tex') || n.includes('textil') || n.includes('confecc') || n.includes('corte') || n.includes('costur') || n.includes('moda') || n.includes('sastre') || n.includes('prenda')) {
    return `<svg viewBox="0 0 24 24" width="${size}" height="${size}" fill="currentColor"><path d="M12 2c-1.3 0-2.4.8-2.8 2H5L2 9l3 2v10c0 .6.4 1 1 1h12c.6 0 1-.4 1-1V11l3-2-3-5h-4.2c-.4-1.2-1.5-2-2.8-2zm0 2c.6 0 1 .4 1 1s-.4 1-1 1-1-.4-1-1 .4-1 1-1z"/></svg>`;
  }

  // 5. Secretariado Ejecutivo / Administración / Oficina / Gestión
  if (k.includes('sec') || n.includes('secreta') || n.includes('admin') || n.includes('oficin') || n.includes('ejecutiv') || n.includes('gestion')) {
    return `<svg viewBox="0 0 24 24" width="${size}" height="${size}" fill="currentColor"><path d="M20 6h-4V4c0-1.11-.89-2-2-2h-4c-1.11 0-2 .89-2 2v2H4c-1.11 0-2 .89-2 2v11c0 1.11.89 2 2 2h16c1.11 0 2-.89 2-2V8c0-1.11-.89-2-2-2zm-6 0h-4V4h4v2zm6 13H4V8h16v11z"/><rect x="8" y="10" width="8" height="3" rx="1"/></svg>`;
  }

  // 6. Agropecuaria / Agronomía / Forestal / Cultivos / Ganadería / Veterinaria
  if (k.includes('agro') || n.includes('agro') || n.includes('agric') || n.includes('pecua') || n.includes('veterin') || n.includes('suelo') || n.includes('campo') || n.includes('riego')) {
    return `<svg viewBox="0 0 24 24" width="${size}" height="${size}" fill="currentColor"><path d="M20.73 3.27a1 1 0 0 0-.95-.27C17.3 3.72 13.4 5.3 10.4 8.3c-2.45 2.45-3.86 5.6-4.04 8.95L3.4 20.2a1 1 0 0 0 1.4 1.4l2.95-2.95c3.35-.18 6.5-1.59 8.95-4.04 3-3 4.58-6.9 5.3-9.38a1 1 0 0 0-.27-.96zm-7.78 10.37c-1.95 1.95-4.4 3.12-6.95 3.36 1.05-2.3 2.5-4.35 4.25-6.1 1.75-1.75 3.8-3.2 6.1-4.25-.24 2.55-1.41 5-3.4 6.99z"/></svg>`;
  }

  // 7. Contaduría General / Contabilidad / Finanzas / Auditoría / Bancaria
  if (k.includes('conta') || n.includes('conta') || n.includes('finan') || n.includes('audit') || n.includes('tribut') || n.includes('banc')) {
    return `<svg viewBox="0 0 24 24" width="${size}" height="${size}" fill="currentColor"><path d="M19 3H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2zm-2 4H7V5h10v2zm-8 4H7V9h2v2zm4 0h-2V9h2v2zm4 0h-2V9h2v2zm-8 4H7v-2h2v2zm4 0h-2v-2h2v2zm4 0h-2v-2h2v2zm-8 4H7v-2h2v2zm4 0h-2v-2h2v2zm4 0h-2v-2h2v2z"/></svg>`;
  }

  // 8. Construcción Civil / Obras / Edificaciones / Albañilería / Hormigón
  if (k.includes('construc') || n.includes('construc') || n.includes('obra') || n.includes('edific') || n.includes('civil') || n.includes('albañil') || n.includes('suelo')) {
    return `<svg viewBox="0 0 24 24" width="${size}" height="${size}" fill="currentColor"><path d="M12 3a9 9 0 0 0-9 9c0 .7.1 1.4.3 2.1l-.8.5c-.3.2-.5.5-.5.9v1.5c0 .6.4 1 1 1h18c.6 0 1-.4 1-1V16.5c0-.4-.2-.7-.5-.9l-.8-.5c.2-.7.3-1.4.3-2.1a9 9 0 0 0-9-9zm-1 3.1h2v5.9h-2V6.1z"/></svg>`;
  }

  // 9. Electricidad Industrial / Redes Eléctricas / Energía
  if (k.includes('electri') || n.includes('electri') || n.includes('energia') || n.includes('volt')) {
    return `<svg viewBox="0 0 24 24" width="${size}" height="${size}" fill="currentColor"><path d="M7 2v11h3v9l7-12h-4l4-8z"/></svg>`;
  }

  // 10. Electromecánica / Mecánica Industrial / Tornería / Metalmecánica
  if (k.includes('electromec') || k.includes('mecanica-ind') || n.includes('electromec') || n.includes('industrial') || n.includes('torner') || n.includes('soldad')) {
    return `<svg viewBox="0 0 24 24" width="${size}" height="${size}" fill="currentColor"><path d="M19.14 12.94c.04-.3.06-.61.06-.94 0-.32-.02-.64-.07-.94l2.03-1.58c.18-.14.23-.41.12-.61l-1.92-3.32c-.12-.22-.37-.29-.59-.22l-2.39.96c-.5-.38-1.03-.7-1.62-.94l-.36-2.54c-.04-.24-.24-.41-.48-.41h-3.84c-.24 0-.43.17-.47.41l-.36 2.54c-.59.24-1.13.57-1.62.94l-2.39-.96c-.22-.08-.47 0-.59.22L2.74 8.87c-.12.21-.08.47.12.61l2.03 1.58c-.05.3-.09.63-.09.94s.02.64.07.94l-2.03 1.58c-.18.14-.23.41-.12.61l1.92 3.32c.12.22.37.29.59.22l2.39-.96c.5.38 1.03.7 1.62.94l.36 2.54c.05.24.24.41.48.41h3.84c.24 0 .44-.17.47-.41l.36-2.54c.59-.24 1.13-.56 1.62-.94l2.39.96c.22.08.47 0 .59-.22l1.92-3.32c.12-.22.07-.47-.12-.61l-2.01-1.58zM12 15.6c-1.98 0-3.6-1.62-3.6-3.6s1.62-3.6 3.6-3.6 3.6 1.62 3.6 3.6-1.62 3.6-3.6 3.6z"/></svg>`;
  }

  // 11. Electrónica / Circuitos / Robótica
  if (k.includes('electronica') || n.includes('electron') || n.includes('robot') || n.includes('circuit')) {
    return `<svg viewBox="0 0 24 24" width="${size}" height="${size}" fill="currentColor"><path d="M6 4h12v16H6z"/><path d="M4 6H2v2h2v2H2v2h2v2H2v2h2v2H2v2h2v1c0 1.1.9 2 2 2h1v2h2v-2h2v2h2v-2h2v2h2v-2h1c1.1 0 2-.9 2-2v-1h2v-2h-2v-2h2v-2h-2v-2h2v-2h-2V8h2V6h-2V5c0-1.1-.9-2-2-2h-1V1h-2v2h-2V1h-2v2h-2V1H7v2H6c-1.1 0-2 .9-2 2v1zm4 3h8v6H8V9z"/></svg>`;
  }

  // 12. Mecánica Automotriz / Autos / Motores / Vehículos
  if (k.includes('mecanica-aut') || n.includes('automot') || n.includes('auto') || n.includes('vehic') || n.includes('motor')) {
    return `<svg viewBox="0 0 24 24" width="${size}" height="${size}" fill="currentColor"><path d="M18.92 6.01C18.72 5.42 18.16 5 17.5 5h-11c-.66 0-1.21.42-1.42 1.01L3 12v8c0 .55.45 1 1 1h1c.55 0 1-.45 1-1v-1h12v1c0 .55.45 1 1 1h1c.55 0 1-.45 1-1v-8l-2.08-5.99zM6.5 16c-.83 0-1.5-.67-1.5-1.5S5.67 13 6.5 13s1.5.67 1.5 1.5S7.33 16 6.5 16zm11 0c-.83 0-1.5-.67-1.5-1.5s.67-1.5 1.5-1.5 1.5.67 1.5 1.5-.67 1.5-1.5 1.5zM5 11l1.5-4.5h11L19 11H5z"/></svg>`;
  }

  // 13. Deportes / Prácticas Deportivas / Entrenamiento
  if (k.includes('deport') || n.includes('deport') || n.includes('entrena') || n.includes('futbol') || n.includes('atlet') || n.includes('fisic')) {
    return `<svg viewBox="0 0 24 24" width="${size}" height="${size}" fill="currentColor"><path d="M19 5h-2V3H7v2H5c-1.1 0-2 .9-2 2v1c0 2.55 1.92 4.63 4.39 4.94A5.01 5.01 0 0 0 11 15.9V19H7v2h10v-2h-4v-3.1a5.01 5.01 0 0 0 3.61-2.96C19.08 12.63 21 10.55 21 8V7c0-1.1-.9-2-2-2zM5 8V7h2v3.82C5.84 10.4 5 9.3 5 8zm14 0c0 1.3-.84 2.4-2 2.82V7h2v1z"/></svg>`;
  }

  // 14. Fruticultura / Frutas / Huertos
  if (k.includes('fruti') || n.includes('fruti') || n.includes('fruta') || n.includes('huerto')) {
    return `<svg viewBox="0 0 24 24" width="${size}" height="${size}" fill="currentColor"><path d="M12 5c-1.5-2.5-4-3-4-3s.5 2.5 2 4c-3.5.5-6 3.5-6 7 0 4.5 3.5 8 8 8s8-3.5 8-8c0-3.5-2.5-6.5-6-7 1.5-1.5 2-4 2-4s-2.5.5-4 3z"/></svg>`;
  }

  // 15. Medicina Tradicional / Salud / Plantas Medicinales / Terapia
  if (k.includes('medicina') || n.includes('medicin') || n.includes('salud') || n.includes('terap') || n.includes('ancestral')) {
    return `<svg viewBox="0 0 24 24" width="${size}" height="${size}" fill="currentColor"><path d="M19 10.5V6h-4V2H9v4H5v4.5l-2 1v6c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2v-6l-2-1zM11 4h2v4h4v2h-4v4h-2v-4H7V8h4V4zm8 15H5v-4.5l1.5-.75V15h11v-1.25l1.5.75V19z"/></svg>`;
  }

  // 16. Parvularia / Infantil / Cuidado del Niño / Inicial
  if (k.includes('parvularia') || n.includes('parvula') || n.includes('infan') || n.includes('niño') || n.includes('kinder')) {
    return `<svg viewBox="0 0 24 24" width="${size}" height="${size}" fill="currentColor"><path d="M12 2c1.66 0 3 1.34 3 3s-1.34 3-3 3-3-1.34-3-3 1.34-3 3-3zm0 8c3.31 0 6 2.69 6 6v3h-3v-3c0-1.66-1.34-3-3-3s-3 1.34-3 3v3H6v-3c0-3.31 2.69-6 6-6zM4 19h16v3H4z"/></svg>`;
  }

  // 17. Turismo / Hotelería / Guía
  if (k.includes('turismo') || n.includes('turis') || n.includes('hotel') || n.includes('viaj') || n.includes('guia')) {
    return `<svg viewBox="0 0 24 24" width="${size}" height="${size}" fill="currentColor"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-1 17.93c-3.95-.49-7-3.85-7-7.93 0-.62.08-1.21.21-1.79L9 15v1c0 1.1.9 2 2 2v1.93zm6.9-2.54c-.26-.81-1-1.39-1.9-1.39h-1v-3c0-.55-.45-1-1-1H8v-2h2c.55 0 1-.45 1-1V7h2c1.1 0 2-.9 2-2v-.41c2.93 1.19 5 4.06 5 7.41 0 2.08-.8 3.97-2.1 5.39z"/></svg>`;
  }

  // 18. Viticultura y Enología / Vinos / Uva
  if (k.includes('enologia') || n.includes('vitic') || n.includes('enolog') || n.includes('vino') || n.includes('uva')) {
    return `<svg viewBox="0 0 24 24" width="${size}" height="${size}" fill="currentColor"><path d="M6 3v6c0 2.97 2.16 5.43 5 5.91V19H8v2h8v-2h-3v-4.09c2.84-.48 5-2.94 5-5.91V3H6zm10 5H8V5h8v3z"/></svg>`;
  }

  // 19. Idiomas / Lingüística
  if (n.includes('idioma') || n.includes('ingles') || n.includes('lengua')) {
    return `<svg viewBox="0 0 24 24" width="${size}" height="${size}" fill="currentColor"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-1 14h2v2h-2v-2zm1.07-7.75l-.9.92C10.45 9.9 10 10.5 10 12h2c0-.55.45-1 1-1s1 .45 1 1c0 .5-.2.96-.54 1.3L12 14.8c-.8.8-1.2 1.4-1.2 2.2h2c0-.6.3-1.1.7-1.5l1.4-1.4c.5-.5.9-1.2.9-2.1 0-1.66-1.34-3-3-3-1.2 0-2.26.7-2.73 1.75z"/></svg>`;
  }

  // 20. Artes / Diseño
  if (n.includes('arte') || n.includes('diseno') || n.includes('diseño') || n.includes('dibujo') || n.includes('pintur')) {
    return `<svg viewBox="0 0 24 24" width="${size}" height="${size}" fill="currentColor"><path d="M12 3c-4.97 0-9 4.03-9 9 0 2.12.74 4.07 1.97 5.61L4.35 19H12c4.97 0 9-4.03 9-9s-4.03-9-9-9zm-5.5 8c-.83 0-1.5-.67-1.5-1.5S5.67 8 6.5 8s1.5.67 1.5 1.5S7.33 11 6.5 11zm3-4c-.83 0-1.5-.67-1.5-1.5S8.67 4 9.5 4s1.5.67 1.5 1.5S10.33 7 9.5 7zm5 0c-.83 0-1.5-.67-1.5-1.5S13.67 4 14.5 4s1.5.67 1.5 1.5S15.33 7 14.5 7zm3 4c-.83 0-1.5-.67-1.5-1.5S16.67 8 17.5 8s1.5.67 1.5 1.5S18.33 11 17.5 11z"/></svg>`;
  }

  // 21. Default Fallback para CUALQUIER carrera creada a futuro: Emblema Técnico Oficial Sólido
  return `<svg viewBox="0 0 24 24" width="${size}" height="${size}" fill="currentColor"><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z"/></svg>`;
}

/* ─── UTILIDADES localStorage Y SINCRONIZACIÓN GLOBAL ─── */
let _aplicandoDatosRemotos = false;
let _inicializacionCompleta = false;
let _ultimaEdicionLocalTimestamp = 0;
let _timerSyncGlobalCEA = null;
let _timerSyncMatrizCEA = null;

function lsGet(key, def) {
  try { const v = localStorage.getItem(key); return v !== null ? JSON.parse(v) : def; }
  catch(e) { return def; }
}

function lsSet(key, val) {
  try { localStorage.setItem(key, JSON.stringify(val)); } catch(e) {}
  if (!_aplicandoDatosRemotos && _inicializacionCompleta && typeof key === 'string' && key.startsWith('cea_')) {
    const kIgnore = ['cea_session', 'cea_gsheet_url', 'cea_visitas', 'cea_dark_override', 'cea_inscripciones'];
    if (!kIgnore.includes(key)) {
      _ultimaEdicionLocalTimestamp = Date.now();
      programarSincronizacionGlobalCEA(key);
    }
  }
}

const CLAVES_EXCLUIDAS_CONFIG_GLOBAL = new Set([
  'cea_session',
  'cea_gsheet_url',
  'cea_inscripciones',
  'cea_visitas',
  'cea_actividades',
  'cea_galeria_fotos',
  'cea_mensajes_contacto',
  'cea_dark_override',
  'cea_fotos_oferta'
]);

function empaquetarConfiguracionGlobalCEA() {
  const cfg = {};
  try {
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (!k || !k.startsWith('cea_') || CLAVES_EXCLUIDAS_CONFIG_GLOBAL.has(k)) continue;
      // Las matrices completas de horarios se sincronizan en su clave dedicada horarios_matriz_json
      if (k.startsWith('cea_horarios_matriz')) continue;
      const raw = localStorage.getItem(k);
      if (!raw || raw.length > 15000 || raw.includes('data:image')) continue;
      try {
        cfg[k] = JSON.parse(raw);
      } catch (eParse) {
        cfg[k] = raw;
      }
    }
  } catch (e) {
    console.warn('Error empaquetando configuración global CEA:', e);
  }
  return cfg;
}

function aplicarEstilosGestorHorario() {
  try {
    const st = lsGet('cea_gestor_app_state', null);
    if (st && typeof st === 'object') {
      if (typeof appStateGestor === 'object' && appStateGestor !== null) {
        Object.assign(appStateGestor, st);
      }
      const colHeader = (st.colores && st.colores.header) || st.colorHeader;
      const colHeaderTxt = (st.colores && st.colores.headerTxt) || st.colorHeaderTxt;
      const colDias = (st.colores && st.colores.dias) || st.colorDias;
      const colDiasTxt = (st.colores && st.colores.diasTxt) || st.colorDiasTxt;
      const colLineas = (st.colores && st.colores.lineas) || st.colorLineas;

      if (colHeader) {
        document.documentElement.style.setProperty('--color-header', colHeader);
        const pk = document.getElementById('picker-color-encabezados-horario');
        if (pk) pk.value = colHeader;
      }
      if (colHeaderTxt) {
        document.documentElement.style.setProperty('--color-header-txt', colHeaderTxt);
      }
      if (colDias) {
        document.documentElement.style.setProperty('--color-dias', colDias);
      }
      if (colDiasTxt) {
        document.documentElement.style.setProperty('--color-dias-txt', colDiasTxt);
        const pkTxt = document.getElementById('picker-color-texto-dias-horario');
        if (pkTxt) pkTxt.value = colDiasTxt;
      }
      if (colLineas) {
        document.documentElement.style.setProperty('--color-lineas', colLineas);
      }
      if (st.titulo && typeof HORARIOS_BTH_CANONICO !== 'undefined') {
        HORARIOS_BTH_CANONICO.titulo = st.titulo;
      }
      if (st.especialidad && typeof HORARIOS_BTH_CANONICO !== 'undefined') {
        HORARIOS_BTH_CANONICO.subtitulo = st.especialidad;
      }
    }
    const selPaleta = document.getElementById('select-paleta-colores-horario');
    if (selPaleta) {
      selPaleta.value = lsGet('cea_horario_paleta_colores', 'institucional');
    }
    const chkDocentes = document.getElementById('chk-mostrar-docentes-horario');
    if (chkDocentes) {
      chkDocentes.checked = lsGet('cea_horario_mostrar_docentes', true) !== false;
    }
    const chkTurnos = document.getElementById('chk-mostrar-turnos-horario');
    if (chkTurnos) {
      chkTurnos.checked = lsGet('cea_horario_mostrar_turnos', true) !== false;
    }
    const chkLineas = document.getElementById('chk-lineas-impresion-horario');
    if (chkLineas) {
      chkLineas.checked = lsGet('cea_horario_imprimir_lineas', true) !== false;
    }
  } catch (e) {
    console.warn('Error aplicando estilos del gestor de horarios:', e);
  }
}

function aplicarConfiguracionGlobalCEA(cfg) {
  if (!cfg || typeof cfg !== 'object') return;
  const prevFlag = _aplicandoDatosRemotos;
  _aplicandoDatosRemotos = true;
  try {
    Object.keys(cfg).forEach(k => {
      if (!k.startsWith('cea_') || CLAVES_EXCLUIDAS_CONFIG_GLOBAL.has(k)) return;
      if (cfg[k] !== undefined && cfg[k] !== null) {
        try {
          localStorage.setItem(k, JSON.stringify(cfg[k]));
        } catch (eSet) {}
      }
    });
    aplicarEstilosGestorHorario();
  } finally {
    _aplicandoDatosRemotos = prevFlag;
  }
}

function programarSincronizacionGlobalCEA(changedKey) {
  const session = lsGet('cea_session', null);
  const tienePermiso = session && (session.role === 'director' || session.role === 'admin' || session.role === 'comision' || session.role === 'docente' || session.loggedIn === true);
  if (!tienePermiso) return;

  if (changedKey && (changedKey.startsWith('cea_horarios_matriz') || changedKey.startsWith('cea_horarios_merges'))) {
    if (_timerSyncMatrizCEA) clearTimeout(_timerSyncMatrizCEA);
    _timerSyncMatrizCEA = setTimeout(() => {
      try {
        const hMatriz = typeof getSedeLsData === 'function'
          ? getSedeLsData('cea_horarios_matriz', typeof HORARIOS_MATRIZ_DEFAULT !== 'undefined' ? HORARIOS_MATRIZ_DEFAULT : {})
          : lsGet('cea_horarios_matriz', {});
        const hMerges = typeof getSedeLsData === 'function'
          ? getSedeLsData('cea_horarios_merges', {})
          : lsGet('cea_horarios_merges', {});
        enviarGoogleSheet({
          action: 'guardar-horarios-matriz',
          sede: typeof getHorarioSedeActiveKey === 'function' ? getHorarioSedeActiveKey() : 'central',
          horariosMatriz: hMatriz,
          horariosMerges: hMerges
        });
      } catch (eMat) {}
    }, 500);
  }

  if (_timerSyncGlobalCEA) clearTimeout(_timerSyncGlobalCEA);
  _timerSyncGlobalCEA = setTimeout(() => {
    sincronizarConfigGlobalCEA();
  }, 600);
}

async function sincronizarConfigGlobalCEA() {
  const session = lsGet('cea_session', null);
  const tienePermiso = session && (session.role === 'director' || session.role === 'admin' || session.role === 'comision' || session.role === 'docente' || session.loggedIn === true);
  if (!tienePermiso) return false;
  try {
    const cfg = empaquetarConfiguracionGlobalCEA();
    const jsonStr = JSON.stringify(cfg);
    await enviarGoogleSheet({
      action: 'guardar-contenido-vivo',
      key: 'config_global_cea_json',
      valor: jsonStr,
      htmlValor: jsonStr
    });
    return true;
  } catch (e) {
    console.warn('Error sincronizando config_global_cea_json:', e);
    return false;
  }
}

/* ─── GOOGLE SHEETS INTEGRACIÓN OFICIAL ─── */
const GOOGLE_SCRIPT_URL = 'https://script.google.com/macros/s/AKfycbxSBubRVsq8_Qk-kg_69_7Bb6796F63PgF0KDeWXyCsNHRDTN9uKUFymCi6FL9BGiYk/exec';
let GOOGLE_SHEET_WEB_APP_URL = GOOGLE_SCRIPT_URL;

// Actualizar automáticamente si tiene la URL anterior o está desactualizada
try {
  const cachedUrl = lsGet('cea_gsheet_url', '');
  if (!cachedUrl || cachedUrl.includes('AKfycbxJ87VDzK') || cachedUrl !== GOOGLE_SCRIPT_URL) {
    lsSet('cea_gsheet_url', GOOGLE_SCRIPT_URL);
    GOOGLE_SHEET_WEB_APP_URL = GOOGLE_SCRIPT_URL;
  } else {
    GOOGLE_SHEET_WEB_APP_URL = cachedUrl;
  }
} catch (eUrlInit) {
  GOOGLE_SHEET_WEB_APP_URL = GOOGLE_SCRIPT_URL;
}

function obtenerGoogleSheetURL() {
  const urlLocal = lsGet('cea_gsheet_url', '');
  if (urlLocal && urlLocal.includes('script.google.com') && !urlLocal.includes('AKfycbxJ87VDzK')) {
    return urlLocal;
  }
  return GOOGLE_SCRIPT_URL;
}

function getSession() {
  return lsGet('cea_session', null);
}

function getSessionToken() {
  const s = getSession();
  return s ? (s.token || '') : '';
}

async function sincronizarInscripcionesProtegidas() {
  const session = getSession();
  if (!session || (session.role !== 'director' && session.role !== 'admin')) return;
  const token = session.token;
  const url = obtenerGoogleSheetURL();
  if (!url || !token) return;

  try {
    const resp = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'text/plain;charset=utf-8' },
      body: JSON.stringify({ action: 'obtenerInscripciones', token: token })
    });
    const res = await resp.json();
    if (res && res.status === 'success' && Array.isArray(res.inscripciones)) {
      const prev = _aplicandoDatosRemotos;
      _aplicandoDatosRemotos = true;
      lsSet('cea_inscripciones', res.inscripciones);
      _aplicandoDatosRemotos = prev;
      cargarInscripciones();
      if (typeof actualizarEstadisticasAdmin === 'function') actualizarEstadisticasAdmin();
    }
  } catch (err) {
    console.warn('Sincronización de inscripciones protegidas:', err);
  }
}

async function enviarGoogleSheet(datos) {
  const url = obtenerGoogleSheetURL();
  if (!url) return false;
  try {
    if (!datos || datos.action !== 'visita') {
      _ultimaEdicionLocalTimestamp = Date.now();
    }
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 25000); // 25 segundos máximo

    const payload = (typeof datos === 'object' && datos !== null) ? { ...datos } : { payload: datos };
    const token = getSessionToken();
    if (token && !payload.token) {
      payload.token = token;
    }

    await fetch(url, {
      method: 'POST',
      mode: 'no-cors',
      headers: { 'Content-Type': 'text/plain;charset=utf-8' },
      body: JSON.stringify(payload),
      signal: controller.signal
    });

    clearTimeout(timeoutId);
    return true;
  } catch (err) {
    console.warn('Respuesta de Google Sheets continuará en segundo plano:', err);
    return true; // Retornar true para no bloquear la interfaz web
  }
}

function guardarGoogleSheetURL() {
  const inp = document.getElementById('adm-gsheet-url');
  if (!inp) return;
  const url = inp.value.trim();
  lsSet('cea_gsheet_url', url);
  GOOGLE_SHEET_WEB_APP_URL = url;
  mostrarMsg('msg-gsheet-config', 'URL de sincronización guardada correctamente.', 'success');
  if (url) {
    cargarDatosGoogleSheets(true);
  }
}

async function probarConexionGoogleSheet() {
  const url = obtenerGoogleSheetURL();
  if (!url) {
    mostrarMsg('msg-gsheet-config', 'Por favor ingresa primero una URL válida.', 'error');
    return;
  }
  mostrarMsg('msg-gsheet-config', 'Conectando con el servidor en línea...', 'success');
  try {
    const fetchUrl = url + (url.includes('?') ? '&' : '?') + '_t=' + Date.now();
    const resp = await fetch(fetchUrl);
    const json = await resp.json();
    if (json && json.status === 'success') {
      mostrarMsg('msg-gsheet-config', '¡Conexión exitosa! Los datos se sincronizaron con el sistema.', 'success');
      aplicarDatosGoogleSheets(json.data);
    } else {
      mostrarMsg('msg-gsheet-config', 'Respuesta recibida pero con error: ' + (json.message || 'Error desconocido'), 'error');
    }
  } catch (err) {
    mostrarMsg('msg-gsheet-config', 'Error de conexión: Verifica que el script esté publicado como Aplicación Web para "Cualquier persona".', 'error');
  }
}

async function cargarDatosGoogleSheets(forzar = false) {
  const url = obtenerGoogleSheetURL();
  if (!url) return;
  // Evitar que una lectura automática pise cambios locales que aún se están guardando en Google Sheets
  if (!forzar && _ultimaEdicionLocalTimestamp && (Date.now() - _ultimaEdicionLocalTimestamp < 10000)) {
    return;
  }
  try {
    const fetchUrl = url + (url.includes('?') ? '&' : '?') + '_t=' + Date.now();
    const resp = await fetch(fetchUrl);
    const json = await resp.json();
    if (json && json.status === 'success' && json.data) {
      if (!forzar && _ultimaEdicionLocalTimestamp && (Date.now() - _ultimaEdicionLocalTimestamp < 10000)) {
        return;
      }
      aplicarDatosGoogleSheets(json.data);
    }
  } catch (e) {
    console.log('Google Sheets no disponible offline o error en URL. Usando caché local.');
  }
}

function aplicarDatosGoogleSheets(data) {
  if (!data) return;
  const prevRemoteFlag = _aplicandoDatosRemotos;
  _aplicandoDatosRemotos = true;

  try {
    // 0. Restaurar paquete completo de configuración global (colores, diseño de horario, paletas, periodos, etc.)
    if (data.textos && data.textos.config_global_cea_json) {
      try {
        const cfgGlobal = typeof data.textos.config_global_cea_json === 'string'
          ? JSON.parse(data.textos.config_global_cea_json)
          : data.textos.config_global_cea_json;
        if (cfgGlobal && typeof cfgGlobal === 'object') {
          aplicarConfiguracionGlobalCEA(cfgGlobal);
        }
      } catch (eCfg) {
        console.warn('Error al parsear config_global_cea_json:', eCfg);
      }
    }

    // 1. Textos & Director
    if (data.textos) {
      const t = data.textos;

      // Restaurar colores individuales de materias si existen en textos
      const customColors = lsGet('cea_colores_materias_personalizados', {});
      let colorMateriaCambio = false;
      Object.keys(t).forEach(k => {
        if (k.startsWith('color_materia_') && t[k]) {
          const matKey = k.replace('color_materia_', '').trim();
          if (matKey) {
            let valColor = t[k];
            if (typeof valColor === 'string' && valColor.startsWith('{')) {
              try { valColor = JSON.parse(valColor); } catch(eParse) {}
            }
            customColors[matKey] = valColor;
            colorMateriaCambio = true;
          }
        }
      });
      if (colorMateriaCambio) {
        lsSet('cea_colores_materias_personalizados', customColors);
      }

      if (t.gestor_app_state_json) {
        try {
          const stParsed = JSON.parse(t.gestor_app_state_json);
          if (stParsed && typeof stParsed === 'object') {
            lsSet('cea_gestor_app_state', stParsed);
            if (typeof appStateGestor !== 'undefined') {
              appStateGestor = Object.assign({}, appStateGestor, stParsed);
            }
          }
        } catch (eSt) {}
      }
      if (t.horario_paleta_colores) {
        lsSet('cea_horario_paleta_colores', t.horario_paleta_colores);
        const selPal = document.getElementById('sel-paleta-colores-horario');
        if (selPal) selPal.value = t.horario_paleta_colores;
      }
      if (t.bth_dias_activos_json) {
        try {
          const diasParsed = JSON.parse(t.bth_dias_activos_json);
          if (Array.isArray(diasParsed)) setSedeLsData('cea_bth_dias_activos', diasParsed);
        } catch(e) {}
      }
      if (t.tec_dias_activos_json) {
        try {
          const diasTecParsed = JSON.parse(t.tec_dias_activos_json);
          if (Array.isArray(diasTecParsed)) setSedeLsData('cea_tec_dias_activos', diasTecParsed);
        } catch(e) {}
      }
      if (t.hum_modo_dia_json) {
        try {
          const modoHum = JSON.parse(t.hum_modo_dia_json);
          if (typeof modoHum === 'object') lsSet('cea_hum_modo_dia', modoHum);
        } catch(e) {}
      }
      if (t.tec_modo_dia_json) {
        try {
          const modoTec = JSON.parse(t.tec_modo_dia_json);
          if (typeof modoTec === 'object') lsSet('cea_tec_modo_dia', modoTec);
        } catch(e) {}
      }
      if (t.bth_cursos_por_dia_json) {
        try {
          const cursosParsed = JSON.parse(t.bth_cursos_por_dia_json);
          if (typeof cursosParsed === 'object') setSedeLsData('cea_bth_cursos_por_dia', cursosParsed);
        } catch(e) {}
      }

      const tDir = lsGet('cea_textos_director', {});
      if (t.director_nombre) {
        tDir.director_nombre = t.director_nombre;
        const el = document.getElementById('display-director-nombre');
        if (el) el.textContent = t.director_nombre;
      }
      if (t.director_titulo) {
        tDir.director_titulo = t.director_titulo;
        const el = document.getElementById('display-director-titulo');
        if (el) el.textContent = t.director_titulo;
      }
      if (t.director_telefono && !String(t.director_telefono).includes('ERROR')) {
        const telLimpio = String(t.director_telefono).replace(/^[`']/, '').trim();
        tDir.director_telefono = telLimpio;
        const el = document.getElementById('display-director-tel');
        const link = document.getElementById('display-director-tel-link');
        if (el) el.textContent = telLimpio;
        if (link) link.href = 'tel:' + telLimpio.replace(/[^\d+]/g, '');
      }
      if (t.director_correo) {
        tDir.director_correo = t.director_correo;
        const el = document.getElementById('display-director-correo');
        const link = document.getElementById('display-director-mail-link');
        if (el) el.textContent = t.director_correo;
        if (link) link.href = 'mailto:' + String(t.director_correo).trim();
      }
      lsSet('cea_textos_director', tDir);

      const c = lsGet('cea_contenido', CONTENIDO_DEFAULT);
      if (t.bienvenida_texto) c.bienvenida = t.bienvenida_texto;
      if (t.bienvenida_titulo) c.bienvenida_titulo = t.bienvenida_titulo;
      if (t.hero_titulo) c.hero_titulo = t.hero_titulo;
      if (t.hero_subtitulo) c.hero_subtitulo = t.hero_subtitulo;
      if (t.oferta_desc) c.oferta_desc = t.oferta_desc;
      if (t.humanistica_texto) c.humanistica = t.humanistica_texto;
      if (t.tecnica_texto) c.tecnica = t.tecnica_texto;
      lsSet('cea_contenido', c);
      cargarContenido();

      // Sincronizar títulos de horarios si fueron editados en vivo
      const titHorarios = lsGet('cea_titulos_horarios', {});
      let titHorariosCambio = false;
      if (t.horario_hum_nombre) { titHorarios.hum_nombre = t.horario_hum_nombre; titHorariosCambio = true; }
      if (t.horario_hum_badge) { titHorarios.hum_badge = t.horario_hum_badge; titHorariosCambio = true; }
      if (t.horario_hum_turno) { titHorarios.hum_turno = t.horario_hum_turno; titHorariosCambio = true; }
      if (t.horario_tec_nombre) { titHorarios.tec_nombre = t.horario_tec_nombre; titHorariosCambio = true; }
      if (t.horario_tec_badge) { titHorarios.tec_badge = t.horario_tec_badge; titHorariosCambio = true; }
      if (t.horario_tec_turno) { titHorarios.tec_turno = t.horario_tec_turno; titHorariosCambio = true; }
      if (titHorariosCambio) {
        lsSet('cea_titulos_horarios', titHorarios);
        if (typeof cargarTitulosHorarios === 'function') cargarTitulosHorarios();
      }

      // Actualizar todos los elementos editables en vivo (incluyendo secciones directas) si vienen desde Sheet
      const todosTargets = [
        ...(typeof TARGETS_EDICION_DIRECTOR !== 'undefined' ? TARGETS_EDICION_DIRECTOR : []),
        ...(typeof TARGETS_SECCIONES_DIRECTAS !== 'undefined' ? TARGETS_SECCIONES_DIRECTAS : [])
      ];
      if (todosTargets.length > 0) {
        const textosVivos = lsGet('cea_textos_vivos', {});
        todosTargets.forEach(item => {
          if (t[item.key] !== undefined && t[item.key] !== '') {
            textosVivos[item.key] = t[item.key];
            const el = document.getElementById(item.id);
            if (el && (typeof elementoEditandoActivo === 'undefined' || elementoEditandoActivo !== item.id)) {
              if (item.type === 'html') el.innerHTML = t[item.key];
              else el.textContent = t[item.key];
            }
          }
        });
        lsSet('cea_textos_vivos', textosVivos);
      }

      if (t.cfg_habilitar_pdf !== undefined) {
        lsSet('cea_cfg_pdf', String(t.cfg_habilitar_pdf) !== 'false');
      }
      if (t.cfg_habilitar_whatsapp !== undefined) {
        lsSet('cea_cfg_whatsapp', String(t.cfg_habilitar_whatsapp) !== 'false');
      }
      actualizarSwitchesConfig();

      // Sincronizar Horarios de Atención desde Sheet
      if (t.horarios_atencion_dia_hum || t.horarios_atencion_hora_hum || t.horarios_atencion_dia_tec || t.horarios_atencion_hora_tec) {
        const h = obtenerHorariosAtencion();
        if (t.horarios_atencion_dia_hum) h.diaHum = t.horarios_atencion_dia_hum;
        if (t.horarios_atencion_hora_hum) h.horaHum = t.horarios_atencion_hora_hum;
        if (t.horarios_atencion_dia_tec) h.diaTec = t.horarios_atencion_dia_tec;
        if (t.horarios_atencion_hora_tec) h.horaTec = t.horarios_atencion_hora_tec;
        lsSet('cea_horarios_atencion', h);
        cargarHorariosAtencion();
      }

      // Sincronizar Días Oficiales de Clases desde Sheet
      if (t.dias_clase_hum || t.dias_clase_tec) {
        const d = obtenerDiasClases();
        if (t.dias_clase_hum) d.hum = t.dias_clase_hum;
        if (t.dias_clase_tec) d.tec = t.dias_clase_tec;
        lsSet('cea_dias_clase', d);
        cargarDiasClases();
      }

      // Sincronizar Fechas Límite de Inscripción desde Sheet
      if (t.insc_sem1_fin || t.insc_sem2_fin || t.insc_gestion) {
        const f = obtenerFechasLimiteInscripcion();
        if (t.insc_gestion) f.gestion = parseInt(t.insc_gestion, 10);
        if (t.insc_sem1_inicio) f.semestre1_inicio = t.insc_sem1_inicio;
        if (t.insc_sem1_fin) f.semestre1_fin = t.insc_sem1_fin;
        if (t.insc_sem1_clases) f.semestre1_clases = t.insc_sem1_clases;
        if (t.insc_sem2_inicio) f.semestre2_inicio = t.insc_sem2_inicio;
        if (t.insc_sem2_fin) f.semestre2_fin = t.insc_sem2_fin;
        if (t.insc_sem2_clases) f.semestre2_clases = t.insc_sem2_clases;
        lsSet('cea_fechas_limite_inscripcion', f);
        cargarFechasLimiteInscripcion();
      }
    }

    // 2. Docentes
    if (data.docentes && typeof data.docentes === 'object' && Object.keys(data.docentes).length > 0) {
      lsSet('cea_docentes', data.docentes);
      cargarDocentes();
      if (typeof cargarDocentesUnificados === 'function') cargarDocentesUnificados();
    if (typeof refrescarCredencialesDocentesDesdeServidor === 'function') refrescarCredencialesDocentesDesdeServidor();
    }

    // 3. Carreras Técnicas
    if (data.carreras && Array.isArray(data.carreras) && data.carreras.length > 0) {
      const areasLocales = lsGet('cea_areas_tec', AREAS_TEC_DEFAULT);
      const nuevasCarreras = data.carreras.map(carrSheet => {
        const existing = areasLocales.find(a => a.key === carrSheet.key) || {};
        let malla = existing.malla || [];
        if (data.mallas && data.mallas[carrSheet.key]) {
          const mallaObj = data.mallas[carrSheet.key];
          malla = Object.keys(mallaObj).map(nivelName => ({
            nivel: nivelName,
            modulos: mallaObj[nivelName]
          }));
        }
        return {
          key: carrSheet.key,
          nombre: carrSheet.nombre || existing.nombre || 'Carrera Técnica',
          docente: carrSheet.docente || existing.docente || carrSheet.key,
          color: carrSheet.color || existing.color || '#1a6b2e',
          resumen: carrSheet.resumen || existing.resumen || '',
          malla: malla
        };
      });

      lsSet('cea_areas_tec', nuevasCarreras);
      cargarAreasTec();
    }

    // 4. Materias Humanística
    if (data.materiasHumanistica && Array.isArray(data.materiasHumanistica) && data.materiasHumanistica.length > 0) {
      const listaMat = data.materiasHumanistica.map(m => m.materia);
      lsSet('cea_materias_hum', listaMat);
      cargarMaterias();
    }

    // 5. Documentos (normalizando desc/descripcion y url/enlace)
    if (data.documentos && Array.isArray(data.documentos) && data.documentos.length > 0) {
      const docsNormalizados = data.documentos.map((doc, idx) => ({
        ...doc,
        id: doc.id || doc.key || ('doc-item-' + idx),
        key: doc.key || doc.id || ('doc-item-' + idx),
        titulo: doc.titulo || 'Documento Institucional',
        desc: doc.desc || doc.descripcion || '',
        descripcion: doc.descripcion || doc.desc || '',
        url: doc.url || doc.enlace || '#',
        enlace: doc.enlace || doc.url || '#',
        botonTexto: doc.botonTexto || 'Ver / Descargar'
      }));

      const d = lsGet('cea_drive', DRIVE_DEFAULT);
      let driveCambio = false;
      docsNormalizados.forEach(doc => {
        const key = String(doc.key || doc.titulo || '').toLowerCase();
        if (key.includes('reglamento') && doc.enlace && doc.enlace !== '#') { d.reglamento = doc.enlace; driveCambio = true; }
        else if (key.includes('formulario') && doc.enlace && doc.enlace !== '#') { d.formulario = doc.enlace; driveCambio = true; }
        else if (key.includes('malla') && doc.enlace && doc.enlace !== '#') { d.mallas = doc.enlace; driveCambio = true; }
        else if (key.includes('calendario') && doc.enlace && doc.enlace !== '#') { d.calendario = doc.enlace; driveCambio = true; }
      });
      if (driveCambio) {
        lsSet('cea_drive', d);
        cargarDrive();
      }

      lsSet('cea_documentos_dinamicos', docsNormalizados);
      if (typeof renderDocumentosDinamicos === 'function') renderDocumentosDinamicos();
      if (typeof cargarDocumentosOficialesAdmin === 'function') cargarDocumentosOficialesAdmin();

      const docsGrid = document.getElementById('docs-grid-display');
      if (docsGrid) {
        const defaultIcon = `<svg class="svg-icon" viewBox="0 0 24 24" width="32" height="32" fill="none" stroke="currentColor"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg>`;
        docsGrid.innerHTML = docsNormalizados.map(doc => `
          <div class="doc-card">
            <div class="doc-icon">${doc.icono && !doc.icono.match(/[\u{1F300}-\u{1F9FF}]/u) ? doc.icono : defaultIcon}</div>
            <h4>${doc.titulo}</h4>
            <p>${doc.descripcion || ''}</p>
            <a href="${doc.enlace || '#'}" class="btn-download" target="_blank" rel="noopener">${doc.botonTexto || 'Ver / Descargar'}</a>
          </div>
        `).join('');
      }
    }

    // 5.1 Sincronización de Sedes / Subcentros desde Google Sheets
    if (data.textos) {
      const t = data.textos;
      if (t.sedes_lista_hum_json) {
        try {
          const sHum = JSON.parse(t.sedes_lista_hum_json);
          if (Array.isArray(sHum) && sHum.length > 0) {
            lsSet('cea_sedes_lista_hum', sHum);
            lsSet('cea_sedes_lista', sHum);
          }
        } catch (eSHum) {}
      } else if (data.sedesHum && Array.isArray(data.sedesHum) && data.sedesHum.length > 0) {
        lsSet('cea_sedes_lista_hum', data.sedesHum);
        lsSet('cea_sedes_lista', data.sedesHum);
      }

      if (t.sedes_lista_tec_json) {
        try {
          const sTec = JSON.parse(t.sedes_lista_tec_json);
          if (Array.isArray(sTec) && sTec.length > 0) {
            lsSet('cea_sedes_lista_tec', sTec);
          }
        } catch (eSTec) {}
      } else if (data.sedesTec && Array.isArray(data.sedesTec) && data.sedesTec.length > 0) {
        lsSet('cea_sedes_lista_tec', data.sedesTec);
      }
    }

    // 6. Horarios Matriz (Priorizar filas reales de Google Sheets data.horariosMatriz)
    let matrizFinal = null;
    if (data.horariosMatriz && typeof data.horariosMatriz === 'object' && Object.keys(data.horariosMatriz).length > 0) {
      matrizFinal = data.horariosMatriz;
    } else if (data.textos && data.textos.horarios_matriz_json) {
      try {
        matrizFinal = JSON.parse(data.textos.horarios_matriz_json);
      } catch (eMatJson) {}
    }

    // Sincronizar Horarios Matriz para TODAS las sedes y subcentros
    if (data.horariosMatrizPorSede && typeof data.horariosMatrizPorSede === 'object' && Object.keys(data.horariosMatrizPorSede).length > 0) {
      Object.keys(data.horariosMatrizPorSede).forEach(sKey => {
        const matSede = data.horariosMatrizPorSede[sKey];
        if (matSede && typeof matSede === 'object') {
          setSedeLsData('cea_horarios_matriz', matSede, sKey, 'hum');
          setSedeLsData('cea_horarios_matriz', matSede, sKey, 'tec');
          if (sKey === 'central') {
            matrizFinal = matSede;
            lsSet('cea_horarios_matriz', matSede);
            lsSet('cea_horarios_matriz_central', matSede);
            lsSet('cea_horarios_matriz_central_hum', matSede);
            lsSet('cea_horarios_matriz_central_tec', matSede);
          }
        }
      });
    }

    let mergesFinal = null;
    if (data.textos && data.textos.horarios_merges_json) {
      try {
        mergesFinal = JSON.parse(data.textos.horarios_merges_json);
      } catch (eMrgJson) {}
    }
    if (!mergesFinal && data.horariosMerges && typeof data.horariosMerges === 'object') {
      mergesFinal = data.horariosMerges;
    }

    aplicarEstilosGestorHorario();

    if (matrizFinal && typeof matrizFinal === 'object') {
      lsSet('cea_horarios_matriz', matrizFinal);
      lsSet('cea_horarios_matriz_hum', matrizFinal);
      lsSet('cea_horarios_matriz_tec', matrizFinal);
      lsSet('cea_horarios_matriz_central', matrizFinal);
      lsSet('cea_horarios_matriz_central_hum', matrizFinal);
      lsSet('cea_horarios_matriz_central_tec', matrizFinal);
      if (mergesFinal && typeof mergesFinal === 'object') {
        lsSet('cea_horarios_merges', mergesFinal);
        lsSet('cea_horarios_merges_hum', mergesFinal);
        lsSet('cea_horarios_merges_tec', mergesFinal);
        lsSet('cea_horarios_merges_central', mergesFinal);
        lsSet('cea_horarios_merges_central_hum', mergesFinal);
        lsSet('cea_horarios_merges_central_tec', mergesFinal);
      }
      if (typeof renderizarBarraSedesHorarios === 'function') renderizarBarraSedesHorarios();
      cargarHorariosMatriz(typeof turnoHorarioActual !== 'undefined' ? turnoHorarioActual : 'hum');
      cargarEditorHorariosMatriz();
    } else if (data.horarios && typeof data.horarios === 'object') {
      if ((data.horarios.hum && data.horarios.hum.length) || (data.horarios.tec && data.horarios.tec.length)) {
        lsSet('cea_horarios_v2', data.horarios);
        cargarHorarios();
      }
    } else {
      if (typeof renderizarBarraSedesHorarios === 'function') renderizarBarraSedesHorarios();
      cargarHorariosMatriz(typeof turnoHorarioActual !== 'undefined' ? turnoHorarioActual : 'hum');
    }

    // 7. Usuarios Docentes (Mezcla segura para preservar contraseñas y comisiones en el dispositivo)
    if (data.usuariosDocentes && Object.keys(data.usuariosDocentes).length > 0) {
      const haEditadoRecientemente = _ultimaEdicionLocalTimestamp && (Date.now() - _ultimaEdicionLocalTimestamp < 60000);
      const actual = lsGet('cea_usuarios_docentes', typeof USUARIOS_DOCENTES_DEFAULT !== 'undefined' ? USUARIOS_DOCENTES_DEFAULT : {});
      const merged = { ...actual };
      Object.keys(data.usuariosDocentes).forEach(k => {
        const remoteUser = data.usuariosDocentes[k].user;
        const remoteComision = data.usuariosDocentes[k].comision;
        const defPass = (typeof USUARIOS_DOCENTES_DEFAULT !== 'undefined' && USUARIOS_DOCENTES_DEFAULT[k]?.pass) || 'docente123';
        merged[k] = {
          ...(merged[k] || {}),
          user: (!haEditadoRecientemente && remoteUser !== undefined) ? remoteUser : (merged[k]?.user || remoteUser || ''),
          pass: merged[k]?.pass || defPass,
          comision: (!haEditadoRecientemente && remoteComision !== undefined) ? remoteComision : (merged[k]?.comision || remoteComision || false)
        };
      });
      lsSet('cea_usuarios_docentes', merged);
      if (typeof cargarUsuariosPanel === 'function') cargarUsuariosPanel();
  if (typeof refrescarCredencialesDocentesDesdeServidor === 'function') refrescarCredencialesDocentesDesdeServidor();
    }

    // 8. Enlaces Drive y configuración institucional
    if (data.textos) {
      const d = lsGet('cea_drive', DRIVE_DEFAULT);
      let driveCambio = false;
      ['reglamento','formulario','mallas','calendario'].forEach(k => {
        if (data.textos['drive_' + k]) {
          d[k] = data.textos['drive_' + k];
          driveCambio = true;
        }
      });
      if (driveCambio) {
        lsSet('cea_drive', d);
        cargarDrive();
      }
      if (data.textos.bth_carrera_activa) {
        lsSet('cea_bth_carrera_activa', data.textos.bth_carrera_activa);
      }
      if (data.textos.bth_filas_humanistica) {
        try {
          const parsed = JSON.parse(data.textos.bth_filas_humanistica);
          if (Array.isArray(parsed) && parsed.length === 4) {
            lsSet('cea_bth_filas_humanistica', parsed);
          }
        } catch (eFilas) {}
      }
    }

    // 9. Visitas Globales (EXCLUSIVAMENTE desde Google Sheets para consistencia multi-dispositivo)
    if (data.visitas && typeof data.visitas === 'object') {
      lsSet('cea_visitas_gsheet', data.visitas);
      lsSet('cea_visitas', data.visitas);
      actualizarContadorVisitasMinimal();
      renderTablaVisitas();
    }

    // 10. Documentos por Nivel, Actividades e Inscripciones desde Google Sheets
    if (data.docNiveles && typeof data.docNiveles === 'object') {
      Object.keys(data.docNiveles).forEach(carrKey => {
        lsSet('cea_doc_niveles_' + carrKey, data.docNiveles[carrKey]);
      });
      if (typeof renderSeccionHumanistica === 'function') renderSeccionHumanistica();
    }
    if (data.actividades && Array.isArray(data.actividades)) {
      lsSet('cea_actividades', data.actividades);
      renderFeedActividades();
      renderListaActividadesAdmin();
    }
    if (data.inscripciones && Array.isArray(data.inscripciones)) {
      lsSet('cea_inscripciones', data.inscripciones);
      cargarInscripciones();
      if (typeof actualizarEstadisticasAdmin === 'function') actualizarEstadisticasAdmin();
      if (typeof revalidarQRPendiente === 'function') revalidarQRPendiente();
    }
    if (data.galeriaFotos && Array.isArray(data.galeriaFotos)) {
      lsSet('cea_galeria_fotos', data.galeriaFotos);
      if (typeof cargarGaleriaFotos === 'function') cargarGaleriaFotos();
    }

    // 11. Calendario Académico y Niveles EPJA
    if (data.calendario && Array.isArray(data.calendario) && data.calendario.length > 0) {
      const anioActual = new Date().getFullYear();
      lsSet('cea_calendario_' + anioActual, data.calendario);
      if (typeof actualizarVistaCalendario === 'function') actualizarVistaCalendario(anioActual);
    }
    if (data.epjaNiveles && Array.isArray(data.epjaNiveles) && data.epjaNiveles.length > 0) {
      lsSet('cea_epja_niveles', data.epjaNiveles);
      if (typeof renderTablaEpjaNiveles === 'function') renderTablaEpjaNiveles();
    }
    if (data.humanistica && typeof data.humanistica === 'object') {
      lsSet('cea_humanistica_data', data.humanistica);
      if (typeof renderSeccionHumanistica === 'function') renderSeccionHumanistica();
    }

    // 12. Listas Dinámicas: Carreras, Requisitos, Casos Excepcionales
    if (data.carrerasTecnicasLista && Array.isArray(data.carrerasTecnicasLista) && data.carrerasTecnicasLista.length > 0) {
      lsSet('cea_carreras_tecnicas_lista', data.carrerasTecnicasLista);
    }
    if (typeof renderCarrerasDisponibles === 'function') renderCarrerasDisponibles();

    if (data.reqNivelesTec && Array.isArray(data.reqNivelesTec) && data.reqNivelesTec.length > 0) {
      lsSet('cea_req_niveles_tec', data.reqNivelesTec);
    }
    if (typeof renderReqNivelesTec === 'function') renderReqNivelesTec();

    if (data.casosExcepcionales && Array.isArray(data.casosExcepcionales) && data.casosExcepcionales.length > 0) {
      lsSet('cea_casos_excepcionales', data.casosExcepcionales);
    }
    if (typeof renderCasosExcepcionales === 'function') renderCasosExcepcionales();

    if (typeof renderLapicesDirectosDirector === 'function') {
      renderLapicesDirectosDirector();
    }
    if (typeof renderSeccionHumanistica === 'function') {
      renderSeccionHumanistica();
    }
  } finally {
    _aplicandoDatosRemotos = prevRemoteFlag;
  }
}

/* ─── MODO DIA EXCLUSIVO (MODO OSCURO ELIMINADO DEFINITIVAMENTE) ─── */
function getHoraBolivia() {
  const now = new Date();
  const utc = now.getTime() + now.getTimezoneOffset() * 60000;
  return new Date(utc - 4 * 3600000).getHours();
}

function aplicarModoOscuro() {
  // Desactivar y remover permanentemente cualquier rastro de modo oscuro en toda la web
  document.documentElement.classList.remove('dark', 'dark-mode');
  if (document.body) {
    document.body.classList.remove('dark', 'dark-mode');
  }
  try {
    localStorage.removeItem('darkOverride');
    localStorage.removeItem('cea_dark_override');
  } catch (e) {}

  const btn = document.getElementById('darkToggle');
  if (btn) btn.style.display = 'none';
  const btnMobile = document.getElementById('darkToggleMobile');
  if (btnMobile) btnMobile.style.display = 'none';
}

function actualizarBotonDark() {
  const btn = document.getElementById('darkToggle');
  if (btn) btn.style.display = 'none';
  const btnMobile = document.getElementById('darkToggleMobile');
  if (btnMobile) btnMobile.style.display = 'none';
}

function toggleDark() {
  // Modo noche eliminado completamente; solo modo día activo
  aplicarModoOscuro();
}

/* ─── ABRIR ADMIN (Boton Director) ─── */
function abrirAdmin() {
  window.location.hash = '#admin';
  const adminSection = document.getElementById('admin');
  if (adminSection) {
    adminSection.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }

  const session = lsGet('cea_session', null);
  if (session && (session.role === 'director' || session.role === 'admin')) {
    mostrarPanelAdmin();
  } else if (session && session.role === 'docente') {
    mostrarPanelDocente(session.areaKey);
  } else {
    const loginBox = document.getElementById('admin-login');
    if (loginBox) loginBox.style.display = 'block';
  }
}

