function getPeriodosSede(franjaKey = 'manana', sedeKey = null, area = turnoHorarioActual) {
  const curArea = area || turnoHorarioActual || 'hum';
  const curSede = sedeKey || getHorarioSedeActiveKey(curArea);

  const baseDef = obtenerPeriodosFranjaDefault(franjaKey, curArea);
  const custom = getSedeLsData(`cea_periodos_custom_${franjaKey}`, null, curSede, curArea);
  if (Array.isArray(custom) && custom.length > 0) {
    return custom;
  }
  return JSON.parse(JSON.stringify(baseDef));
}

function setPeriodosSede(periodos, franjaKey = 'manana', sedeKey = null, area = turnoHorarioActual) {
  const curArea = area || turnoHorarioActual || 'hum';
  const curSede = sedeKey || getHorarioSedeActiveKey(curArea);

  setSedeLsData(`cea_periodos_custom_${franjaKey}`, periodos, curSede, curArea);
  if (curArea === 'hum' && franjaKey === 'manana' && curSede === 'central') {
    HORARIOS_BTH_CANONICO.periodos = periodos;
  }
}

function getPeriodosDia(dia, area = turnoHorarioActual, sedeKey = null) {
  const curArea = area || turnoHorarioActual || 'hum';
  const curSede = sedeKey || getHorarioSedeActiveKey(curArea);

  const customDia = getSedeLsData(`cea_periodos_dia_${dia}`, null, curSede, curArea);
  if (Array.isArray(customDia) && customDia.length > 0) {
    return customDia;
  }

  const turnoDia = (curArea === 'hum') ? getTurnoDiaHum(dia, curSede) : getTurnoDiaTec(dia);
  return getPeriodosSede(turnoDia, curSede, curArea);
}

function setPeriodosDia(dia, periodos, area = turnoHorarioActual, sedeKey = null) {
  const curArea = area || turnoHorarioActual || 'hum';
  const curSede = sedeKey || getHorarioSedeActiveKey(curArea);

  setSedeLsData(`cea_periodos_dia_${dia}`, periodos, curSede, curArea);
  cargarHorariosMatriz(curArea);
}

function getDiaScheduleConfig(dia, area = turnoHorarioActual, sedeKey = null) {
  const curArea = area || turnoHorarioActual || 'hum';
  const curSede = sedeKey || getHorarioSedeActiveKey(curArea);
  const saved = getSedeLsData(`cea_dia_config_${dia}`, null, curSede, curArea);
  if (saved && typeof saved === 'object') {
    return saved;
  }
  return {
    usarCustom: false,
    recesoPosition: 3,
    recesoInicio: (curArea === 'hum' ? '10:00' : '16:00'),
    recesoFin: (curArea === 'hum' ? '10:20' : '16:20'),
    totalPeriodos: 6
  };
}

function setDiaScheduleConfig(dia, configObj, area = turnoHorarioActual, sedeKey = null) {
  const curArea = area || turnoHorarioActual || 'hum';
  const curSede = sedeKey || getHorarioSedeActiveKey(curArea);

  setSedeLsData(`cea_dia_config_${dia}`, configObj, curSede, curArea);
  cargarHorariosMatriz(curArea);
}

function calcularSlotDia(dia, pIdx, area, sedeKey) {
  const cfgD = getDiaScheduleConfig(dia, area, sedeKey);
  const pos = (cfgD && cfgD.usarCustom) ? cfgD.recesoPosition : 3;

  if (pos === 0) {
    // Sin recreo: row 0->P1, row 1->P2, row 2->P3, row 3->P4, row 4->P5, row 5->P6, row 6->P7
    const periodNum = (pIdx < 3) ? (pIdx + 1) : (pIdx === 3 ? 4 : pIdx + 1);
    return { isReceso: false, periodNum: periodNum, cfg: cfgD };
  }

  if (pos === 1) {
    // Recreo después del 1º periodo (a la fila pIdx = 1)
    if (pIdx === 1) return { isReceso: true, cfg: cfgD };
    const periodNum = (pIdx === 0) ? 1 : (pIdx === 2 ? 2 : (pIdx === 3 ? 3 : pIdx));
    return { isReceso: false, periodNum: periodNum, cfg: cfgD };
  }

  if (pos === 2) {
    // Recreo después del 2º periodo (a la fila pIdx = 2)
    if (pIdx === 2) return { isReceso: true, cfg: cfgD };
    const periodNum = (pIdx < 2) ? (pIdx + 1) : (pIdx === 3 ? 3 : pIdx);
    return { isReceso: false, periodNum: periodNum, cfg: cfgD };
  }

  if (pos === 4) {
    // Recreo después del 4º periodo (a la fila pIdx = 4)
    if (pIdx === 4) return { isReceso: true, cfg: cfgD };
    const periodNum = (pIdx < 4) ? (pIdx + 1) : pIdx;
    return { isReceso: false, periodNum: periodNum, cfg: cfgD };
  }

  // Predeterminado pos === 3 (Recreo en la fila pIdx = 3)
  if (pIdx === 3) return { isReceso: true, cfg: cfgD };
  const periodNum = (pIdx < 3) ? (pIdx + 1) : pIdx;
  return { isReceso: false, periodNum: periodNum, cfg: cfgD };
}

function tienePeriodosPersonalizadosDia(dia, area = turnoHorarioActual, sedeKey = null) {
  const curArea = area || turnoHorarioActual || 'hum';
  const curSede = sedeKey || getHorarioSedeActiveKey(curArea);
  const customDia = getSedeLsData(`cea_periodos_dia_${dia}`, null, curSede, curArea);
  return Array.isArray(customDia) && customDia.length > 0;
}

function obtenerPeriodosFranja(franjaKey, area = 'hum', sedeKey = null) {
  return getPeriodosSede(franjaKey, sedeKey, area);
}


function getHorarioSedeActiveKey(area = turnoHorarioActual) {
  const curArea = area || turnoHorarioActual || 'hum';
  return lsGet(`cea_sede_activa_${curArea}`, 'central') || 'central';
}

function setHorarioSedeActiveKey(sedeKey, area = turnoHorarioActual) {
  const curArea = area || turnoHorarioActual || 'hum';
  lsSet(`cea_sede_activa_${curArea}`, sedeKey);
  lsSet('cea_sede_activa', sedeKey);
}

function obtenerListaSedesEducativas(area = turnoHorarioActual) {
  const curArea = area || turnoHorarioActual || 'hum';
  if (curArea === 'hum') {
    const listHum = lsGet('cea_sedes_lista_hum', null);
    if (listHum !== null) return listHum;
    return lsGet('cea_sedes_lista', [{ key: 'central', nombre: 'Sede Central — CEA' }]);
  }
  return lsGet(`cea_sedes_lista_${curArea}`, [
    { key: 'central', nombre: 'Sede Central — CEA' }
  ]);
}

function guardarListaSedesEducativas(sedesList, area = turnoHorarioActual) {
  const curArea = area || turnoHorarioActual || 'hum';
  lsSet(`cea_sedes_lista_${curArea}`, sedesList);
  if (curArea === 'hum') {
    lsSet('cea_sedes_lista', sedesList);
  }
  // Sincronizar de forma inmediata con Google Sheets para que todos los dispositivos lo vean
  enviarGoogleSheet({
    action: 'guardar-sedes-lista',
    area: curArea,
    sedes: sedesList
  });
  enviarGoogleSheet({
    action: 'guardar-contenido-vivo',
    key: `sedes_lista_${curArea}_json`,
    valor: JSON.stringify(sedesList),
    htmlValor: JSON.stringify(sedesList)
  });
}

function getSedeStorageKey(baseKey, sedeKey = null, area = turnoHorarioActual) {
  const curArea = area || turnoHorarioActual || 'hum';
  const sede = sedeKey || getHorarioSedeActiveKey(curArea);
  if (sede === 'central') return `${baseKey}_${curArea}`;
  return `${baseKey}_${curArea}_${sede}`;
}

function getSedeLsData(baseKey, defaultVal, sedeKey = null, area = turnoHorarioActual) {
  const curArea = area || turnoHorarioActual || 'hum';
  const keyWithArea = getSedeStorageKey(baseKey, sedeKey, curArea);
  let val = lsGet(keyWithArea, null);

  // Fallback de compatibilidad para 'central'
  if (val === null && (sedeKey === 'central' || !sedeKey)) {
    val = lsGet(baseKey, null);
  }
  if (val !== null) return val;

  if (baseKey === 'cea_horarios_matriz') {
    return JSON.parse(JSON.stringify(HORARIOS_MATRIZ_DEFAULT));
  }
  return defaultVal;
}

function setSedeLsData(baseKey, val, sedeKey = null, area = turnoHorarioActual) {
  const curArea = area || turnoHorarioActual || 'hum';
  const keyWithArea = getSedeStorageKey(baseKey, sedeKey, curArea);
  lsSet(keyWithArea, val);
  const sede = sedeKey || getHorarioSedeActiveKey(curArea);
  if (sede === 'central') {
    lsSet(baseKey, val);
  }
}

function renderizarBarraSedesHorarios() {
  const container = document.getElementById('sedes-tabs-container');
  if (!container) return;
  const curArea = turnoHorarioActual || 'hum';
  const sedes = obtenerListaSedesEducativas(curArea);
  const sedeActual = getHorarioSedeActiveKey(curArea);
  sedeHorarioActiva = sedeActual;
  const isVistaUnificada = lsGet('cea_vista_unificada_sedes', false);
  const puedeEditar = tienePermisoEdicionHorarios();

  const parentWrap = container.parentElement;

  // Mostrar siempre la barra de selección de Sedes (Sede Central seleccionada por defecto)
  container.style.display = 'flex';
  if (parentWrap) parentWrap.style.display = 'flex';

  // Renderizar ÚNICAMENTE las pestañas de las sedes (Central y Subcentro/s)
  let html = sedes.map(s => {
    const isAct = (s.key === sedeActual && !isVistaUnificada);
    const isCentral = (s.key === 'central');
    return `
      <button type="button" class="btn-sede-tab ${isAct ? 'activo' : ''}" onclick="switchSedeHorario('${s.key}')" title="Ver horario de ${escapeHTML(s.nombre)}">
        <svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="2.3" style="display:inline-block;vertical-align:-1px"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"/><circle cx="12" cy="10" r="3"/></svg>
        <span>${escapeHTML(s.nombre)}</span>
        ${puedeEditar ? `
          <span class="btn-sede-rename" onclick="event.stopPropagation(); renombrarSedeHorario('${s.key}')" title="Cambiar nombre de ${isCentral ? 'la Sede Principal' : 'este Subcentro'}" style="cursor:pointer;margin-left:6px;padding:2px 6px;display:inline-flex;align-items:center;opacity:0.95;border-radius:4px;background:rgba(255,255,255,0.35);border:1px solid rgba(255,255,255,0.5);font-size:0.70rem;font-weight:700">
            <svg viewBox="0 0 24 24" width="11" height="11" fill="none" stroke="currentColor" stroke-width="2.5" style="margin-right:2px"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
            <span>Editar</span>
          </span>
        ` : ''}
        ${(!isCentral && puedeEditar) ? `
          <span class="btn-sede-del" onclick="event.stopPropagation(); eliminarSubcentroSede('${s.key}')" title="Eliminar subcentro y su horario">&times;</span>
        ` : ''}
      </button>
    `;
  }).join('');

  container.innerHTML = html;

  const banner = document.getElementById('subcentro-ubicacion-banner');
  if (banner) banner.style.display = 'none';

  actualizarBotonModoEdicion();
}

async function renombrarSedeHorario(sedeKey) {
  if (!tienePermisoEdicionHorarios()) {
    mostrarToastLive('Debe iniciar sesión como Director(a) para modificar nombres de sedes o subcentros.');
    mostrarModalLoginDirector();
    return;
  }
  const curArea = turnoHorarioActual || 'hum';
  const sedes = obtenerListaSedesEducativas(curArea);
  const sObj = sedes.find(s => s.key === sedeKey);
  if (!sObj) return;

  const esCentral = (sedeKey === 'central');
  const nuevoNombre = await mostrarPromptModal(
    `Ingrese el nuevo nombre oficial para ${esCentral ? 'la Sede Principal' : 'el Subcentro'}:`,
    `Cambiar Nombre — ${esCentral ? 'Sede Principal' : 'Subcentro'}`,
    sObj.nombre || '',
    'Ej: Sede Central — CEA Madre Marie Poussepin / Subcentro Chulumani'
  );
  if (!nuevoNombre || !nuevoNombre.trim() || nuevoNombre.trim() === sObj.nombre) return;

  sObj.nombre = nuevoNombre.trim();
  guardarListaSedesEducativas(sedes, curArea);
  renderizarBarraSedesHorarios();
  cargarHorariosMatriz(curArea);
  mostrarToastLive(`Nombre de ${esCentral ? 'Sede Principal' : 'Subcentro'} actualizado a: "${nuevoNombre.trim()}"`);
}

async function abrirModalRenombrarSedeActiva() {
  const curArea = turnoHorarioActual || 'hum';
  const sedeActual = getHorarioSedeActiveKey(curArea);
  await renombrarSedeHorario(sedeActual);
}

function switchSedeHorario(sedeKey) {
  const curArea = turnoHorarioActual || 'hum';
  lsSet('cea_vista_unificada_sedes', false);
  const chk = document.getElementById('chk-vista-unificada-sedes');
  if (chk) chk.checked = false;
  const txt = document.getElementById('txt-estado-vista-unificada');
  if (txt) txt.textContent = 'Vista Sede Individual';

  sedeHorarioActiva = sedeKey;
  setHorarioSedeActiveKey(sedeKey, curArea);
  renderizarBarraSedesHorarios();
  cargarHorariosMatriz(curArea);
  const containerAdmin = document.getElementById('editor-horarios-matriz-container');
  if (containerAdmin) cargarEditorHorariosMatriz(curArea);
  const sedes = obtenerListaSedesEducativas(curArea);
  const sObj = sedes.find(x => x.key === sedeKey);
  mostrarToastLive(`Sede activa (${curArea === 'hum' ? 'Humanística' : 'Técnica'}): ${sObj ? sObj.nombre : sedeKey}`);
}

async function abrirModalAgregarSubcentro() {
  const curArea = turnoHorarioActual || 'hum';
  const areaNombre = (curArea === 'hum') ? 'Área Humanística' : 'Área Técnica';
  const nombre = await mostrarPromptModal(
    `Ingrese el nombre oficial del nuevo Subcentro o Anexo para ${areaNombre}:`,
    `Agregar Subcentro — ${areaNombre}`,
    '',
    'Ejemplo: Subcentro Anexo Norte / Irupana'
  );
  if (!nombre || !nombre.trim()) return;
  const sedes = obtenerListaSedesEducativas(curArea);
  const newKey = `subcentro_${Date.now()}`;
  sedes.push({ key: newKey, nombre: nombre.trim() });
  guardarListaSedesEducativas(sedes, curArea);
  switchSedeHorario(newKey);
  mostrarToastLive(`¡Nuevo Subcentro "${nombre.trim()}" agregado a ${areaNombre}!`);
}

async function eliminarSubcentroSede(sedeKey) {
  if (sedeKey === 'central') return;
  if (!tienePermisoEdicionHorarios()) return;
  const curArea = turnoHorarioActual || 'hum';
  const sedes = obtenerListaSedesEducativas(curArea);
  const sObj = sedes.find(s => s.key === sedeKey);
  const nom = sObj ? sObj.nombre : 'este subcentro';
  const ok = await mostrarConfirmModal(
    `¿Desea eliminar el subcentro "${nom}" y borrar todo el horario asignado a esta sede?`,
    'Eliminar Subcentro',
    'Eliminar Subcentro',
    true
  );
  if (!ok) return;

  const nuevasSedes = sedes.filter(s => s.key !== sedeKey);
  guardarListaSedesEducativas(nuevasSedes, curArea);
  enviarGoogleSheet({
    action: 'eliminar-subcentro',
    sede: sedeKey,
    area: curArea
  });
  // Limpiar llaves locales del subcentro
  try {
    lsSet(`cea_horarios_matriz_${curArea}_${sedeKey}`, null);
    lsSet(`cea_horarios_merges_${curArea}_${sedeKey}`, null);
  } catch(e) {}
  switchSedeHorario('central');
  mostrarToastLive(`Subcentro "${nom}" y su horario fueron eliminados de ${curArea === 'hum' ? 'Humanística' : 'Técnica'}.`);
}

function switchTurnoHorario(turno) {
  turnoHorarioActual = turno;
  window.turnoHorarioActual = turno;
  // Por defecto al cambiar o iniciar en Bachillerato Humanístico o Técnica Tecnológica, seleccionar Sede Central
  sedeHorarioActiva = 'central';
  setHorarioSedeActiveKey('central', turno);
  lsSet('cea_vista_unificada_sedes', false);
  const chkUni = document.getElementById('chk-vista-unificada-sedes');
  if (chkUni) chkUni.checked = false;

  document.querySelectorAll('#btn-turno-hum, #btn-turno-tec, .btn-turno-tab').forEach(b => {
    const tVal = b.getAttribute('data-turno') || b.id.replace('btn-turno-', '');
    b.classList.toggle('active', tVal === turno);
    b.classList.toggle('activo', tVal === turno);
  });
  renderizarBarraSedesHorarios();
  cargarHorariosMatriz(turno);
}

function generarOpcionesEditorMateria(turno, materiaActual) {
  const areasTec = lsGet('cea_areas_tec', AREAS_TEC_DEFAULT);
  let opts = `<option value="Libre" ${(!materiaActual || materiaActual === 'Libre') ? 'selected' : ''}>-- Libre / Sin clase --</option>`;
  if (turno === 'hum') {
    const humMats = [
      'Matemática', 'Lenguaje y Literatura', 'Ciencias Naturales', 'Ciencias Sociales',
      'Física', 'Química', 'Biología', 'Filosofía y Psicología', 'Cívica', 'Cosmovisiones'
    ];
    opts += `<optgroup label="Materias Humanísticas">`;
    humMats.forEach(m => {
      opts += `<option value="${m}" ${m === materiaActual ? 'selected' : ''}>${m}</option>`;
    });
    opts += `</optgroup>`;
  } else {
    opts += `<optgroup label="Carreras Técnicas">`;
    areasTec.forEach(a => {
      opts += `<option value="${a.nombre}" ${a.nombre === materiaActual || a.key === materiaActual ? 'selected' : ''}>${a.nombre}</option>`;
    });
    opts += `</optgroup>`;
  }
  if (materiaActual && materiaActual !== 'Libre' && !opts.includes(`value="${materiaActual}"`)) {
    opts += `<option value="${materiaActual}" selected>${materiaActual}</option>`;
  }
  return opts;
}

function generarOpcionesEditorDocente(docenteActual) {
  const d = lsGet('cea_docentes', DOCENTES_DEFAULT);
  const docentes = Array.from(new Set(Object.values(d).filter(Boolean)));
  let opts = `<option value="—" ${(!docenteActual || docenteActual === '—') ? 'selected' : ''}>-- Sin Docente --</option>`;
  docentes.forEach(nom => {
    opts += `<option value="${nom}" ${nom === docenteActual ? 'selected' : ''}>${nom}</option>`;
  });
  if (docenteActual && docenteActual !== '—' && !docentes.includes(docenteActual)) {
    opts += `<option value="${docenteActual}" selected>${docenteActual}</option>`;
  }
  return opts;
}

