function toggleMostrarDocentesHorario(checked) {
  const mostrar = (typeof checked === 'boolean') ? checked : !lsGet('cea_horario_mostrar_docentes', true);
  lsSet('cea_horario_mostrar_docentes', mostrar);
  
  const chk = document.getElementById('chk-mostrar-docentes-horario');
  if (chk) chk.checked = mostrar;
  const txt = document.getElementById('txt-estado-ver-docentes');
  if (txt) txt.textContent = mostrar ? 'Ver Docentes' : 'Solo Materias';
  const chkStep1 = document.getElementById('chk-mostrar-docentes-step1');
  if (chkStep1) chkStep1.checked = mostrar;
  const lblDoc1 = document.getElementById('txt-mostrar-docentes-step1-lbl');
  if (lblDoc1) lblDoc1.textContent = mostrar ? 'Docentes' : 'Solo Materias';
  const chipDoc = document.getElementById('chip-mostrar-docentes');
  if (chipDoc) chipDoc.classList.toggle('is-active', mostrar);
  
  cargarHorariosMatriz(turnoHorarioActual);
  mostrarToastLive(mostrar ? 'Horario: Mostrando asignaturas y docentes asignados.' : 'Horario: Mostrando solo asignaturas con sus colores.');
}

function toggleMostrarTurnosHorario(checked) {
  const mostrar = (typeof checked === 'boolean') ? checked : !lsGet('cea_horario_mostrar_turnos', true);
  lsSet('cea_horario_mostrar_turnos', mostrar);

  const chk = document.getElementById('chk-mostrar-turnos-horario');
  if (chk) chk.checked = mostrar;
  const txt = document.getElementById('txt-estado-ver-turnos');
  if (txt) txt.textContent = mostrar ? 'Ver Turnos' : 'Ocultar Turnos';

  const chkStep1 = document.getElementById('chk-mostrar-turnos-step1');
  if (chkStep1) chkStep1.checked = mostrar;
  const lblStep1 = document.getElementById('txt-mostrar-turnos-step1-lbl');
  if (lblStep1) lblStep1.textContent = mostrar ? 'Visible' : 'Oculto';
  const chipTurnos = document.getElementById('chip-mostrar-turnos');
  if (chipTurnos) chipTurnos.classList.toggle('is-active', mostrar);

  cargarHorariosMatriz(turnoHorarioActual);
  if (typeof mostrarToastLive === 'function') {
    mostrarToastLive(mostrar ? 'Horario: Texto de turnos (Mañana/Tarde/Noche) visible en los días.' : 'Horario: Texto de turnos ocultado en los días.');
  }
}


function toggleIncluirBthHorario(checked, sedeKey = null) {
  const curArea = 'hum';
  const curSede = sedeKey || getHorarioSedeActiveKey(curArea);
  const actual = getSedeLsData('cea_horario_incluir_bth', true, curSede, curArea);
  const incluir = (typeof checked === 'boolean') ? checked : !actual;

  setSedeLsData('cea_horario_incluir_bth', incluir, curSede, curArea);

  const chk = document.getElementById('chk-incluir-bth-horario');
  if (chk) chk.checked = incluir;
  const txt = document.getElementById('txt-estado-incluir-bth');
  if (txt) txt.textContent = incluir ? 'Con Módulos BTH' : 'Sin BTH (Omitir)';

  cargarHorariosMatriz('hum');

  const sedes = obtenerListaSedesEducativas('hum');
  const sObj = sedes.find(s => s.key === curSede);
  const nomSede = sObj ? sObj.nombre : 'Sede Central';
  mostrarToastLive(incluir ? `Módulos BTH activados para ${nomSede}.` : `Módulos BTH omitidos para ${nomSede}.`);
}


function obtenerListaMateriasParaPaleta(turno = 'hum') {
  if (turno === 'tec') {
    return [
      'ETA',
      'Sistemas Informáticos',
      'Gastronomía',
      'Belleza Integral',
      'Secretariado Ejecutivo',
      'Confección Textil',
      'Agropecuaria'
    ];
  }
  // Turno Humanística: estrictamente las 4 materias oficiales de Humanística + La especialidad BTH activa
  const carreraBTHActiva = getSedeLsData('cea_bth_carrera_activa', 'Agropecuaria');
  return [
    'Ciencias Naturales',
    'Matemática',
    'Ciencias Sociales',
    'Lenguaje',
    carreraBTHActiva
  ];
}

function toggleDiaHorarioBTH(dia, activo) {
  let dias = getSedeLsData('cea_bth_dias_activos', ['Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes']);
  if (activo && !dias.includes(dia)) {
    dias.push(dia);
  } else if (!activo && dias.includes(dia)) {
    dias = dias.filter(d => d !== dia);
  }
  if (!dias.length) dias = ['Lunes'];
  dias = ordenarDiasCronologico(dias);
  setSedeLsData('cea_bth_dias_activos', dias);
  cargarHorariosMatriz('hum');
  enviarGoogleSheet({
    action: 'guardar-contenido-vivo',
    key: 'bth_dias_activos_json',
    valor: JSON.stringify(dias)
  });
}

function obtenerCursosParaDiaBTH(dia) {
  const conf = getSedeLsData('cea_bth_cursos_por_dia', {});
  if (conf[dia] && Array.isArray(conf[dia]) && conf[dia].length > 0) {
    return conf[dia];
  }
  if (dia === 'Viernes') {
    return [...HORARIOS_BTH_CANONICO.cursosViernes];
  }
  return [...HORARIOS_BTH_CANONICO.cursosDefault];
}

function cambiarPaqueteCursosDia(dia, paquete) {
  const conf = getSedeLsData('cea_bth_cursos_por_dia', {});
  conf[dia] = ['Avanzados', 'Aplicados', 'Complementarios', 'Especializados'];
  setSedeLsData('cea_bth_cursos_por_dia', conf);
  cargarHorariosMatriz('hum');
  const containerAdmin = document.getElementById('editor-horarios-matriz-container');
  if (containerAdmin) cargarEditorHorariosMatriz('hum');
  mostrarToastLive(`Cursos oficiales de ${dia} configurados (Avanzados, Aplicados, Complementarios, Especializados).`);
  enviarGoogleSheet({
    action: 'guardar-contenido-vivo',
    key: 'bth_cursos_por_dia_json',
    valor: JSON.stringify(conf)
  });
}

function cambiarCursoColumnaDia(dia, colIdx, nuevoCurso) {
  const conf = getSedeLsData('cea_bth_cursos_por_dia', {});
  if (!conf[dia] || !Array.isArray(conf[dia])) {
    conf[dia] = (dia === 'Viernes') ? [...HORARIOS_BTH_CANONICO.cursosViernes] : [...HORARIOS_BTH_CANONICO.cursosDefault];
  }
  conf[dia][colIdx] = nuevoCurso;
  setSedeLsData('cea_bth_cursos_por_dia', conf);
  cargarHorariosMatriz('hum');
  const containerAdmin = document.getElementById('editor-horarios-matriz-container');
  if (containerAdmin) cargarEditorHorariosMatriz('hum');
  mostrarToastLive(`Paralelo ${colIdx + 1} de ${dia} actualizado a ${nuevoCurso}`);
  enviarGoogleSheet({
    action: 'guardar-contenido-vivo',
    key: 'bth_cursos_por_dia_json',
    valor: JSON.stringify(conf)
  });
}

function obtenerDatosCeldaBTH(dia, periodoNum, cursoIdx) {
  return { materia: 'Libre', docente: '—', sub: '' };
}

