window.modoEdicionHorarioActivo = false;

function tienePermisoEdicionHorarios() {
  const session = lsGet('cea_session', null);
  if (!session) return false;
  if (session.role === 'director') return true;
  if (session.role === 'docente') {
    const uDoc = lsGet('cea_usuarios_docentes', {})[session.areaKey];
    return Boolean(uDoc && uDoc.comision === true);
  }
  return false;
}

// Gestión de Turnos Dinámicos por Día en Área Técnica (TTP)
const DIAS_TURNOS_DEFAULT_TEC = {
  'Lunes': 'tarde',
  'Martes': 'tarde',
  'Miércoles': 'tarde',
  'Jueves': 'tarde',
  'Viernes': 'tarde',
  'Sábado': 'mañana',
  'Domingo': 'mañana'
};

const DIAS_TURNOS_DEFAULT_HUM = {
  'Lunes': 'mañana',
  'Martes': 'mañana',
  'Miércoles': 'mañana',
  'Jueves': 'mañana',
  'Viernes': 'mañana',
  'Sábado': 'mañana',
  'Domingo': 'mañana'
};

function getTurnoDiaHum(dia, sedeKey = null) {
  const sKey = sedeKey || getHorarioSedeActiveKey('hum');
  const turnosMap = getSedeLsData('cea_hum_turnos_dias', DIAS_TURNOS_DEFAULT_HUM, sKey, 'hum');
  return turnosMap[dia] || 'mañana';
}

function setTurnoDiaHum(dia, nuevoTurno, sedeKey = null) {
  const sKey = sedeKey || getHorarioSedeActiveKey('hum');
  const turnosMap = getSedeLsData('cea_hum_turnos_dias', DIAS_TURNOS_DEFAULT_HUM, sKey, 'hum');
  turnosMap[dia] = nuevoTurno;
  setSedeLsData('cea_hum_turnos_dias', turnosMap, sKey, 'hum');
  cargarHorariosMatriz('hum');
  const labelTurno = nuevoTurno === 'mañana' ? 'Mañana' : (nuevoTurno === 'noche' ? 'Noche' : 'Tarde');
  mostrarToastLive(`Día ${dia} (Humanística) configurado en Turno ${labelTurno}.`);

  if (typeof enviarGoogleSheet === 'function') {
    enviarGoogleSheet({
      action: 'guardar-turnos-dias-hum',
      turnosDiasHum: turnosMap,
      sedeKey: sKey
    }).catch(() => {});
  }
}

function getTurnoDiaTec(dia) {
  const turnosMap = getSedeLsData('cea_tec_turnos_dias', DIAS_TURNOS_DEFAULT_TEC);
  return turnosMap[dia] || (dia === 'Sábado' || dia === 'Domingo' ? 'mañana' : 'tarde');
}

function setTurnoDiaTec(dia, nuevoTurno) {
  const turnosMap = getSedeLsData('cea_tec_turnos_dias', DIAS_TURNOS_DEFAULT_TEC);
  turnosMap[dia] = nuevoTurno;
  setSedeLsData('cea_tec_turnos_dias', turnosMap);
  cargarHorariosMatriz('tec');
  const labelTurno = nuevoTurno === 'mañana' ? 'Mañana' : (nuevoTurno === 'noche' ? 'Noche' : 'Tarde');
  mostrarToastLive(`Día ${dia} configurado en Turno ${labelTurno}.`);

  if (typeof enviarGoogleSheet === 'function') {
    enviarGoogleSheet({
      action: 'guardar-turnos-dias-tec',
      turnosDiasTec: turnosMap
    }).catch(() => {});
  }
}

let _diaEditandoTurno = null;
let _areaEditandoTurno = 'tec';

function abrirModalCambiarTurnoDiaTec(dia) {
  abrirModalCambiarTurnoDia(dia, 'tec');
}

function abrirModalCambiarTurnoDia(dia, area = 'tec') {
  if (!tienePermisoEdicionHorarios()) return;
  _diaEditandoTurno = dia;
  _areaEditandoTurno = area;
  const modal = document.getElementById('modal-cambiar-turno-dia-tec');
  const titulo = document.getElementById('modal-turno-dia-titulo');
  const desc = document.getElementById('modal-turno-dia-desc');
  const btnTarde = document.getElementById('btn-opcion-turno-tarde');
  const btnManana = document.getElementById('btn-opcion-turno-manana');
  const btnNoche = document.getElementById('btn-opcion-turno-noche');

  const areaNombre = (area === 'hum') ? 'Área Humanística' : 'Área Técnica (TTP)';
  if (titulo) titulo.textContent = `Turno Oficial para: ${dia} (${areaNombre})`;
  if (desc) desc.textContent = `Selecciona el turno oficial de clases para ${dia} en ${areaNombre}:`;

  const turnoActual = (area === 'hum') ? getTurnoDiaHum(dia) : getTurnoDiaTec(dia);
  if (btnTarde) btnTarde.classList.toggle('selected', turnoActual === 'tarde');
  if (btnManana) btnManana.classList.toggle('selected', turnoActual === 'mañana');
  if (btnNoche) btnNoche.classList.toggle('selected', turnoActual === 'noche');

  if (modal) modal.style.display = 'flex';
}

let _diaConfigurandoPeriodos = null;
let _areaConfigurandoPeriodos = 'hum';

function abrirModalConfigurarPeriodosDia(dia, area = turnoHorarioActual) {
  if (!tienePermisoEdicionHorarios()) return;
  _diaConfigurandoPeriodos = dia;
  _areaConfigurandoPeriodos = area || turnoHorarioActual || 'hum';

  const curSede = getHorarioSedeActiveKey(_areaConfigurandoPeriodos);
  const cfg = getDiaScheduleConfig(dia, _areaConfigurandoPeriodos, curSede);

  const title = document.getElementById('modal-cfg-dia-title');
  const sub = document.getElementById('modal-cfg-dia-sub');
  const inpNombre = document.getElementById('modal-cfg-dia-nombre');
  const inpArea = document.getElementById('modal-cfg-dia-area');

  const areaNombre = (_areaConfigurandoPeriodos === 'hum') ? 'Área Humanística' : 'Área Técnica (TTP)';
  if (title) title.textContent = `Estructura de Horario para: ${dia}`;
  if (sub) sub.textContent = `${areaNombre} • Configuración de recreo y periodos`;
  if (inpNombre) inpNombre.value = dia;
  if (inpArea) inpArea.value = _areaConfigurandoPeriodos;

  const optGen = document.getElementById('opt-cfg-dia-general');
  const optCust = document.getElementById('opt-cfg-dia-custom');
  const esCustom = !!cfg.usarCustom;

  if (optGen) optGen.checked = !esCustom;
  if (optCust) optCust.checked = esCustom;

  const selPos = document.getElementById('modal-cfg-dia-receso-pos');
  if (selPos) selPos.value = String(cfg.recesoPosition !== undefined ? cfg.recesoPosition : 3);

  const selTot = document.getElementById('modal-cfg-dia-total-periodos');
  if (selTot) selTot.value = String(cfg.totalPeriodos || 6);

  toggleModoPeriodosDiaModal(esCustom);

  const modal = document.getElementById('modal-configurar-periodos-dia');
  if (modal) modal.style.display = 'flex';
}

function cerrarModalConfigurarPeriodosDia() {
  const modal = document.getElementById('modal-configurar-periodos-dia');
  if (modal) modal.style.display = 'none';
  _diaConfigurandoPeriodos = null;
}

function toggleModoPeriodosDiaModal(esCustom) {
  const editorWrap = document.getElementById('modal-cfg-dia-editor-wrap');
  if (editorWrap) editorWrap.style.display = esCustom ? 'block' : 'none';
}

function alCambiarPosicionRecesoModal(val) {
  // Sin campos de hora extra en el modal
}

function restablecerDiaConfigModal() {
  if (!_diaConfigurandoPeriodos) return;
  const curSede = getHorarioSedeActiveKey(_areaConfigurandoPeriodos);
  setDiaScheduleConfig(_diaConfigurandoPeriodos, { usarCustom: false }, _areaConfigurandoPeriodos, curSede);
  mostrarToastLive(`Horario de ${_diaConfigurandoPeriodos} restablecido al horario general.`);
  cerrarModalConfigurarPeriodosDia();
}

function guardarConfiguracionPeriodosDiaModal(e) {
  if (e) e.preventDefault();
  if (!_diaConfigurandoPeriodos) return;

  const optCust = document.getElementById('opt-cfg-dia-custom');
  const esCustom = optCust ? optCust.checked : false;

  const curSede = getHorarioSedeActiveKey(_areaConfigurandoPeriodos);

  if (!esCustom) {
    setDiaScheduleConfig(_diaConfigurandoPeriodos, { usarCustom: false }, _areaConfigurandoPeriodos, curSede);
    mostrarToastLive(`Horario de ${_diaConfigurandoPeriodos} usará la estructura general.`);
  } else {
    const selPos = document.getElementById('modal-cfg-dia-receso-pos');
    const selTot = document.getElementById('modal-cfg-dia-total-periodos');

    const recesoPos = parseInt(selPos ? selPos.value : '3', 10);
    const totPer = parseInt(selTot ? selTot.value : '6', 10);

    const newCfg = {
      usarCustom: true,
      recesoPosition: recesoPos,
      totalPeriodos: totPer
    };

    setDiaScheduleConfig(_diaConfigurandoPeriodos, newCfg, _areaConfigurandoPeriodos, curSede);
    const posTxt = recesoPos === 0 ? 'sin recreo' : `recreo después del ${recesoPos}º periodo`;
    mostrarToastLive(`Horario de ${_diaConfigurandoPeriodos} actualizado (${posTxt}).`);
  }

  cerrarModalConfigurarPeriodosDia();
}

function cerrarModalCambiarTurnoDiaTec() {
  const modal = document.getElementById('modal-cambiar-turno-dia-tec');
  if (modal) modal.style.display = 'none';
  _diaEditandoTurno = null;
}

function seleccionarTurnoDiaTec(nuevoTurno) {
  if (!_diaEditandoTurno) return;
  if (_areaEditandoTurno === 'hum') {
    setTurnoDiaHum(_diaEditandoTurno, nuevoTurno);
  } else {
    setTurnoDiaTec(_diaEditandoTurno, nuevoTurno);
  }
  cerrarModalCambiarTurnoDiaTec();
}

function alternarTurnoDiaTec(dia) {
  if (!tienePermisoEdicionHorarios()) return;
  const actual = getTurnoDiaTec(dia);
  let nuevo = 'tarde';
  if (actual === 'tarde') nuevo = 'mañana';
  else if (actual === 'mañana') nuevo = 'noche';
  else nuevo = 'tarde';
  setTurnoDiaTec(dia, nuevo);
}

function clickBotonEditarHorario() {
  if (!tienePermisoEdicionHorarios()) {
    const session = lsGet('cea_session', null);
    if (!session) {
      mostrarToastLive('Debes iniciar sesión como Director(a) o Comisión Pedagógica para editar el horario oficial.');
      const adminSec = document.getElementById('admin');
      if (adminSec) {
        adminSec.scrollIntoView({ behavior: 'smooth' });
        const userInp = document.getElementById('admin-user');
        if (userInp) setTimeout(() => userInp.focus(), 400);
      }
      return;
    } else {
      mostrarToastLive('Acceso restringido: Tu perfil no cuenta con permisos de Dirección o Comisión Pedagógica para modificar horarios.');
      return;
    }
  }

  window.modoEdicionHorarioActivo = !window.modoEdicionHorarioActivo;
  actualizarBotonModoEdicion();
  cargarHorariosMatriz(turnoHorarioActual);

  if (window.modoEdicionHorarioActivo) {
    mostrarToastLive('Modo edición activado. Haz clic en cualquier celda para asignar materias, docentes o fusionar periodos.');
  } else {
    mostrarToastLive('Modo edición finalizado. Horario oficial actualizado y guardado.');
  }
}

function actualizarBotonModoEdicion() {
  const btn = document.getElementById('btn-toggle-modo-edicion-horario');
  const txt = document.getElementById('btn-toggle-modo-edicion-texto');
  const svg = document.getElementById('btn-toggle-modo-edicion-svg');
  const btnTogglePanel = document.getElementById('btn-toggle-panel-gestor');

  // Sincronizar estado del toggle Ver Docentes, Ver Turnos, Líneas de Impresión e Incluir BTH
  const chkDoc = document.getElementById('chk-mostrar-docentes-horario');
  const txtDoc = document.getElementById('txt-estado-ver-docentes');
  const mostrarDoc = lsGet('cea_horario_mostrar_docentes', true);
  if (chkDoc) chkDoc.checked = mostrarDoc;
  if (txtDoc) txtDoc.textContent = mostrarDoc ? 'Ver Docentes' : 'Solo Materias';
  const chkDocStep1 = document.getElementById('chk-mostrar-docentes-step1');
  if (chkDocStep1) chkDocStep1.checked = mostrarDoc;

  const chkTur = document.getElementById('chk-mostrar-turnos-horario');
  const txtTur = document.getElementById('txt-estado-ver-turnos');
  const mostrarTur = lsGet('cea_horario_mostrar_turnos', true);
  if (chkTur) chkTur.checked = mostrarTur;
  if (txtTur) txtTur.textContent = mostrarTur ? 'Ver Turnos' : 'Ocultar Turnos';
  const chkStep1 = document.getElementById('chk-mostrar-turnos-step1');
  if (chkStep1) chkStep1.checked = mostrarTur;

  const chkBth = document.getElementById('chk-incluir-bth-horario');
  const txtBth = document.getElementById('txt-estado-incluir-bth');
  const incluirBth = getSedeLsData('cea_horario_incluir_bth', true, getHorarioSedeActiveKey('hum'), 'hum');
  if (chkBth) chkBth.checked = incluirBth;
  if (txtBth) txtBth.textContent = incluirBth ? 'Con Módulos BTH' : 'Sin BTH (Omitir)';

  const chkLin = document.getElementById('chk-imprimir-lineas-horario');
  const impLin = lsGet('cea_horario_imprimir_lineas', true);
  if (chkLin) chkLin.checked = impLin;

  const selPaleta = document.getElementById('sel-paleta-colores-horario');
  const paletaActiva = lsGet('cea_horario_paleta_colores', 'multicolor');
  if (selPaleta) selPaleta.value = paletaActiva;

  const puedeGestionar = tienePermisoEdicionHorarios();

  // Control estricto de visibilidad: Sólo Director o Comisión Pedagógica
  const lblDocentes = document.getElementById('toggle-docentes-switch-label');
  if (lblDocentes) lblDocentes.style.display = puedeGestionar ? 'inline-flex' : 'none';

  const lblTurnos = document.getElementById('toggle-turnos-switch-label');
  if (lblTurnos) lblTurnos.style.display = puedeGestionar ? 'inline-flex' : 'none';

  const lblBth = document.getElementById('toggle-bth-switch-label');
  if (lblBth) lblBth.style.display = (puedeGestionar && turnoHorarioActual === 'hum') ? 'inline-flex' : 'none';

  const lblEta = document.getElementById('toggle-eta-nombre-label');
  const chkEta = document.getElementById('chk-mostrar-eta-completo');
  const txtEta = document.getElementById('txt-estado-eta-completo');
  const mostrarEta = lsGet('cea_tec_mostrar_eta_completo', false);
  const textoEtaPersonalizado = lsGet('cea_tec_texto_eta', 'Educación Técnica Alternativa');
  const siglaEtaPersonalizada = lsGet('cea_tec_sigla_eta', 'ETA');
  if (chkEta) chkEta.checked = mostrarEta;
  if (txtEta) txtEta.textContent = mostrarEta ? textoEtaPersonalizado : `Sigla (${siglaEtaPersonalizada})`;
  if (lblEta) lblEta.style.display = (puedeGestionar && turnoHorarioActual === 'tec') ? 'inline-flex' : 'none';

  const btnEditEta = document.getElementById('btn-editar-texto-eta');
  if (btnEditEta) btnEditEta.style.display = (puedeGestionar && turnoHorarioActual === 'tec') ? 'inline-flex' : 'none';

  const lblLineas = document.getElementById('toggle-lineas-imprimir-label');
  if (lblLineas) lblLineas.style.display = puedeGestionar ? 'inline-flex' : 'none';

  const boxPaleta = document.getElementById('paleta-selector-container');
  if (boxPaleta) boxPaleta.style.display = puedeGestionar ? 'inline-flex' : 'none';

  const boxFranjas = document.getElementById('franjas-selector-container');
  if (boxFranjas) boxFranjas.style.display = puedeGestionar ? 'inline-flex' : 'none';

  const lblUnificada = document.getElementById('toggle-unificada-switch-label');
  const chkUnificada = document.getElementById('chk-vista-unificada-sedes');
  const sedesList = obtenerListaSedesEducativas(turnoHorarioActual || 'hum');
  const isVistaUnificada = lsGet('cea_vista_unificada_sedes', false);
  if (chkUnificada) chkUnificada.checked = isVistaUnificada;
  if (lblUnificada) lblUnificada.style.display = (puedeGestionar && sedesList.length > 1) ? 'inline-flex' : 'none';

  const btnSubcentro = document.getElementById('btn-agregar-subcentro');
  if (btnSubcentro) btnSubcentro.style.display = puedeGestionar ? 'inline-flex' : 'none';

  if (!puedeGestionar) {
    window.modoEdicionHorarioActivo = false;
  } else if (typeof window.modoEdicionHorarioActivo === 'undefined') {
    window.modoEdicionHorarioActivo = true;
  }

  if (!btn || !txt) return;

  btn.style.display = puedeGestionar ? 'inline-flex' : 'none';

  if (window.modoEdicionHorarioActivo) {
    btn.classList.add('activo');
    txt.textContent = 'Edición Activa (Listo)';
    if (svg) {
      svg.innerHTML = '<polyline points="20 6 9 17 4 12" stroke-width="2.5"></polyline>';
    }
    if (btnTogglePanel) btnTogglePanel.style.display = 'none';
  } else {
    btn.classList.remove('activo');
    txt.textContent = 'Modo Edición';
    if (svg) {
      svg.innerHTML = '<path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 1 2 2h14a2 2 0 0 0 2-2v-7"></path><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"></path>';
    }
    if (btnTogglePanel) btnTogglePanel.style.display = 'none';
  }
}

function isCellCoveredByMerge(merges, turno, dia, periodoNum, cIdx, periodosList) {
  if (!merges || typeof merges !== 'object') return false;
  for (const [key, m] of Object.entries(merges)) {
    if (!m || ((m.rowSpan || 1) <= 1 && (m.colSpan || 1) <= 1)) continue;
    const parts = key.split('_');
    if (parts.length < 4) continue;
    const [mTurno, mDia, mPNumStr, mCIdxStr] = parts;
    if (mTurno !== turno || mDia !== dia) continue;
    const mPNum = parseInt(mPNumStr, 10);
    const mCIdx = parseInt(mCIdxStr, 10);

    if (mPNum === periodoNum && mCIdx === cIdx) continue;

    const colCovered = (cIdx >= mCIdx && cIdx < mCIdx + (m.colSpan || 1));
    if (!colCovered) continue;

    const mRowIdx = periodosList.findIndex(x => !x.receso && x.num === mPNum);
    const curRowIdx = periodosList.findIndex(x => !x.receso && x.num === periodoNum);
    if (mRowIdx === -1 || curRowIdx === -1) continue;

    if (curRowIdx >= mRowIdx && curRowIdx < mRowIdx + (m.rowSpan || 1)) {
      return true;
    }
  }
  return false;
}

function renderCeldasClaseHum(d, periodNum, fKey, sedeKey, merges, matrizCustom, puedeEditar, modo, cursosDia) {
  const numCols = (modo === 'multi') ? cursosDia.length : 1;
  const basePeriodosFranja = getPeriodosSede(fKey, sedeKey, 'hum');
  let html = '';

  for (let cIdx = 0; cIdx < numCols; cIdx++) {
    if (isCellCoveredByMerge(merges, 'hum', d, periodNum, cIdx, basePeriodosFranja)) {
      continue;
    }

    const cellKey = `hum_${d}_${periodNum}_${cIdx}`;
    const mergeInfo = merges[cellKey] || { rowSpan: 1, colSpan: 1 };
    const mRowSpan = mergeInfo.rowSpan || 1;
    const mColSpan = mergeInfo.colSpan || 1;

    let cellData = null;
    let celdaCustomDefinida = false;
    if (matrizCustom) {
      const customSlot = (matrizCustom[fKey] && matrizCustom[fKey][d] && matrizCustom[fKey][d][periodNum])
        ? matrizCustom[fKey][d][periodNum]
        : (matrizCustom[d] && matrizCustom[d][periodNum] ? matrizCustom[d][periodNum] : null);
      if (customSlot) {
        if (Array.isArray(customSlot)) {
          // 1. Buscar coincidencia por nombre de curso o etiqueta de índice
          const targetCurso = (cursosDia && cursosDia[cIdx]) ? String(cursosDia[cIdx]).trim().toLowerCase() : '';
          const targetCursoIdx1 = 'curso ' + (cIdx + 1);
          const targetCursoIdx2 = 'esa ' + (cIdx + 1) + '°';
          const targetCursoIdx3 = 'esa ' + (cIdx + 1);

          let found = customSlot.find(item => {
            if (!item) return false;
            const cName = String(item.curso || item.sub || '').trim().toLowerCase();
            return (targetCurso && cName === targetCurso) || cName === targetCursoIdx1 || cName === targetCursoIdx2 || cName === targetCursoIdx3;
          });

          // 2. Si no coincide por nombre, usar el índice de columna directo
          if (!found && customSlot[cIdx] !== undefined && customSlot[cIdx] !== null) {
            found = customSlot[cIdx];
          }

          if (found) {
            cellData = found;
            celdaCustomDefinida = true;
          }
        } else if (cIdx === 0 && customSlot.materia !== undefined) {
          cellData = customSlot;
          celdaCustomDefinida = true;
        }
      }
    }
    if (!celdaCustomDefinida || !cellData) {
      cellData = { materia: 'Libre', docente: '—', sub: '' };
    }

    const incluirBth = getSedeLsData('cea_horario_incluir_bth', true, sedeKey, 'hum');
    if (!incluirBth && cellData) {
      let mat = cellData.materia || '';
      let sub = cellData.sub || '';
      let areaRef = cellData.areaRef || '';
      if (cellData.esBTH || sub.includes('BTH') || mat.startsWith('Módulo') || sub.startsWith('(')) {
        if (sub.includes('Matemática') || areaRef === 'Matemática') {
          mat = 'Matemática'; sub = '';
        } else if (sub.includes('Ciencias Naturales') || areaRef === 'Ciencias Naturales') {
          mat = 'Ciencias Naturales'; sub = '';
        } else if (sub.includes('Ciencias Sociales') || areaRef === 'Ciencias Sociales') {
          mat = 'Ciencias Sociales'; sub = '';
        } else if (sub.includes('Lenguaje') || sub.includes('Comunicación') || areaRef === 'Lenguaje') {
          mat = 'Lenguaje'; sub = '';
        } else if (areaRef) {
          mat = areaRef; sub = '';
        } else {
          sub = '';
        }
      }
      cellData = { ...cellData, materia: mat, sub: sub };
    }

    const esLibre = (!cellData || !cellData.materia || cellData.materia === 'Libre' || cellData.materia === 'Blanco');
    const isDayEndCls = (cIdx === numCols - 1) ? 'day-group-end' : '';

    if (esLibre) {
      if (puedeEditar) {
        html += `
          <td class="${isDayEndCls}" ${mRowSpan > 1 ? `rowspan="${mRowSpan}"` : ''} ${mColSpan > 1 ? `colspan="${mColSpan}"` : ''} onclick="abrirPopoverEdicionCelda(event, '${d}', ${periodNum}, ${cIdx}, 'hum', '${sedeKey}')" style="padding:4px;vertical-align:top;cursor:pointer">
            <div class="gestor-cell-card gestor-cell-free">
              <div class="gestor-cell-free-label">
                <svg viewBox="0 0 24 24" width="11" height="11" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/><line x1="12" y1="8" x2="12" y2="16"/><line x1="8" y1="12" x2="16" y2="12"/></svg>
                <span>Libre (Asignar)</span>
              </div>
            </div>
          </td>
        `;
      } else {
        html += `
          <td class="${isDayEndCls}" ${mRowSpan > 1 ? `rowspan="${mRowSpan}"` : ''} ${mColSpan > 1 ? `colspan="${mColSpan}"` : ''} style="padding:4px;vertical-align:top;background:transparent">
            <div class="gestor-cell-card gestor-cell-free-normal" style="background:transparent;border:none;box-shadow:none;min-height:36px"></div>
          </td>
        `;
      }
    } else {
      const st = obtenerEstilosMateria(cellData.areaRef || (cellData.sub ? cellData.sub.replace(/[()]/g, '').replace('BTH ', '') : '') || cellData.materia, 'hum');
      const colorMateria = st.bg;
      const colorTexto = st.txt;
      const mLow = String(cellData.materia || '').toLowerCase().trim();
      const esCienciasNat = mLow.includes('natural') || mLow.includes('biolog') || mLow.includes('físic') || mLow.includes('fisic') || mLow.includes('químic') || mLow.includes('quimic') || mLow.includes('salud') || (mLow.includes('ciencias') && !mLow.includes('social'));
      const esLenguaje = mLow.includes('lengua') || mLow.includes('literat') || mLow.includes('redacc') || mLow.includes('comunicac');
      const esCienciasSociales = mLow.includes('social') || mLow.includes('histor') || mLow.includes('cívic') || mLow.includes('civic') || mLow.includes('geograf');

      const paletaActivaActual = (typeof lsGet === 'function') ? lsGet('cea_horario_paleta_colores', 'multicolor') : 'multicolor';
      const isEco = (paletaActivaActual === 'economica');
      // En la paleta verde institucional, ni Ciencias Sociales ni Lenguaje deben tener sombra de texto.
      // En la paleta económica (ahorro de tinta), ninguna materia tiene sombra para máxima legibilidad.
      // En la paleta multicolor oficial, se mantiene intacta su sombra con total fidelidad.
      const tieneSombraNegra = (paletaActivaActual === 'verde') 
        ? esCienciasNat 
        : ((paletaActivaActual === 'economica') ? false : (esCienciasNat || esLenguaje || esCienciasSociales));
      const sombraTextoStyle = tieneSombraNegra ? 'text-shadow: 0 1px 2px rgba(0, 0, 0, 0.5) !important;' : 'text-shadow: none !important;';
      const extraCsClass = ((esLenguaje || esCienciasSociales) && paletaActivaActual === 'multicolor') ? ' cs-print-shadow' : '';
      const mostrarDocentes = lsGet('cea_horario_mostrar_docentes', true);

      const cardBg = isEco ? '#ffffff' : colorMateria;
      const cardBorder = isEco ? (st.border || st.accent || colorMateria) : colorMateria;
      const cardBorderWidth = isEco ? '2px' : '1px';
      const titleColor = isEco ? (st.accent || colorMateria) : colorTexto;
      const teacherColor = isEco ? '#334155' : colorTexto;
      const subColor = isEco ? '#64748b' : colorTexto;

      if (mostrarDocentes) {
        html += `
          <td class="${isDayEndCls}" ${mRowSpan > 1 ? `rowspan="${mRowSpan}"` : ''} ${mColSpan > 1 ? `colspan="${mColSpan}"` : ''} ${puedeEditar ? `onclick="abrirPopoverEdicionCelda(event, '${d}', ${periodNum}, ${cIdx}, 'hum', '${sedeKey}')"` : ''} style="padding:0.5px; vertical-align:middle; text-align:center; ${puedeEditar ? 'cursor:pointer' : ''}">
            <div class="gestor-cell-card ${mRowSpan > 1 ? (mRowSpan >= 3 ? 'merged-card merged-card-3' : 'merged-card') : ''}" style="background-color: ${cardBg} !important; background: ${cardBg} !important; border: ${cardBorderWidth} solid ${cardBorder} !important; border-color: ${cardBorder} !important; border-radius: 6px; color: ${titleColor} !important; min-height: 100%; height: 100%; width: 100%; margin: 0; padding: 2px 1px; box-sizing: border-box; display: flex; flex-direction: column; justify-content: center; align-items: center; -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important;">
              <div class="gestor-cell-header" style="background: transparent !important; color: ${titleColor} !important; padding: 1px;">
                <span class="gestor-cell-subject-title${extraCsClass}" style="color: ${titleColor} !important; font-weight:800; ${sombraTextoStyle}">${escapeHTML(cellData.materia || 'Asignatura')}</span>
              </div>
              <div class="gestor-cell-body" style="background: transparent !important; flex:1; display:flex; flex-direction:column; justify-content:center; align-items:center;">
                <div class="gestor-cell-teacher" style="color: ${teacherColor} !important; opacity: 0.95; font-weight:700;">
                  <svg viewBox="0 0 24 24" width="10" height="10" fill="none" stroke="currentColor" stroke-width="2" style="display:inline-block;vertical-align:-1px;margin-right:2px;opacity:0.85"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>
                  <span style="color: ${teacherColor} !important;">${escapeHTML(cellData.docente || 'Docente')}</span>
                </div>
                ${cellData.sub ? `<div class="gestor-cell-sub" style="opacity:0.92;color:${subColor} !important;line-height:1.08;margin-top:1px">${escapeHTML(cellData.sub)}</div>` : ''}
              </div>
              ${puedeEditar ? `
                <span class="gestor-edit-badge" title="Editar celda o fusionar">
                  <svg viewBox="0 0 24 24" width="10" height="10" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
                </span>
              ` : ''}
            </div>
          </td>
        `;
      } else {
        html += `
          <td class="${isDayEndCls}" ${mRowSpan > 1 ? `rowspan="${mRowSpan}"` : ''} ${mColSpan > 1 ? `colspan="${mColSpan}"` : ''} ${puedeEditar ? `onclick="abrirPopoverEdicionCelda(event, '${d}', ${periodNum}, ${cIdx}, 'hum', '${sedeKey}')"` : ''} style="padding:0.5px; vertical-align:middle; text-align:center; ${puedeEditar ? 'cursor:pointer' : ''}">
            <div class="gestor-cell-card gestor-cell-subject-only ${mRowSpan > 1 ? (mRowSpan >= 3 ? 'merged-card merged-card-3' : 'merged-card') : ''}" style="background-color: ${cardBg} !important; background: ${cardBg} !important; border: ${cardBorderWidth} solid ${cardBorder} !important; border-color: ${cardBorder} !important; border-radius: 6px; color: ${titleColor} !important; min-height: 100%; height: 100%; width: 100%; margin: 0; padding: 2px 1px; box-sizing: border-box; display: flex; flex-direction: column; justify-content: center; align-items: center; -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important;">
              <div class="gestor-cell-header" style="background: transparent !important; flex: 1; display: flex; flex-direction: column; justify-content: center; align-items: center; min-height: 32px; padding: 2px 1px;">
                <span class="gestor-cell-subject-title${extraCsClass}" style="color: ${titleColor} !important; font-weight:800; ${sombraTextoStyle}">${escapeHTML(cellData.materia || 'Asignatura')}</span>
                ${cellData.sub ? `<div class="gestor-cell-sub" style="opacity:0.92;color:${subColor} !important;line-height:1.08;margin-top:1px;text-align:center">${escapeHTML(cellData.sub)}</div>` : ''}
              </div>
              ${puedeEditar ? `
                <span class="gestor-edit-badge" title="Editar celda">
                  <svg viewBox="0 0 24 24" width="10" height="10" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
                </span>
              ` : ''}
            </div>
          </td>
        `;
      }
    }
  }

  return html;
}


function cargarHorariosMatriz(turno = turnoHorarioActual) {
  if (typeof sincronizarPublicoHorariosYAtencionDesdeCentral === 'function') {
    sincronizarPublicoHorariosYAtencionDesdeCentral();
  }

  const container = document.getElementById('tabla-horario-matriz-container');
  if (!container) return;

  const paletaActiva = (typeof lsGet === 'function') ? lsGet('cea_horario_paleta_colores', 'multicolor') : 'multicolor';
  container.setAttribute('data-paleta', paletaActiva);
  if (paletaActiva === 'economica') {
    container.classList.add('paleta-economica');
  } else {
    container.classList.remove('paleta-economica');
  }

  renderizarBarraSedesHorarios();
  actualizarBotonModoEdicion();
  sincronizarCheckboxesFranjas(turno);

  const vistaUnificada = lsGet('cea_vista_unificada_sedes', false);
  const curSede = vistaUnificada ? 'central' : getHorarioSedeActiveKey(turno);
  const puedeEditar = tienePermisoEdicionHorarios();
  const areaLabel = (turno === 'hum') ? 'Área Humanística (BTH)' : 'Área Técnica (TTP)';

  let html = renderTablaMatrizParaSede(curSede, turno, false);

  if (vistaUnificada) {
    const sedesList = obtenerListaSedesEducativas(turno);
    const subcentros = sedesList.filter(s => s.key !== 'central');

    if (subcentros.length > 0) {
      subcentros.forEach(sub => {
        html += `
          <div class="subcentro-bloque-unificado">
            <div class="subcentro-bloque-titulo">
              <div style="display:flex;align-items:center;gap:10px">
                <svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2.2" style="color:var(--verde-dark)"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"/><circle cx="12" cy="10" r="3"/></svg>
                <span style="font-weight:900;color:var(--verde-dark);font-size:1.05rem">SUBCENTRO / ANEXO: ${escapeHTML(sub.nombre.toUpperCase())}</span>
              </div>
              <span style="font-size:0.82rem;font-weight:700;color:var(--text-sec)">${areaLabel} • Horario Oficial Integrado</span>
            </div>
            ${renderTablaMatrizParaSede(sub.key, turno, true)}
          </div>
        `;
      });
    } else {
      html += `
        <div class="subcentro-bloque-unificado">
          <div class="subcentro-bloque-titulo" style="background:var(--verde-light);border-color:var(--verde)">
            <div style="display:flex;align-items:center;gap:10px">
              <svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2.2" style="color:var(--verde-dark)"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"/><circle cx="12" cy="10" r="3"/></svg>
              <span style="font-weight:900;color:var(--verde-dark);font-size:1.00rem">SUBCENTROS / ANEXOS (${areaLabel})</span>
            </div>
            ${puedeEditar ? `
              <button type="button" class="btn-agregar-subcentro-style" onclick="abrirModalAgregarSubcentro()" style="padding:4px 12px;font-size:0.80rem">
                + Agregar Subcentro
              </button>
            ` : '<span style="font-size:0.82rem;font-weight:700;color:var(--text-sec)">Sin Subcentros Configurados</span>'}
          </div>
          <div style="padding:16px 20px;text-align:center;color:var(--text-sec);font-size:0.88rem;background:var(--bg-card);border-radius:12px;border:1px dashed var(--border-col)">
            Aún no has agregado subcentros o anexos para esta área. Al hacer clic en <strong>"+ Agregar Subcentro"</strong>, su horario aparecerá automáticamente acoplado aquí abajo.
          </div>
        </div>
      `;
    }
  }

  container.innerHTML = html;
}

function renderTablaMatrizParaSede(sedeKey, turno = 'hum', esSubcentro = false) {
  const puedeEditar = tienePermisoEdicionHorarios();
  const merges = getSedeLsData('cea_horarios_merges', {}, sedeKey, turno);
  const franjasActivas = getFranjasActivas(turno);

  if (turno === 'hum') {
    const rawDias = getSedeLsData('cea_bth_dias_activos', HORARIOS_BTH_CANONICO.diasDefault, sedeKey, 'hum');
    let diasActivos = ordenarDiasCronologico(rawDias);
    if (!Array.isArray(diasActivos) || diasActivos.length === 0) {
      diasActivos = ['Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes'];
    }
    const hMatriz = getSedeLsData('cea_horarios_matriz', HORARIOS_MATRIZ_DEFAULT, sedeKey, 'hum');
    const matrizCustom = (hMatriz && hMatriz.hum && hMatriz.hum.matriz) ? hMatriz.hum.matriz : null;

    const diasTarde = diasActivos.filter(d => getTurnoDiaHum(d, sedeKey) === 'tarde');
    const diasManana = diasActivos.filter(d => getTurnoDiaHum(d, sedeKey) === 'mañana');
    const diasNoche = diasActivos.filter(d => getTurnoDiaHum(d, sedeKey) === 'noche');

    const hayDiasManana = (diasManana.length > 0);
    const hayDiasTarde = (diasTarde.length > 0);
    const hayDiasNoche = (diasNoche.length > 0);

    const gruposTurno = [];
    if (hayDiasManana) gruposTurno.push({ key: 'manana', label: 'MAÑANA', subClass: 'sub-manana', colHorarioClass: 'col-horario-manana', dias: diasManana });
    if (hayDiasTarde) gruposTurno.push({ key: 'tarde', label: 'TARDE', subClass: 'sub-tarde', colHorarioClass: '', dias: diasTarde });
    if (hayDiasNoche) gruposTurno.push({ key: 'noche', label: 'NOCHE', subClass: 'sub-noche', colHorarioClass: 'col-horario-noche', dias: diasNoche });

    gruposTurno.forEach(g => {
      let groupCols = 0;
      g.dias.forEach(d => {
        const modo = getModoDocenteDia('hum', d);
        const cursos = obtenerCursosParaDiaBTH(d);
        groupCols += (modo === 'mono' ? 1 : cursos.length);
      });
      g.cols = groupCols;
    });

    const totalTableCols = 1 + gruposTurno.reduce((acc, g) => acc + 1 + g.cols + (g.dias.length > 1 ? g.dias.length - 1 : 0), 0);
    const mostrarTurnos = lsGet('cea_horario_mostrar_turnos', true);

    let html = `
      ${(puedeEditar && !esSubcentro) ? renderPanelEdicionAccesible('hum') : ''}

      <div class="ttp-header-title" style="position:relative">
        <h2>HORARIO DE FORMACIÓN HUMANÍSTICA (EPJA)</h2>
        <h3>GESTIÓN 2026</h3>
        <button type="button" class="btn-submit horario-toolbar-no-print" onclick="imprimirHorarioActual('hum')" title="Imprimir Horario Oficial" aria-label="Imprimir Horario Oficial" style="position:absolute;right:12px;top:0;background:var(--verde-dark);width:40px;height:40px;padding:0;display:inline-flex;align-items:center;justify-content:center;border-radius:50%;box-shadow:0 3px 10px rgba(0,0,0,0.18);border:none;cursor:pointer;z-index:5">
          <svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2.2"><polyline points="6 9 6 2 18 2 18 9"/><path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"/><rect x="6" y="14" width="12" height="8"/></svg>
        </button>
      </div>

      <div class="gestor-schedule-wrap">
        <table class="gestor-schedule-table">
          <thead>
            <tr>
              <th rowspan="2" class="gestor-th-corner col-periodo" style="width:28px;min-width:28px;max-width:30px;background:#ffffff!important;color:#334155!important;border:none!important;vertical-align:middle!important;">
                <span class="gestor-th-corner-text" style="color:#334155!important;font-weight:900!important;font-size:0.65rem!important;display:block!important;text-align:center!important;">N°</span>
              </th>
              ${gruposTurno.map(g => `
                <th rowspan="2" class="gestor-th-corner col-horario ${g.colHorarioClass}" style="width:50px;min-width:50px;max-width:54px;background:#ffffff!important;color:#334155!important;border:none!important;vertical-align:middle!important;">
                  <span class="gestor-th-corner-text" style="color:#334155!important;font-weight:900!important;font-size:0.65rem!important;display:block!important;text-align:center!important;">Hora</span>
                </th>
                ${g.dias.map((d, dIdx) => {
                  const modo = getModoDocenteDia('hum', d);
                  const cursos = obtenerCursosParaDiaBTH(d);
                  const colSpan = (modo === 'multi') ? cursos.length : 1;
                  const labelModo = (modo === 'mono') ? ' (1 Docente)' : '';
                  const dNorm = d.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
                  const diaClass = 'dia-' + dNorm;
                  const isLastInGrp = (dIdx === g.dias.length - 1);
                  return `
                    <th colspan="${colSpan}" class="gestor-th-day ${diaClass} day-group-end ${puedeEditar ? 'clickable-day' : ''}" ${puedeEditar ? `onclick="abrirModalCambiarTurnoDia('${d}', 'hum')"` : ''}>
                      <div class="gestor-th-day-box ${diaClass}-box" style="display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;">
                        <span>${d.toUpperCase()}${labelModo}</span>
                        ${mostrarTurnos ? `<span class="ttp-day-sub ${g.subClass}">${g.label}</span>` : ''}
                        ${puedeEditar ? `
                          <div style="display:inline-flex;gap:3px;margin-top:2px" onclick="event.stopPropagation()">
                            <button type="button" class="btn-col-control btn-col-add" onclick="agregarColumnaDia('${d}','hum')" title="Agregar columna en ${d}">+ Col</button>
                            <button type="button" class="btn-col-control btn-col-remove" onclick="quitarColumnaDia('${d}','hum')" title="Quitar columna en ${d}">- Col</button>
                            <button type="button" class="btn-col-control btn-col-cfg" onclick="abrirModalConfigurarPeriodosDia('${d}','hum')" title="Configurar periodos y recreo de ${d}"><svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2.3"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1 0 2.83 2 2 0 0 1 0-2.83l.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-2 2 2 2 0 0 1-2-2v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83 0 2 2 0 0 1 0-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1-2-2 2 2 0 0 1 2-2h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 0-2.83 2 2 0 0 1 2.83 0l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 2-2 2 2 0 0 1 2 2v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 0 1 2.83 0 2 2 0 0 1 0 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 2 2 2 2 0 0 1-2 2h-.09a1.65 1.65 0 0 0-1.51 1z"/></svg></button>
                          </div>
                        ` : ''}
                      </div>
                    </th>
                    ${!isLastInGrp ? `<th class="day-red-separator"></th>` : ''}`;
                }).join('')}
              `).join('')}
            </tr>
            <tr>
              ${gruposTurno.map(g => g.dias.map((d, dIdx) => {
                const modo = getModoDocenteDia('hum', d);
                const isLastInGrp = (dIdx === g.dias.length - 1);
                let trackHtml = '';
                if (modo === 'mono') {
                  trackHtml = `<th class="gestor-th-track day-group-end"><div class="gestor-th-track-box"><span class="gestor-th-track-text">Grupo General / Docente Asignado</span></div></th>`;
                } else {
                  const cursos = obtenerCursosParaDiaBTH(d);
                  trackHtml = cursos.map((c, colIdx) => {
                    const isEnd = (colIdx === cursos.length - 1) ? 'day-group-end' : '';
                    if (puedeEditar) {
                      return `
                        <th class="gestor-th-track ${isEnd}" style="padding:1px;border:none!important;background:transparent!important;vertical-align:stretch;height:100%">
                          <div class="bth-curso-select-wrap" style="position:relative;background:#ffffff!important;border:1.5px solid #94a3b8!important;border-radius:5px!important;padding:1px 0px;width:100%;height:100%;min-height:28px;box-sizing:border-box;display:flex;align-items:center;justify-content:center;text-align:center;">
                            <span class="bth-curso-label-text" style="font-family:Arial,sans-serif;font-size:0.52rem;font-weight:900;line-height:1.05;color:#334155;text-transform:uppercase;white-space:normal;word-break:break-word;overflow-wrap:break-word;text-align:center;display:block;width:100%;pointer-events:none;">${escapeHTML(c)}</span>
                            <select onchange="cambiarCursoColumnaDia('${d}', ${colIdx}, this.value)" style="position:absolute;top:0;left:0;width:100%;height:100%;opacity:0;cursor:pointer;z-index:2;" title="Cambiar grupo o nivel de esta columna">
                              <optgroup label="Grupos">
                                ${['Avanzados', 'Aplicados', 'Complementarios', 'Especializados'].map(opt => `<option value="${opt}" ${opt === c ? 'selected' : ''}>${opt}</option>`).join('')}
                              </optgroup>
                              <optgroup label="Niveles BTH">
                                ${['Técnico Básico', 'Técnico Auxiliar', 'Técnico Medio I', 'Técnico Medio II'].map(opt => `<option value="${opt}" ${opt === c ? 'selected' : ''}>${opt}</option>`).join('')}
                              </optgroup>
                            </select>
                          </div>
                        </th>
                      `;
                    } else {
                      return `<th class="gestor-th-track ${isEnd}"><div class="gestor-th-track-box"><span class="gestor-th-track-text">${escapeHTML(c)}</span></div></th>`;
                    }
                  }).join('');
                }
                return trackHtml + (!isLastInGrp ? `<th class="day-red-separator"></th>` : '');
              }).join('')).join('')}
            </tr>
          </thead>
          <tbody>
    `;

    franjasActivas.forEach((fKey, fIdx) => {
      if (fIdx > 0) {
        const fTitle = (fKey === 'tarde')
          ? 'RECREO GENERAL / ALMUERZO Y TRANSICIÓN A TURNO TARDE'
          : 'RECREO DE LA TARDE Y TRANSICIÓN A TURNO NOCHE';
        html += `
          <tr class="gestor-row-franja-divider">
            <td colspan="${totalTableCols}">
              <div class="franja-divider-banner">
                <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2.2"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
                <span>${fTitle}</span>
              </div>
            </td>
          </tr>
        `;
      }

      const periodosFranja = getPeriodosSede(fKey, sedeKey, 'hum');
      const periodosManana = getPeriodosSede('manana', sedeKey, 'hum');
      const periodosTarde = getPeriodosSede('tarde', sedeKey, 'hum');
      const periodosNoche = getPeriodosSede('noche', sedeKey, 'hum');

      periodosFranja.forEach((p, pIdx) => {
        const pManana = periodosManana[pIdx] || p;
        const pTarde = periodosTarde[pIdx] || p;
        const pNoche = periodosNoche[pIdx] || p;

        const isRowReceso = p.receso;
        const isEven = (pIdx % 2 === 1);

        html += `
          <tr class="${isRowReceso ? 'gestor-row-recreo' : (isEven ? 'gestor-row-even' : '')}">
            <td class="gestor-td-periodo col-periodo" style="${isRowReceso ? 'background:#e9ecef;padding:4px 2px' : ''}">
              <div style="display:flex;flex-direction:column;align-items:center;gap:2px">
                <span class="gestor-periodo-badge ${isRowReceso ? 'recreo' : ''}">${isRowReceso ? '' : `${p.num}º`}</span>
                ${puedeEditar ? `
                  <button type="button" class="btn-del-periodo-tabla" onclick="eliminarPeriodoPorIndice(${pIdx}, 'hum', '${fKey}', '${sedeKey}')" title="Eliminar este periodo del horario">
                    <svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2.5"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
                    <span>Borrar</span>
                  </button>
                ` : ''}
              </div>
            </td>
            ${gruposTurno.map(g => {
              const pGrp = (g.key === 'manana' ? pManana : (g.key === 'tarde' ? pTarde : pNoche));
              const hStart = pGrp.inicio || (g.key === 'manana' ? '08:00' : (g.key === 'tarde' ? '14:00' : '19:00'));
              const hFin = pGrp.fin || (g.key === 'manana' ? '08:40' : (g.key === 'tarde' ? '14:40' : '19:40'));

              let gCells = `
                <td class="gestor-td-horario col-horario ${g.colHorarioClass}" style="${isRowReceso ? 'background:#e9ecef;' : ''}${puedeEditar ? 'cursor:pointer' : ''}" ${puedeEditar ? `onclick="editarHoraPeriodoDirecto(${pIdx}, 'hum', '${g.key}', '${sedeKey}')"` : ''}>
                  <div class="gestor-time-stack">
                    <span class="gestor-time-start">${hStart}</span>
                    <span class="gestor-time-end">${hFin}</span>
                    ${puedeEditar ? `<span class="gestor-time-edit-btn no-print-edit" style="font-size:0.58rem;color:var(--verde-dark);font-weight:700">Editar</span>` : ''}
                  </div>
                </td>
              `;

              g.dias.forEach((d, dIdx) => {
                const modo = getModoDocenteDia('hum', d);
                const cursosDia = obtenerCursosParaDiaBTH(d);
                const numCols = (modo === 'mono') ? 1 : cursosDia.length;
                const slot = calcularSlotDia(d, pIdx, 'hum', sedeKey);
                const isLastInGrp = (dIdx === g.dias.length - 1);

                if (slot.isReceso) {
                  gCells += `
                    <td colspan="${numCols}" class="gestor-recreo-td day-group-end">
                      <div class="gestor-recreo-banner">
                        <span class="gestor-recreo-text">RECREO</span>
                      </div>
                    </td>
                  `;
                } else {
                  gCells += renderCeldasClaseHum(d, slot.periodNum, fKey, sedeKey, merges, matrizCustom, puedeEditar, modo, cursosDia);
                }

                if (!isLastInGrp) {
                  gCells += `<td class="day-red-separator"></td>`;
                }
              });

              return gCells;
            }).join('')}
          </tr>
        `;
      });
    });

    html += `
          </tbody>
        </table>
      </div>

      <!-- Tarjeta Oficial Inferior de Asignaciones BTH -->
      ${(() => {
        const curSedePrint = lsGet('cea_sede_activa', 'central');
  const incluirBth = getSedeLsData('cea_horario_incluir_bth', true, sedeKey, 'hum');
        if (!incluirBth) return '';
        const carreraBTHActiva = getSedeLsData('cea_bth_carrera_activa', 'Agropecuaria', sedeKey, 'hum');
        const bthData = (typeof CURRICULA_BTH_CARRERAS !== 'undefined' && CURRICULA_BTH_CARRERAS[carreraBTHActiva])
          ? CURRICULA_BTH_CARRERAS[carreraBTHActiva]
          : ((typeof CATALOGO_BTH_CARRERAS !== 'undefined' && CATALOGO_BTH_CARRERAS[carreraBTHActiva]) ? CATALOGO_BTH_CARRERAS[carreraBTHActiva] : { titulo: 'EDUCACIÓN TÉCNICA HUMANÍSTICA (BTH)', subtitulo: 'Malla Curricular Oficial' });
        const filasHumanistica = obtenerFilasHumanisticaBTH();
        const listaCarreras = (typeof CURRICULA_BTH_CARRERAS !== 'undefined') ? Object.keys(CURRICULA_BTH_CARRERAS) : [];

        return `
          <div class="bth-docentes-banner">
            <div style="background:var(--verde-dark);color:#ffffff;padding:6px 12px;font-weight:900;font-size:0.82rem;letter-spacing:0.5px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:6px">
              <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap">
                <span>${escapeHTML(bthData.titulo)}</span>
                ${puedeEditar ? `
                  <div class="bth-carrera-selector-wrap" title="Cambiar especialidad técnica BTH">
                    <span style="font-size:0.70rem;color:#d1fae5;font-weight:700">Cambiar especialidad:</span>
                    <select class="bth-carrera-select" onchange="cambiarCarreraBTH(this.value)" style="font-size:0.70rem;padding:2px 6px">
                      ${listaCarreras.map(c => `
                        <option value="${c}" ${c === carreraBTHActiva ? 'selected' : ''}>${c}</option>
                      `).join('')}
                    </select>
                  </div>
                ` : ''}
              </div>
              <span style="font-size:0.72rem;font-weight:600;opacity:0.85">${escapeHTML(bthData.subtitulo)}</span>
            </div>
            ${filasHumanistica.map((item, idx) => {
              const modsActuales = (typeof obtenerModulosOficialesDocente === 'function') ? obtenerModulosOficialesDocente(carreraBTHActiva, idx) : [];
              const todosModsCarrera = (typeof obtenerTodosModulosMallaOficial === 'function') ? obtenerTodosModulosMallaOficial(carreraBTHActiva) : [];
              const nivelesUnicos = [...new Set(todosModsCarrera.map(m => m.nivel))];
              const bthSt = obtenerEstilosMateria(item.area, 'hum');
              const bthAreaBg = bthSt.isEco ? '#ffffff' : bthSt.bg;
              const bthAreaTxt = bthSt.isEco ? bthSt.accent : bthSt.txt;
              const bthAreaBorder = bthSt.isEco ? `border: 2px solid ${bthSt.accent} !important;` : 'border:none;';
              const modLvlBg = bthSt.isEco ? '#ffffff' : bthSt.bg;
              const modLvlTxt = bthSt.isEco ? bthSt.accent : bthSt.txt;
              const modLvlBorder = bthSt.isEco ? `border: 1.5px solid ${bthSt.accent} !important;` : 'border:none !important;';
              const estaEditando = (typeof _bthFilaEditandoIdx !== 'undefined' && _bthFilaEditandoIdx === idx);

              return `
                <div class="bth-doc-row" style="background:#ffffff;padding:4px 8px;border-bottom:1px solid #e2e8f0;align-items:${estaEditando ? 'flex-start' : 'stretch'}">
                  <div style="height:100%;width:100%;display:flex;align-items:stretch">
                    <div class="bth-area-badge" style="background-color:${bthAreaBg} !important;background:${bthAreaBg} !important;color:${bthAreaTxt} !important;${bthAreaBorder}padding:5px 8px;border-radius:6px;font-weight:800;font-size:0.72rem;text-align:center;width:100%;height:100%;box-sizing:border-box;display:flex;align-items:center;justify-content:center;-webkit-print-color-adjust:exact;print-color-adjust:exact;">
                      ${puedeEditar ? `
                        <select class="bth-materia-select bth-select-no-print" style="background-color:transparent;color:${bthAreaTxt};border:none;font-weight:800;cursor:pointer;width:100%;height:100%;outline:none;font-size:0.72rem;padding:0;text-align:center;" onchange="cambiarMateriaFilaBTH(${idx}, this.value)" title="Cambiar materia humanística">
                          ${(typeof OPCIONES_MATERIAS_HUMANISTICA !== 'undefined' ? OPCIONES_MATERIAS_HUMANISTICA : []).map(opt => `
                            <option value="${opt.area}" ${opt.area === item.area ? 'selected' : ''}>${opt.area}</option>
                          `).join('')}
                        </select>
                        <span class="bth-print-only-text" style="display:none;font-weight:800;font-size:5.2pt;color:${bthAreaTxt} !important;">${escapeHTML(item.area)}</span>
                      ` : `
                        <span style="font-weight:800;font-size:0.72rem;color:${bthAreaTxt} !important;">${escapeHTML(item.area)}</span>
                      `}
                    </div>
                  </div>
                  <div style="font-weight:800;color:#0f172a;padding:0 6px;font-size:0.72rem;display:flex;align-items:center;height:100%;white-space:nowrap">
                    <span class="bth-doc-nombre" style="white-space:nowrap">${escapeHTML(item.docente)}</span>
                  </div>
                  <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;width:100%">
                    ${estaEditando ? `
                      <div class="bth-inline-edit-box">
                        <label style="display:block;font-size:0.75rem;font-weight:800;color:var(--verde-dark);margin-bottom:6px">
                          Módulos BTH de ${escapeHTML(item.area)} — ${escapeHTML(carreraBTHActiva)}:
                        </label>
                        <div style="display:flex;flex-direction:column;gap:8px;margin-bottom:8px">
                          ${[0, 1].map(mi => {
                            const modActual = modsActuales[mi];
                            const optsConSelected = nivelesUnicos.map(niv => {
                              const modsNiv = todosModsCarrera.filter(m => m.nivel === niv);
                              return `<optgroup label="${escapeHTML(niv)}">${modsNiv.map(m => `<option value="${escapeHTML(m.codigo)}" ${modActual && modActual.codigo === m.codigo ? 'selected' : ''}>${escapeHTML(m.codigo)} – ${escapeHTML(m.nombre)}</option>`).join('')}</optgroup>`;
                            }).join('');
                            return `
                              <div style="display:flex;align-items:center;gap:6px">
                                <span style="font-size:0.7rem;font-weight:800;color:#64748b;min-width:44px">Mód. ${mi + 1}:</span>
                                <select id="bth-mod-sel-${idx}-${mi}" class="bth-modulo-dropdown" style="flex:1">
                                  <option value="">— Seleccione un módulo —</option>
                                  ${optsConSelected}
                                </select>
                              </div>
                            `;
                          }).join('')}
                        </div>
                        <div class="bth-inline-actions">
                          <button type="button" class="btn-bth-inline-guardar" onclick="guardarEdicionInlineBTH('${escapeHTML(carreraBTHActiva)}', ${idx}, '${escapeHTML(item.area)}')">
                            <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg>
                            <span>Guardar</span>
                          </button>
                          <button type="button" class="btn-bth-inline-cancelar" onclick="cancelarEdicionInlineBTH()">
                            <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.5"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
                            <span>Cancelar</span>
                          </button>
                        </div>
                      </div>
                    ` : `
                      <div class="bth-modulos-display" style="flex:1;display:flex;flex-direction:column;gap:3px;width:100%">
                        ${modsActuales.length > 0 ? modsActuales.map(m => `
                          <div class="bth-mod-pill">
                            <span class="mod-lvl-badge" style="background-color:${modLvlBg} !important;background:${modLvlBg} !important;color:${modLvlTxt} !important;${modLvlBorder}-webkit-print-color-adjust:exact !important;print-color-adjust:exact !important;">${escapeHTML(m.nivel)}</span>
                            <span class="mod-num">${escapeHTML(m.codigo)}</span>
                            <span class="mod-tit">${escapeHTML(m.nombre)}</span>
                          </div>
                        `).join('') : '<span style="font-size:0.72rem;color:#94a3b8;font-style:italic">Sin módulos asignados</span>'}
                      </div>
                      ${puedeEditar ? `
                        <button type="button" class="btn-edit-modulo-bth" onclick="activarEdicionInlineBTH(${idx})" title="Editar módulos de la malla oficial">
                          <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.2"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 1 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
                          <span>Editar</span>
                        </button>
                      ` : ''}
                    `}
                  </div>
                </div>
              `;
            }).join('')}
          </div>
        `;
      })()}
    `;

    return html;
  } else {
    // ÁREA TÉCNICA (TTP)
    const rawDiasTec = getSedeLsData('cea_tec_dias_activos', ['Miércoles', 'Jueves', 'Viernes', 'Sábado'], sedeKey, 'tec');
    let diasActivosTec = ordenarDiasCronologico(rawDiasTec);
    if (!Array.isArray(diasActivosTec) || diasActivosTec.length === 0) {
      diasActivosTec = ['Miércoles', 'Jueves', 'Viernes', 'Sábado'];
    }
    const hMatriz = getSedeLsData('cea_horarios_matriz', HORARIOS_MATRIZ_DEFAULT, sedeKey, 'tec');
    const dataTurno = hMatriz.tec || HORARIOS_MATRIZ_DEFAULT.tec;
    const mostrarDocentes = lsGet('cea_horario_mostrar_docentes', true);
    const etaLabel = obtenerTextoETACustom();

    const diasTarde = diasActivosTec.filter(d => getTurnoDiaTec(d) === 'tarde');
    const diasManana = diasActivosTec.filter(d => getTurnoDiaTec(d) === 'mañana');
    const diasNoche = diasActivosTec.filter(d => getTurnoDiaTec(d) === 'noche');
    const hayDiasTarde = (diasTarde.length > 0);
    const hayDiasManana = (diasManana.length > 0);
    const hayDiasNoche = (diasNoche.length > 0);
    const mostrarTurnos = lsGet('cea_horario_mostrar_turnos', true);

    let html = `
      ${(puedeEditar && !esSubcentro) ? renderPanelEdicionAccesible('tec') : ''}

      <div class="ttp-header-title" style="position:relative">
        <h2>HORARIO DE TÉCNICA TECNOLÓGICA PRODUCTIVA (TTP)</h2>
        <h3>GESTIÓN 2026</h3>
        <button type="button" class="btn-submit horario-toolbar-no-print" onclick="imprimirHorarioActual('tec')" title="Imprimir Horario Oficial" aria-label="Imprimir Horario Oficial" style="position:absolute;right:12px;top:0;background:var(--verde-dark);width:40px;height:40px;padding:0;display:inline-flex;align-items:center;justify-content:center;border-radius:50%;box-shadow:0 3px 10px rgba(0,0,0,0.18);border:none;cursor:pointer;z-index:5">
          <svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2.2"><polyline points="6 9 6 2 18 2 18 9"/><path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"/><rect x="6" y="14" width="12" height="8"/></svg>
        </button>
      </div>

      <div class="gestor-schedule-wrap">
        <table class="gestor-schedule-table ttp-table">
          <thead>
            <tr>
              <th class="gestor-th-corner col-periodo" style="width:28px;min-width:28px;max-width:30px;">
                <span class="gestor-th-corner-text">N°</span>
              </th>

              ${hayDiasTarde ? `
                <th class="gestor-th-corner col-horario" style="width:50px;min-width:50px;max-width:54px;">
                  <span class="gestor-th-corner-text">HORA</span>
                </th>
                ${diasTarde.map(d => {
                  const dNorm = d.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
                  const diaClass = 'dia-' + dNorm;
                  return `
                  <th class="gestor-th-day ttp-th-day ${diaClass} day-group-end ${puedeEditar ? 'clickable-day' : ''}" ${puedeEditar ? `onclick="abrirModalCambiarTurnoDiaTec('${d}')"` : ''}>
                    <div class="ttp-day-header-box ${diaClass}-box">
                      <span class="ttp-day-name">${d.toUpperCase()}</span>
                      ${mostrarTurnos ? `<span class="ttp-day-sub sub-tarde">TURNO TARDE</span>` : ''}
                      ${puedeEditar ? `
                        <div style="display:inline-flex;gap:3px;margin-top:2px" onclick="event.stopPropagation()">
                          <button type="button" class="btn-col-control btn-col-cfg" onclick="abrirModalConfigurarPeriodosDia('${d}','tec')" title="Configurar periodos y recreo de ${d}"><svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2.3"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1 0 2.83 2 2 0 0 1-2.83 0l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-2 2 2 2 0 0 1-2-2v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83 0 2 2 0 0 1 0-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1-2-2 2 2 0 0 1 2-2h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 0-2.83 2 2 0 0 1 2.83 0l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 2-2 2 2 0 0 1 2 2v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 0 1 2.83 0 2 2 0 0 1 0 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 2 2 2 2 0 0 1-2 2h-.09a1.65 1.65 0 0 0-1.51 1z"/></svg></button>
                        </div>
                      ` : ''}
                    </div>
                  </th>
                `;}).join('')}
              ` : ''}

              ${hayDiasManana ? `
                <th class="gestor-th-corner col-horario col-horario-manana" style="width:50px;min-width:50px;max-width:54px;">
                  <span class="gestor-th-corner-text">HORA</span>
                </th>
                ${diasManana.map(d => {
                  const dNorm = d.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
                  const diaClass = 'dia-' + dNorm;
                  return `
                  <th class="gestor-th-day ttp-th-day ${diaClass} day-group-end ${puedeEditar ? 'clickable-day' : ''}" ${puedeEditar ? `onclick="abrirModalCambiarTurnoDiaTec('${d}')"` : ''}>
                    <div class="ttp-day-header-box ${diaClass}-box">
                      <span class="ttp-day-name">${d.toUpperCase()}</span>
                      ${mostrarTurnos ? `<span class="ttp-day-sub sub-manana">TURNO MAÑANA</span>` : ''}
                      ${puedeEditar ? `
                        <div style="display:inline-flex;gap:3px;margin-top:2px" onclick="event.stopPropagation()">
                          <button type="button" class="btn-col-control btn-col-cfg" onclick="abrirModalConfigurarPeriodosDia('${d}','tec')" title="Configurar periodos y recreo de ${d}"><svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2.3"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1 0 2.83 2 2 0 0 1-2.83 0l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-2 2 2 2 0 0 1-2-2v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83 0 2 2 0 0 1 0-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1-2-2 2 2 0 0 1 2-2h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 0-2.83 2 2 0 0 1 2.83 0l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 2-2 2 2 0 0 1 2 2v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 0 1 2.83 0 2 2 0 0 1 0 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 2 2 2 2 0 0 1-2 2h-.09a1.65 1.65 0 0 0-1.51 1z"/></svg></button>
                        </div>
                      ` : ''}
                    </div>
                  </th>
                `;}).join('')}
              ` : ''}

              ${hayDiasNoche ? `
                <th class="gestor-th-corner col-horario col-horario-noche" style="width:50px;min-width:50px;max-width:54px;">
                  <span class="gestor-th-corner-text">HORA</span>
                </th>
                ${diasNoche.map(d => {
                  const dNorm = d.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
                  const diaClass = 'dia-' + dNorm;
                  return `
                  <th class="gestor-th-day ttp-th-day ${diaClass} day-group-end ${puedeEditar ? 'clickable-day' : ''}" ${puedeEditar ? `onclick="abrirModalCambiarTurnoDiaTec('${d}')"` : ''}>
                    <div class="ttp-day-header-box ${diaClass}-box">
                      <span class="ttp-day-name">${d.toUpperCase()}</span>
                      ${mostrarTurnos ? `<span class="ttp-day-sub sub-noche">TURNO NOCHE</span>` : ''}
                      ${puedeEditar ? `
                        <div style="display:inline-flex;gap:3px;margin-top:2px" onclick="event.stopPropagation()">
                          <button type="button" class="btn-col-control btn-col-cfg" onclick="abrirModalConfigurarPeriodosDia('${d}','tec')" title="Configurar periodos y recreo de ${d}"><svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2.3"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1 0 2.83 2 2 0 0 1-2.83 0l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-2 2 2 2 0 0 1-2-2v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83 0 2 2 0 0 1 0-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1-2-2 2 2 0 0 1 2-2h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 0-2.83 2 2 0 0 1 2.83 0l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 2-2 2 2 0 0 1 2 2v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 0 1 2.83 0 2 2 0 0 1 0 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 2 2 2 2 0 0 1-2 2h-.09a1.65 1.65 0 0 0-1.51 1z"/></svg></button>
                        </div>
                      ` : ''}
                    </div>
                  </th>
                `;}).join('')}
              ` : ''}
            </tr>
          </thead>
          <tbody>
    `;

    franjasActivas.forEach((fKey, fIdx) => {
      if (fIdx > 0) {
        const fTitle = (fKey === 'tarde')
          ? 'RECREO GENERAL / ALMUERZO Y TRANSICIÓN A TURNO TARDE'
          : 'RECREO DE LA TARDE Y TRANSICIÓN A TURNO NOCHE';
        html += `
          <tr class="gestor-row-franja-divider">
            <td colspan="${diasActivosTec.length + (hayDiasTarde ? 1 : 0) + (hayDiasManana ? 1 : 0) + (hayDiasNoche ? 1 : 0) + 1}">
              <div class="franja-divider-banner">
                <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2.2"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
                <span>${fTitle}</span>
              </div>
            </td>
          </tr>
        `;
      }

      const periodosTecFranja = getPeriodosSede(fKey, sedeKey, 'tec');

      periodosTecFranja.forEach((p, pIdx) => {
        const horaTardeInicio = p.inicio || '14:00';
        const horaTardeFin = p.fin || '14:40';

        const partsManana = (p.horaManana || '08:00 – 08:40').split('–').map(s => s.trim());
        const horaMananaInicio = partsManana[0] || p.inicio || '08:00';
        const horaMananaFin = partsManana[1] || p.fin || '08:40';

        const partsNoche = (p.horaNoche || '19:00 – 19:40').split('–').map(s => s.trim());
        const horaNocheInicio = partsNoche[0] || '19:00';
        const horaNocheFin = partsNoche[1] || '19:40';

        const isRowReceso = p.receso;
        const isZebra = (p.num % 2 === 0);

        html += `
          <tr class="${isRowReceso ? 'gestor-row-recreo ttp-receso-row' : (isZebra ? 'ttp-row-alt' : 'ttp-row-minimal')}">
            <td class="gestor-td-periodo col-periodo" style="${isRowReceso ? 'padding:4px 2px' : ''}">
              <div style="display:flex;flex-direction:column;align-items:center;gap:2px">
                <span class="gestor-periodo-badge ${isRowReceso ? 'recreo' : ''}">${isRowReceso ? '' : `${p.num}º`}</span>
              </div>
            </td>

            ${hayDiasTarde ? `
              <td class="gestor-td-horario col-horario" style="${isRowReceso ? 'background:#e9ecef;' : ''}">
                <div class="gestor-time-stack">
                  <span class="gestor-time-start">${horaTardeInicio}</span>
                  <span class="gestor-time-end">${horaTardeFin}</span>
                </div>
              </td>
              ${diasTarde.map(d => {
                const slot = calcularSlotDia(d, pIdx, 'tec', sedeKey);
                if (slot.isReceso) {
                  return `<td class="ttp-receso-cell day-group-end">RECREO</td>`;
                }
                return renderizarCeldaTec(d, slot.periodNum, pIdx, false, puedeEditar, mostrarDocentes, etaLabel, merges, dataTurno, sedeKey);
              }).join('')}
            ` : ''}

            ${hayDiasManana ? `
              <td class="gestor-td-horario col-horario col-horario-manana" style="${isRowReceso ? 'background:#e9ecef;' : ''}">
                <div class="gestor-time-stack">
                  <span class="gestor-time-start">${horaMananaInicio}</span>
                  <span class="gestor-time-end">${horaMananaFin}</span>
                </div>
              </td>
              ${diasManana.map(d => {
                const slot = calcularSlotDia(d, pIdx, 'tec', sedeKey);
                if (slot.isReceso) {
                  return `<td class="ttp-receso-cell day-group-end">RECREO</td>`;
                }
                return renderizarCeldaTec(d, slot.periodNum, pIdx, true, puedeEditar, mostrarDocentes, etaLabel, merges, dataTurno, sedeKey);
              }).join('')}
            ` : ''}

            ${hayDiasNoche ? `
              <td class="gestor-td-horario col-horario col-horario-noche" style="${isRowReceso ? 'background:#e9ecef;' : ''}">
                <div class="gestor-time-stack">
                  <span class="gestor-time-start">${horaNocheInicio}</span>
                  <span class="gestor-time-end">${horaNocheFin}</span>
                </div>
              </td>
              ${diasNoche.map(d => {
                const slot = calcularSlotDia(d, pIdx, 'tec', sedeKey);
                if (slot.isReceso) {
                  return `<td class="ttp-receso-cell day-group-end">RECREO</td>`;
                }
                return renderizarCeldaTec(d, slot.periodNum, pIdx, true, puedeEditar, mostrarDocentes, etaLabel, merges, dataTurno, sedeKey);
              }).join('')}
            ` : ''}
          </tr>
        `;
      });
    });

    html += `
          </tbody>
        </table>
      </div>
    `;

    return html;
  }
}


// Función auxiliar para renderizar cada celda del Área Técnica (TTP)
function renderizarCeldaTec(d, pObjOrNum, pIdx, esManana, puedeEditar, mostrarDocentes, etaLabel, merges, dataTurno, sedeKey = null) {
  const pNum = (typeof pObjOrNum === 'object' && pObjOrNum !== null) ? pObjOrNum.num : pObjOrNum;

  if (isCellCoveredByMerge(merges, 'tec', d, pNum, 0, dataTurno.periodos || [])) {
    return '';
  }

  const cellKey = `tec_${d}_${pNum}_0`;
  const mergeInfo = merges[cellKey] || { rowSpan: 1, colSpan: 1 };
  const mRowSpan = mergeInfo.rowSpan || 1;

  const rawSlot = (dataTurno.matriz && dataTurno.matriz[d] && dataTurno.matriz[d][pNum]);
  let slot = rawSlot;
  if (Array.isArray(rawSlot)) slot = rawSlot[0];

  // En TODOS los días activos (sea nuevo o existente), el valor por defecto oficial es ETA
  if (!slot || !slot.materia || slot.materia === '—' || slot.materia === '') {
    slot = { docente: 'Taller Técnico Modular', materia: 'ETA', curso: 'TTP' };
  }

  const esLibre = (slot.materia === 'Libre' || slot.materia === 'Blanco');

  if (esLibre) {
    if (puedeEditar) {
      return `
        <td class="day-group-end" ${mRowSpan > 1 ? `rowspan="${mRowSpan}"` : ''} onclick="abrirPopoverEdicionCelda(event, '${d}', ${pNum}, 0, 'tec', '${sedeKey}')" style="padding:0.5px;vertical-align:middle;text-align:center;cursor:pointer">
          <div class="gestor-cell-card gestor-cell-free" title="Celda libre. Clic para asignar" style="width:100%;min-height:36px;display:flex;align-items:center;justify-content:center">
            <span style="color:#94a3b8;font-weight:700;font-size:0.82rem">—</span>
          </div>
        </td>
      `;
    } else {
      return `
        <td class="day-group-end" ${mRowSpan > 1 ? `rowspan="${mRowSpan}"` : ''} style="padding:0.5px;vertical-align:middle;text-align:center;background:transparent">
          <div class="gestor-cell-card gestor-cell-free-normal" style="background:transparent;border:none;box-shadow:none;min-height:36px"></div>
        </td>
      `;
    }
  }

  const textoMateria = (slot.materia === 'ETA' || !slot.materia) ? etaLabel : slot.materia;

  return `
    <td class="day-group-end" ${mRowSpan > 1 ? `rowspan="${mRowSpan}"` : ''} ${puedeEditar ? `onclick="abrirPopoverEdicionCelda(event, '${d}', ${pNum}, 0, 'tec', '${sedeKey}')"` : ''} style="padding:0.5px;vertical-align:middle;text-align:center;${puedeEditar ? 'cursor:pointer' : ''}">
      <div style="display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;height:100%">
        <div class="ttp-eta-badge" style="width:100%;position:relative" ${puedeEditar ? `title="Clic para editar"` : ''}>
          <span>${escapeHTML(textoMateria)}</span>
          ${puedeEditar ? `
            <span class="gestor-edit-badge" title="Editar celda" style="top:-3px;right:-3px">
              <svg viewBox="0 0 24 24" width="9" height="9" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 1 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
            </span>
          ` : ''}
        </div>
      </div>
    </td>
  `;
}

function obtenerTextoETACustom() {
  const mostrarCompleto = lsGet('cea_tec_mostrar_eta_completo', false);
  const textoCompleto = lsGet('cea_tec_texto_eta', 'Educación Técnica Alternativa');
  const textoSigla = lsGet('cea_tec_sigla_eta', 'ETA');
  return mostrarCompleto ? textoCompleto : textoSigla;
}

function toggleMostrarNombreCompletoETA(checked) {
  const actual = lsGet('cea_tec_mostrar_eta_completo', false);
  const nuevo = (typeof checked === 'boolean') ? checked : !actual;
  lsSet('cea_tec_mostrar_eta_completo', nuevo);
  const textoEtaPersonalizado = lsGet('cea_tec_texto_eta', 'Educación Técnica Alternativa');
  const siglaEtaPersonalizada = lsGet('cea_tec_sigla_eta', 'ETA');
  actualizarBotonModoEdicion();
  cargarHorariosMatriz('tec');
  mostrarToastLive(nuevo ? `Denominación: "${textoEtaPersonalizado}"` : `Sigla: "${siglaEtaPersonalizada}"`);
}

async function abrirModalEditarTextoETA() {
  if (!tienePermisoEdicionHorarios()) {
    mostrarToastLive('Debe iniciar sesión como Director(a) para editar el texto técnico.');
    mostrarModalLoginDirector();
    return;
  }
  const textoActual = lsGet('cea_tec_texto_eta', 'Educación Técnica Alternativa');
  const siglaActual = lsGet('cea_tec_sigla_eta', 'ETA');

  const nuevoCompleto = await mostrarPromptModal(
    'Ingrese la denominación completa para el área técnica (sin siglas obligatorias, puede ser cualquier texto):',
    'Personalizar Nombre de Educación Técnica',
    textoActual,
    'Ej: Educación Técnica Alternativa'
  );
  if (nuevoCompleto === null || !nuevoCompleto.trim()) return;

  const nuevaSigla = await mostrarPromptModal(
    'Ingrese la sigla abreviada:',
    'Personalizar Sigla Técnica',
    siglaActual,
    'Ej: ETA / TEC'
  );
  if (nuevaSigla === null || !nuevaSigla.trim()) return;

  lsSet('cea_tec_texto_eta', nuevoCompleto.trim());
  lsSet('cea_tec_sigla_eta', nuevaSigla.trim());

  enviarGoogleSheet({
    action: 'guardar-contenido-vivo',
    key: 'tec_texto_eta',
    valor: nuevoCompleto.trim(),
    htmlValor: nuevoCompleto.trim()
  });
  enviarGoogleSheet({
    action: 'guardar-contenido-vivo',
    key: 'tec_sigla_eta',
    valor: nuevaSigla.trim(),
    htmlValor: nuevaSigla.trim()
  });

  actualizarBotonModoEdicion();
  cargarHorariosMatriz('tec');
  mostrarToastLive(`Texto técnico actualizado a: "${nuevoCompleto.trim()}" (Sigla: "${nuevaSigla.trim()}")`);
}

function toggleDiaHorarioTec(dia, activo) {
  let dias = getSedeLsData('cea_tec_dias_activos', ['Miércoles', 'Jueves', 'Viernes', 'Sábado']);
  if (activo && !dias.includes(dia)) {
    dias.push(dia);
  } else if (!activo && dias.includes(dia)) {
    dias = dias.filter(d => d !== dia);
  }
  if (!dias.length) dias = ['Miércoles'];
  dias = ordenarDiasCronologico(dias);
  setSedeLsData('cea_tec_dias_activos', dias);
  cargarHorariosMatriz('tec');
}

/* ─── MODAL RÁPIDO DE ASIGNACIÓN CELDA POR CELDA Y FUSIÓN (Director / Comisión) ─── */
function abrirModalEdicionCeldaHorario(dia, periodoNum, cursoIdx, turno = 'hum') {
  if (!tienePermisoEdicionHorarios()) {
    mostrarToastLive('Acceso exclusivo para Dirección o Comisión Pedagógica.');
    return;
  }
  if (typeof abrirPopoverEdicionCelda === 'function') {
    abrirPopoverEdicionCelda(window.event, dia, periodoNum, cursoIdx, turno);
    return;
  }
  const modal = document.getElementById('modalEditarCeldaHorario');
  if (!modal) return;

  document.getElementById('mch-dia').value = dia;
  document.getElementById('mch-periodo').value = periodoNum;
  document.getElementById('mch-curso-idx').value = cursoIdx;
  document.getElementById('mch-turno').value = turno;

  const modoDia = getModoDocenteDia(turno, dia);
  let cursoNom = 'Área Técnica';
  if (turno === 'hum') {
    if (modoDia === 'mono') {
      cursoNom = 'Grupo General / Docente Asignado';
    } else {
      const cursos = obtenerCursosParaDiaBTH(dia);
      cursoNom = cursos[cursoIdx] || `Paralelo ${cursoIdx + 1}`;
    }
  }

  document.getElementById('mch-titulo').textContent = `Editar Horario: ${dia} • Periodo ${periodoNum}`;
  document.getElementById('mch-subtitulo').textContent = `Nivel / Curso: ${cursoNom}`;

  const selectMat = document.getElementById('mch-materia-select');
  selectMat.innerHTML = `
    <option value="">-- Seleccionar Asignatura o Carrera --</option>
    <option value="Libre">Libre / Vacía (Dejar Sin Clase)</option>
    <optgroup label="Área Humanística (BTH)">
      <option value="Ciencias Naturales">Ciencias Naturales (Verde)</option>
      <option value="Matemática">Matemática (Azul)</option>
      <option value="Ciencias Sociales">Ciencias Sociales (Ámbar)</option>
      <option value="Comunicación y Lenguajes">Comunicación y Lenguajes (Púrpura)</option>
      <option value="Lenguaje">Lenguaje</option>
      <option value="Agropecuaria">Agropecuaria (BTH Agropecuaria)</option>
      <option value="Taller de Investigación BTH">Taller de Investigación BTH</option>
      <option value="Recreo">Recreo / Receso</option>
    </optgroup>
    <optgroup label="Área Técnica Tecnológica">
      <option value="Agropecuaria">Agropecuaria</option>
      <option value="Sistemas Informáticos">Sistemas Informáticos</option>
      <option value="Belleza Integral">Belleza Integral</option>
      <option value="Confección Textil">Confección Textil</option>
      <option value="Gastronomía">Gastronomía</option>
      <option value="Secretariado Ejecutivo">Secretariado Ejecutivo</option>
    </optgroup>
  `;

  // Obtener datos actuales de la celda
  const hMatriz = getSedeLsData('cea_horarios_matriz', HORARIOS_MATRIZ_DEFAULT);
  let curMat = '';
  let curDoc = '';
  let curSub = '';
  let celdaConfigurada = false;
  if (hMatriz && hMatriz[turno] && hMatriz[turno].matriz && hMatriz[turno].matriz[dia] && hMatriz[turno].matriz[dia][periodoNum]) {
    const slot = hMatriz[turno].matriz[dia][periodoNum];
    const cell = Array.isArray(slot) ? slot[cursoIdx] : slot;
    if (cell !== undefined && cell !== null) {
      curMat = cell.materia || '';
      curDoc = cell.docente || '';
      curSub = cell.sub || '';
      celdaConfigurada = true;
    }
  }
  if (!celdaConfigurada && turno === 'hum') {
    const canon = obtenerDatosCeldaBTH(dia, periodoNum, cursoIdx);
    if (canon) {
      curMat = canon.materia;
      curSub = canon.sub || '';
    }
  }

  selectMat.value = curMat;
  poblarSelectDocentesModal(curDoc);
  if (curDoc && curDoc !== '—') {
    const docInp = document.getElementById('mch-docente-inp');
    if (docInp) docInp.value = curDoc;
  } else {
    alCambiarMateriaEnModalCelda(curMat);
  }
  if (curSub) document.getElementById('mch-sub-inp').value = curSub;

  // Cargar estado de fusión (merge)
  const merges = getSedeLsData('cea_horarios_merges', {});
  const cellKey = `${turno}_${dia}_${periodoNum}_${cursoIdx}`;
  const currentMerge = merges[cellKey] || { rowSpan: 1, colSpan: 1 };
  const rSpan = currentMerge.rowSpan || 1;
  const cSpan = currentMerge.colSpan || 1;

  const rDisp = document.getElementById('mch-rowspan-disp');
  const rVal = document.getElementById('mch-rowspan-val');
  const cDisp = document.getElementById('mch-colspan-disp');
  const cVal = document.getElementById('mch-colspan-val');
  if (rDisp) rDisp.textContent = rSpan;
  if (rVal) rVal.value = rSpan;
  if (cDisp) cDisp.textContent = cSpan;
  if (cVal) cVal.value = cSpan;

  const unmergeWrap = document.getElementById('mch-unmerge-wrap');
  if (unmergeWrap) unmergeWrap.style.display = (rSpan > 1 || cSpan > 1) ? 'block' : 'none';

  modal.style.display = 'flex';
}

function obtenerMaxRowSpanParaPeriodo(periodoNum, periodosList) {
  const pNum = Number(periodoNum);
  const curIdx = periodosList.findIndex(p => Number(p.num) === pNum && !p.receso);
  if (curIdx === -1) return periodosList.filter(p => !p.receso).length;
  let span = 1;
  for (let i = curIdx + 1; i < periodosList.length; i++) {
    if (periodosList[i].receso) break;
    span++;
  }
  return Math.max(1, span);
}

function ajustarMergeRowSpan(delta) {
  const valInp = document.getElementById('mch-rowspan-val');
  const disp = document.getElementById('mch-rowspan-disp');
  if (!valInp || !disp) return;
  let cur = parseInt(valInp.value, 10) || 1;
  const periodoNum = parseInt(document.getElementById('mch-periodo').value, 10) || 1;
  const turno = document.getElementById('mch-turno').value || 'hum';
  const periodos = (turno === 'hum') ? HORARIOS_BTH_CANONICO.periodos : (lsGet('cea_horarios_matriz', {}).tec?.periodos || []);

  const maxRows = obtenerMaxRowSpanParaPeriodo(periodoNum, periodos);
  let next = Math.max(1, Math.min(maxRows, cur + delta));
  valInp.value = next;
  disp.textContent = next;

  const colSpanVal = parseInt(document.getElementById('mch-colspan-val').value, 10) || 1;
  const unmergeWrap = document.getElementById('mch-unmerge-wrap');
  if (unmergeWrap) unmergeWrap.style.display = (next > 1 || colSpanVal > 1) ? 'block' : 'none';
}

function ajustarMergeColSpan(delta) {
  const valInp = document.getElementById('mch-colspan-val');
  const disp = document.getElementById('mch-colspan-disp');
  if (!valInp || !disp) return;
  let cur = parseInt(valInp.value, 10) || 1;
  const cIdx = parseInt(document.getElementById('mch-curso-idx').value, 10) || 0;
  const turno = document.getElementById('mch-turno').value || 'hum';
  const dia = document.getElementById('mch-dia').value;
  const modoDia = getModoDocenteDia(turno, dia);

  let maxCols = 1;
  if (turno === 'hum' && modoDia === 'multi') {
    maxCols = Math.max(1, 4 - cIdx);
  }

  let next = Math.max(1, Math.min(maxCols, cur + delta));
  valInp.value = next;
  disp.textContent = next;

  const rowSpanVal = parseInt(document.getElementById('mch-rowspan-val').value, 10) || 1;
  const unmergeWrap = document.getElementById('mch-unmerge-wrap');
  if (unmergeWrap) unmergeWrap.style.display = (rowSpanVal > 1 || next > 1) ? 'block' : 'none';
}

function ejecutarUnionDireccionalModal(dir) {
  const dia = document.getElementById('mch-dia').value;
  const periodoNum = parseInt(document.getElementById('mch-periodo').value, 10);
  const cursoIdx = parseInt(document.getElementById('mch-curso-idx').value, 10);
  const turno = document.getElementById('mch-turno').value || 'hum';
  const sede = document.getElementById('mch-sede')?.value || document.getElementById('hqp-sede')?.value || getHorarioSedeActiveKey(turno);

  let materia = document.getElementById('mch-materia-select').value;
  let docente = document.getElementById('mch-docente-inp').value;
  const selDoc = document.getElementById('mch-docente-select');
  if (selDoc && selDoc.value && selDoc.value !== '__custom__') docente = selDoc.value;
  const sub = document.getElementById('mch-sub-inp').value;

  const hMatriz = getSedeLsData('cea_horarios_matriz', HORARIOS_MATRIZ_DEFAULT, sede, turno);
  if (!hMatriz[turno]) hMatriz[turno] = { matriz: {} };
  if (!hMatriz[turno].matriz) hMatriz[turno].matriz = {};
  if (!hMatriz[turno].matriz[dia]) hMatriz[turno].matriz[dia] = {};

  const periodos = (turno === 'hum') ? HORARIOS_BTH_CANONICO.periodos : ((hMatriz.tec && hMatriz.tec.periodos) || []);
  const nonReceso = periodos.filter(p => !p.receso);
  const curIdx = nonReceso.findIndex(p => p.num === periodoNum);
  const merges = getSedeLsData('cea_horarios_merges', {}, sede, turno);
  const cellKey = `${turno}_${dia}_${periodoNum}_${cursoIdx}`;
  const curMerge = merges[cellKey] || { rowSpan: 1, colSpan: 1 };

  if (!Array.isArray(hMatriz[turno].matriz[dia][periodoNum])) {
    hMatriz[turno].matriz[dia][periodoNum] = [];
    for (let i = 0; i < 4; i++) {
      hMatriz[turno].matriz[dia][periodoNum].push({ materia: 'Libre', docente: '—', sub: '' });
    }
  }

  if (dir === 'abajo') {
    if (curIdx < 0 || curIdx >= nonReceso.length - 1) {
      mostrarToastLive('No hay más periodos abajo para fusionar en esta jornada.');
      return;
    }
    const maxRowSpan = obtenerMaxRowSpanParaPeriodo(periodoNum, periodos);
    if ((curMerge.rowSpan || 1) >= maxRowSpan) {
      mostrarToastLive('Límite de bloque continuo alcanzado (antes de recreo o final).');
      return;
    }

    curMerge.rowSpan = (curMerge.rowSpan || 1) + 1;
    merges[cellKey] = curMerge;

    const nextPNum = nonReceso[curIdx + curMerge.rowSpan - 1]?.num;
    if (nextPNum) {
      delete merges[`${turno}_${dia}_${nextPNum}_${cursoIdx}`];
    }

    if (materia) {
      hMatriz[turno].matriz[dia][periodoNum][cursoIdx] = { materia, docente, sub };
    }

    setSedeLsData('cea_horarios_matriz', hMatriz, sede, turno);
    setSedeLsData('cea_horarios_merges', merges, sede, turno);
    cerrarModalEdicionCeldaHorario();
    cargarHorariosMatriz(turno);
    mostrarToastLive(`Unión vertical hacia abajo completada (${curMerge.rowSpan} periodos continuos).`);

    enviarGoogleSheet({
      action: 'guardar-horarios-matriz',
      sede: sede,
      horariosMatriz: hMatriz,
      horariosMerges: merges
    });
  } else if (dir === 'arriba') {
    if (curIdx <= 0) {
      mostrarToastLive('Ya te encuentras en el primer periodo de la jornada.');
      return;
    }
    const prevP = nonReceso[curIdx - 1];
    if (!prevP) return;
    const prevPNum = prevP.num;
    const masterKey = `${turno}_${dia}_${prevPNum}_${cursoIdx}`;
    const masterMerge = merges[masterKey] || { rowSpan: 1, colSpan: 1 };
    masterMerge.rowSpan = (masterMerge.rowSpan || 1) + 1;
    merges[masterKey] = masterMerge;

    if (!Array.isArray(hMatriz[turno].matriz[dia][prevPNum])) {
      hMatriz[turno].matriz[dia][prevPNum] = [];
      for (let i = 0; i < 4; i++) hMatriz[turno].matriz[dia][prevPNum].push({ materia: 'Libre', docente: '—', sub: '' });
    }
    if (materia) {
      hMatriz[turno].matriz[dia][prevPNum][cursoIdx] = { materia, docente, sub };
    }
    delete merges[cellKey];

    setSedeLsData('cea_horarios_matriz', hMatriz, sede, turno);
    setSedeLsData('cea_horarios_merges', merges, sede, turno);
    cerrarModalEdicionCeldaHorario();
    cargarHorariosMatriz(turno);
    mostrarToastLive(`Unión vertical hacia arriba completada con Periodo ${prevPNum}º.`);

    enviarGoogleSheet({
      action: 'guardar-horarios-matriz',
      sede: sede,
      horariosMatriz: hMatriz,
      horariosMerges: merges
    });
  } else if (dir === 'derecha') {
    const modoDia = getModoDocenteDia(turno, dia);
    const maxCols = (turno === 'hum' && modoDia === 'multi') ? 4 : 1;
    if (cursoIdx + (curMerge.colSpan || 1) >= maxCols) {
      mostrarToastLive('No hay más columnas o paralelos a la derecha para fusionar.');
      return;
    }
    curMerge.colSpan = (curMerge.colSpan || 1) + 1;
    merges[cellKey] = curMerge;

    const targetCol = cursoIdx + curMerge.colSpan - 1;
    delete merges[`${turno}_${dia}_${periodoNum}_${targetCol}`];

    if (materia) {
      hMatriz[turno].matriz[dia][periodoNum][cursoIdx] = { materia, docente, sub };
    }

    setSedeLsData('cea_horarios_matriz', hMatriz, sede, turno);
    setSedeLsData('cea_horarios_merges', merges, sede, turno);
    cerrarModalEdicionCeldaHorario();
    cargarHorariosMatriz(turno);
    mostrarToastLive(`Unión horizontal hacia la derecha completada (${curMerge.colSpan} columnas).`);

    enviarGoogleSheet({
      action: 'guardar-horarios-matriz',
      sede: sede,
      horariosMatriz: hMatriz,
      horariosMerges: merges
    });
  } else if (dir === 'izquierda') {
    if (cursoIdx <= 0) {
      mostrarToastLive('Ya te encuentras en la primera columna o paralelo.');
      return;
    }
    const targetCol = cursoIdx - 1;
    const masterKey = `${turno}_${dia}_${periodoNum}_${targetCol}`;
    const masterMerge = merges[masterKey] || { rowSpan: 1, colSpan: 1 };
    masterMerge.colSpan = (masterMerge.colSpan || 1) + 1;
    merges[masterKey] = masterMerge;

    if (materia) {
      hMatriz[turno].matriz[dia][periodoNum][targetCol] = { materia, docente, sub };
    }
    delete merges[cellKey];

    setSedeLsData('cea_horarios_matriz', hMatriz, sede, turno);
    setSedeLsData('cea_horarios_merges', merges, sede, turno);
    cerrarModalEdicionCeldaHorario();
    cargarHorariosMatriz(turno);
    mostrarToastLive(`Unión horizontal hacia la izquierda completada.`);

    enviarGoogleSheet({
      action: 'guardar-horarios-matriz',
      sede: sede,
      horariosMatriz: hMatriz,
      horariosMerges: merges
    });
  }
}

function quitarMergeCeldaActual() {
  const dia = document.getElementById('mch-dia').value;
  const periodoNum = parseInt(document.getElementById('mch-periodo').value, 10);
  const cursoIdx = parseInt(document.getElementById('mch-curso-idx').value, 10);
  const turno = document.getElementById('mch-turno').value || 'hum';
  const sede = document.getElementById('mch-sede')?.value || document.getElementById('hqp-sede')?.value || getHorarioSedeActiveKey(turno);

  const merges = getSedeLsData('cea_horarios_merges', {}, sede, turno);
  const cellKey = `${turno}_${dia}_${periodoNum}_${cursoIdx}`;
  delete merges[cellKey];

  for (const [k, m] of Object.entries(merges)) {
    if (k.startsWith(`${turno}_${dia}_`)) {
      const parts = k.split('_');
      const mPNum = parseInt(parts[2], 10);
      const mCIdx = parseInt(parts[3], 10);
      if (mPNum <= periodoNum && mPNum + (m.rowSpan || 1) > periodoNum &&
          mCIdx <= cursoIdx && mCIdx + (m.colSpan || 1) > cursoIdx) {
        delete merges[k];
      }
    }
  }

  setSedeLsData('cea_horarios_merges', merges, sede, turno);
  cerrarModalEdicionCeldaHorario();
  cargarHorariosMatriz(turno);
  mostrarToastLive('Celdas separadas correctamente. Volvieron al estado individual.');

  const hMatriz = getSedeLsData('cea_horarios_matriz', HORARIOS_MATRIZ_DEFAULT, sede, turno);

  enviarGoogleSheet({
    action: 'guardar-horarios-matriz',
    sede: sede,
    horariosMatriz: hMatriz,
    horariosMerges: merges
  });
}

function borrarContenidoCeldaHorario() {
  const dia = document.getElementById('mch-dia').value;
  const periodoNum = parseInt(document.getElementById('mch-periodo').value, 10);
  const cursoIdx = parseInt(document.getElementById('mch-curso-idx').value, 10);
  const turno = document.getElementById('mch-turno').value || 'hum';
  const sede = document.getElementById('mch-sede')?.value || document.getElementById('hqp-sede')?.value || getHorarioSedeActiveKey(turno);

  const hMatriz = getSedeLsData('cea_horarios_matriz', HORARIOS_MATRIZ_DEFAULT, sede, turno);
  if (!hMatriz[turno]) hMatriz[turno] = { matriz: {} };
  if (!hMatriz[turno].matriz) hMatriz[turno].matriz = {};
  if (!hMatriz[turno].matriz[dia]) hMatriz[turno].matriz[dia] = {};
  if (!Array.isArray(hMatriz[turno].matriz[dia][periodoNum])) {
    const base = [];
    for (let i = 0; i < 4; i++) {
      const defSlot = (turno === 'hum') ? obtenerDatosCeldaBTH(dia, periodoNum, i) : { materia: 'Libre', docente: '—', sub: '' };
      base.push(defSlot);
    }
    hMatriz[turno].matriz[dia][periodoNum] = base;
  }

  hMatriz[turno].matriz[dia][periodoNum][cursoIdx] = {
    materia: 'Libre',
    docente: '—',
    sub: ''
  };
  setSedeLsData('cea_horarios_matriz', hMatriz, sede, turno);

  const merges = getSedeLsData('cea_horarios_merges', {}, sede, turno);
  const cellKey = `${turno}_${dia}_${periodoNum}_${cursoIdx}`;
  delete merges[cellKey];
  for (const [k, m] of Object.entries(merges)) {
    if (k.startsWith(`${turno}_${dia}_`)) {
      const parts = k.split('_');
      const mPNum = parseInt(parts[2], 10);
      const mCIdx = parseInt(parts[3], 10);
      if (mPNum <= periodoNum && mPNum + (m.rowSpan || 1) > periodoNum &&
          mCIdx <= cursoIdx && mCIdx + (m.colSpan || 1) > cursoIdx) {
        delete merges[k];
      }
    }
  }
  setSedeLsData('cea_horarios_merges', merges, sede, turno);

  cerrarModalEdicionCeldaHorario();
  cargarHorariosMatriz(turno);
  mostrarToastLive('Contenido de celda eliminado (dejada libre).');

  enviarGoogleSheet({
    action: 'guardar-horarios-matriz',
    sede: sede,
    horariosMatriz: hMatriz,
    horariosMerges: merges
  });
}

function obtenerListaDocentesUnificada() {
  const defaults = [
    { nombre: 'Lic. Edmar Callisaya Tapia', area: 'Ciencias Naturales' },
    { nombre: 'Lic. Marcela Choque Mamani', area: 'Matemática' },
    { nombre: 'Lic. María Estela Laura Tenorio', area: 'Ciencias Sociales' },
    { nombre: 'Lic. Efraina Pajarito Ventura', area: 'Comunicación y Lenguajes' },
    { nombre: 'Lic. Gualberto Choque', area: 'Sistemas Informáticos' },
    { nombre: 'Lic. Ofelia Flores', area: 'Secretariado Ejecutivo' },
    { nombre: 'Lic. Maritza Ojeda Conde', area: 'Belleza Integral / Textil' },
    { nombre: 'Lic. Lourdes Chambi', area: 'Gastronomía' },
    { nombre: 'Lic. Macario Ticonipa', area: 'Agropecuaria' }
  ];

  const mapGuardado = lsGet('cea_docentes', {});
  const unicos = new Map();

  defaults.forEach(d => unicos.set(d.nombre, d));

  Object.entries(mapGuardado).forEach(([k, v]) => {
    const nom = (typeof v === 'string') ? v : (v && v.nombre ? v.nombre : '');
    if (nom && !unicos.has(nom)) {
      unicos.set(nom, { nombre: nom, area: 'General' });
    }
  });

  if (typeof appStateGestor !== 'undefined' && Array.isArray(appStateGestor.docentes)) {
    appStateGestor.docentes.forEach(d => {
      if (d.prof && !unicos.has(d.prof)) {
        unicos.set(d.prof, { nombre: d.prof, area: d.area || 'General' });
      }
    });
  }

  return Array.from(unicos.values());
}

function poblarSelectDocentesModal(docenteSeleccionado = '') {
  const sel = document.getElementById('mch-docente-select');
  const inpHidden = document.getElementById('mch-docente-inp');
  const customWrap = document.getElementById('mch-docente-custom-wrap');
  const customInp = document.getElementById('mch-docente-custom-inp');
  if (!sel) return;

  const docentes = obtenerListaDocentesUnificada();
  let html = `<option value="">-- Seleccionar Docente de la Lista --</option>`;

  const humDocs = docentes.filter(d => ['Ciencias Naturales','Matemática','Ciencias Sociales','Comunicación y Lenguajes','Lenguaje'].includes(d.area));
  const tecDocs = docentes.filter(d => !['Ciencias Naturales','Matemática','Ciencias Sociales','Comunicación y Lenguajes','Lenguaje'].includes(d.area));

  html += `<optgroup label="Docentes Humanística (BTH)">`;
  humDocs.forEach(d => {
    html += `<option value="${escapeHTML(d.nombre)}">${escapeHTML(d.nombre)} (${escapeHTML(d.area)})</option>`;
  });
  html += `</optgroup>`;

  html += `<optgroup label="Docentes Especialidades Técnicas / General">`;
  tecDocs.forEach(d => {
    html += `<option value="${escapeHTML(d.nombre)}">${escapeHTML(d.nombre)} (${escapeHTML(d.area)})</option>`;
  });
  html += `</optgroup>`;

  html += `<option value="__custom__">+ Escribir otro docente manualmente...</option>`;

  sel.innerHTML = html;

  if (docenteSeleccionado && docenteSeleccionado !== '—') {
    const existe = docentes.some(d => d.nombre === docenteSeleccionado);
    if (existe) {
      sel.value = docenteSeleccionado;
      if (customWrap) customWrap.style.display = 'none';
      if (inpHidden) inpHidden.value = docenteSeleccionado;
    } else {
      sel.value = '__custom__';
      if (customWrap) customWrap.style.display = 'block';
      if (customInp) customInp.value = docenteSeleccionado;
      if (inpHidden) inpHidden.value = docenteSeleccionado;
    }
  } else {
    sel.value = '';
    if (customWrap) customWrap.style.display = 'none';
    if (inpHidden) inpHidden.value = '';
  }
}

function alCambiarDocenteEnModalCelda(val) {
  const inpHidden = document.getElementById('mch-docente-inp');
  const customWrap = document.getElementById('mch-docente-custom-wrap');
  const customInp = document.getElementById('mch-docente-custom-inp');
  if (val === '__custom__') {
    if (customWrap) customWrap.style.display = 'block';
    if (customInp) {
      customInp.focus();
      if (inpHidden) inpHidden.value = customInp.value.trim();
    }
  } else {
    if (customWrap) customWrap.style.display = 'none';
    if (inpHidden) inpHidden.value = val;
  }
}

function buscarDocentePorMateria(materia) {
  if (!materia || materia === 'Libre' || materia === 'Recreo' || materia === 'Blanco') return '';
  const matNorm = materia.toLowerCase().trim();

  // 1. Buscar en appStateGestor.docentes (por área o por lista de módulos)
  if (typeof appStateGestor !== 'undefined' && Array.isArray(appStateGestor.docentes)) {
    for (const d of appStateGestor.docentes) {
      const prof = d.prof || d.nombre || '';
      const area = (d.area || '').toLowerCase().trim();
      if (area && (matNorm === area || matNorm.includes(area) || area.includes(matNorm))) {
        return prof;
      }
      if (Array.isArray(d.mods)) {
        for (const m of d.mods) {
          const mNorm = String(m).toLowerCase().trim();
          if (mNorm && (matNorm.includes(mNorm) || mNorm.includes(matNorm))) {
            return prof;
          }
        }
      }
    }
  }

  // 2. Docentes Canónicos Institucionales Humanística / BTH
  if (matNorm.includes('natural') || matNorm.includes('biolog') || matNorm.includes('químic') || matNorm.includes('físic') || matNorm.includes('quimica') || matNorm.includes('fisica') || matNorm.includes('riesgo')) {
    return 'Lic. Edmar Callisaya Tapia';
  }
  if (matNorm.includes('matem') || matNorm.includes('estadístic') || matNorm.includes('estadistica') || matNorm.includes('calcul') || matNorm.includes('cálcul')) {
    return 'Lic. Marcela Choque Mamani';
  }
  if (matNorm.includes('social') || matNorm.includes('histor') || matNorm.includes('cívic') || matNorm.includes('civica') || matNorm.includes('creatividad') || matNorm.includes('empresarial') || matNorm.includes('seguridad')) {
    return 'Lic. María Estela Laura Tenorio';
  }
  if (matNorm.includes('lengua') || matNorm.includes('comunic') || matNorm.includes('literat') || matNorm.includes('originari')) {
    return 'Lic. Efraina Pajarito Ventura';
  }

  // 3. Docentes Áreas Técnicas
  if (matNorm.includes('agropec')) return 'Lic. Macario Ticonipa';
  if (matNorm.includes('sistema') || matNorm.includes('informát') || matNorm.includes('informat')) return 'Lic. Gualberto Choque';
  if (matNorm.includes('secretariad')) return 'Lic. Ofelia Flores';
  if (matNorm.includes('belleza')) return 'Lic. Maritza Ojeda Conde';
  if (matNorm.includes('gastronom')) return 'Lic. Lourdes Chambi';
  if (matNorm.includes('textil') || matNorm.includes('confecc')) return 'Lic. Maritza Ojeda Conde';

  // 4. MAPA_MATERIAS_DOCENTES fallback
  if (typeof MAPA_MATERIAS_DOCENTES !== 'undefined' && MAPA_MATERIAS_DOCENTES[materia] && MAPA_MATERIAS_DOCENTES[materia].docente && MAPA_MATERIAS_DOCENTES[materia].docente !== '—') {
    return MAPA_MATERIAS_DOCENTES[materia].docente;
  }
  return '';
}

function alCambiarMateriaEnModalCelda(materia) {
  const selDoc = document.getElementById('mch-docente-select');
  const docInp = document.getElementById('mch-docente-inp');
  const customWrap = document.getElementById('mch-docente-custom-wrap');

  if (!materia || materia === 'Libre' || materia === 'Recreo' || materia === 'Blanco') {
    if (selDoc) selDoc.value = '';
    if (docInp) docInp.value = (materia === 'Libre' ? '—' : '');
    if (customWrap) customWrap.style.display = 'none';
    return;
  }

  const docAsignar = buscarDocentePorMateria(materia);
  if (docAsignar) {
    if (docInp) docInp.value = docAsignar;
    if (selDoc) {
      let matchIdx = -1;
      const cleanNom = docAsignar.toLowerCase().replace(/^(lic\.|prof\.)\s*/, '').trim();
      for (let i = 0; i < selDoc.options.length; i++) {
        const val = selDoc.options[i].value;
        const valClean = val.toLowerCase().replace(/^(lic\.|prof\.)\s*/, '').trim();
        if (val === docAsignar || (cleanNom && valClean === cleanNom)) {
          matchIdx = i;
          break;
        }
      }
      if (matchIdx >= 0) {
        selDoc.selectedIndex = matchIdx;
        if (docInp) docInp.value = selDoc.options[matchIdx].value;
      } else {
        const opt = document.createElement('option');
        opt.value = docAsignar;
        opt.textContent = docAsignar;
        opt.selected = true;
        selDoc.insertBefore(opt, selDoc.lastElementChild);
        if (docInp) docInp.value = docAsignar;
      }
      if (customWrap) customWrap.style.display = 'none';
    }
  }
}

function cerrarModalEdicionCeldaHorario() {
  const modal = document.getElementById('modalEditarCeldaHorario');
  if (modal) modal.style.display = 'none';
}

async function guardarEdicionCeldaHorario(e) {
  if (e) e.preventDefault();
  const dia = document.getElementById('mch-dia').value;
  const periodoNum = parseInt(document.getElementById('mch-periodo').value, 10);
  const cursoIdx = parseInt(document.getElementById('mch-curso-idx').value, 10);
  const turno = document.getElementById('mch-turno').value || 'hum';
  const materia = document.getElementById('mch-materia-select').value;
  
  let docente = document.getElementById('mch-docente-inp').value;
  const selDoc = document.getElementById('mch-docente-select');
  if (selDoc && selDoc.value === '__custom__') {
    const customInp = document.getElementById('mch-docente-custom-inp');
    if (customInp && customInp.value.trim()) {
      docente = customInp.value.trim();
    }
  } else if (selDoc && selDoc.value) {
    docente = selDoc.value;
  }
  const sub = document.getElementById('mch-sub-inp').value;

  const rowSpan = parseInt(document.getElementById('mch-rowspan-val').value, 10) || 1;
  const colSpan = parseInt(document.getElementById('mch-colspan-val').value, 10) || 1;

  const sede = document.getElementById('mch-sede')?.value || document.getElementById('hqp-sede')?.value || getHorarioSedeActiveKey(turno);
  const hMatriz = getSedeLsData('cea_horarios_matriz', HORARIOS_MATRIZ_DEFAULT, sede, turno);
  if (!hMatriz[turno]) hMatriz[turno] = { matriz: {} };
  if (!hMatriz[turno].matriz) hMatriz[turno].matriz = {};
  if (!hMatriz[turno].matriz[dia]) hMatriz[turno].matriz[dia] = {};

  if (!Array.isArray(hMatriz[turno].matriz[dia][periodoNum])) {
    const base = [];
    const numCursos = (turno === 'hum') ? (obtenerCursosParaDia(dia).length || 4) : 1;
    for (let i = 0; i < numCursos; i++) {
      base.push({ materia: 'Libre', docente: '—', sub: '', curso: 'Curso ' + (i + 1) });
    }
    hMatriz[turno].matriz[dia][periodoNum] = base;
  }

  while (hMatriz[turno].matriz[dia][periodoNum].length <= cursoIdx) {
    const nextIdx = hMatriz[turno].matriz[dia][periodoNum].length;
    hMatriz[turno].matriz[dia][periodoNum].push({
      materia: 'Libre', docente: '—', sub: '', curso: 'Curso ' + (nextIdx + 1)
    });
  }

  const cursosLista = (turno === 'hum') ? obtenerCursosParaDia(dia) : [];
  const nombreCurso = (cursosLista && cursosLista[cursoIdx]) ? cursosLista[cursoIdx] : ('Curso ' + (cursoIdx + 1));

  hMatriz[turno].matriz[dia][periodoNum][cursoIdx] = {
    materia: materia,
    docente: docente,
    sub: sub,
    curso: nombreCurso
  };

  setSedeLsData('cea_horarios_matriz', hMatriz, sede, turno);

  // Guardar configuración de fusión (merges)
  const merges = getSedeLsData('cea_horarios_merges', {}, sede, turno);
  const cellKey = `${turno}_${dia}_${periodoNum}_${cursoIdx}`;
  if (rowSpan > 1 || colSpan > 1) {
    merges[cellKey] = { rowSpan, colSpan };
  } else {
    delete merges[cellKey];
  }
  setSedeLsData('cea_horarios_merges', merges, sede, turno);

  cerrarModalEdicionCeldaHorario();
  cargarHorariosMatriz(turno);
  const containerAdmin = document.getElementById('editor-horarios-matriz-container');
  if (containerAdmin) cargarEditorHorariosMatriz(turno);
  const containerDoc = document.getElementById('docente-editor-horarios-slot');
  if (containerDoc) cargarEditorHorariosMatriz('hum', 'docente-editor-horarios-slot');
  mostrarToastLive((rowSpan > 1 || colSpan > 1) ? 'Asignación y fusión de celdas guardadas con éxito.' : 'Asignación guardada con éxito.');

  // Sincronizar en segundo plano con Google Sheets
  await enviarGoogleSheet({
    action: 'guardar-horarios-matriz',
    sede: sede,
    horariosMatriz: hMatriz,
    horariosMerges: merges
  });
}

