/* ─── DÍAS DE CLASES Y HORARIOS DE ATENCIÓN AUTOMÁTICOS DESDE SEDE CENTRAL ─── */
function formatearRangoDiasTexto(dias) {
  if (!Array.isArray(dias) || dias.length === 0) return 'Lunes a Viernes';
  const orden = ['Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes', 'Sábado', 'Domingo'];
  const diasOrdenados = orden.filter(d => dias.includes(d));
  if (diasOrdenados.length === 0) return 'Lunes a Viernes';
  if (diasOrdenados.length === 1) return diasOrdenados[0];

  const indices = diasOrdenados.map(d => orden.indexOf(d));
  let esConsecutivo = true;
  for (let i = 0; i < indices.length - 1; i++) {
    if (indices[i + 1] !== indices[i] + 1) {
      esConsecutivo = false;
      break;
    }
  }

  if (esConsecutivo && diasOrdenados.length >= 2) {
    return `${diasOrdenados[0]} a ${diasOrdenados[diasOrdenados.length - 1]}`;
  }

  if (diasOrdenados.length === 2) {
    return `${diasOrdenados[0]} y ${diasOrdenados[1]}`;
  }

  return diasOrdenados.slice(0, -1).join(', ') + ' y ' + diasOrdenados[diasOrdenados.length - 1];
}

function calcularRangoHorasCentral(area = 'hum') {
  const sedeKey = 'central';
  const franjasActivas = (typeof getFranjasActivas === 'function') ? getFranjasActivas(area, sedeKey) : [(area === 'tec') ? 'tarde' : 'manana'];

  let minInicio = '23:59';
  let maxFin = '00:00';

  franjasActivas.forEach(fKey => {
    const periodos = (typeof getPeriodosSede === 'function') ? getPeriodosSede(fKey, sedeKey, area) : [];
    if (Array.isArray(periodos)) {
      periodos.forEach(p => {
        if (p.inicio && p.inicio < minInicio) minInicio = p.inicio;
        if (p.fin && p.fin > maxFin) maxFin = p.fin;
      });
    }
  });

  if (minInicio === '23:59') minInicio = (area === 'tec') ? '14:00' : '08:00';
  if (maxFin === '00:00') maxFin = (area === 'tec') ? '18:20' : '12:20';

  return { inicio: minInicio, fin: maxFin };
}

function irAEditarHorarioEnPaginaWeb() {
  const secHorarios = document.getElementById('horarios');
  if (secHorarios) {
    window.location.hash = '#horarios';
    secHorarios.scrollIntoView({ behavior: 'smooth' });
    window.modoEdicionHorarioActivo = true;
    if (typeof actualizarBotonModoEdicion === 'function') actualizarBotonModoEdicion();
    if (typeof cargarHorariosMatriz === 'function') cargarHorariosMatriz(turnoHorarioActual);
    mostrarToastLive('Modo edición activado en el horario del sitio web. Haz clic en cualquier celda para editar materias o docentes.');
  }
}

function sincronizarPublicoHorariosYAtencionDesdeCentral() {
  const sedeCentralKey = 'central';

  // 1. Humanística (Sede Central)
  const rawDiasHum = getSedeLsData('cea_bth_dias_activos', ['Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes'], sedeCentralKey, 'hum');
  const diasHum = ordenarDiasCronologico(rawDiasHum);
  const textoDiasHum = formatearRangoDiasTexto(diasHum);
  const horasHum = calcularRangoHorasCentral('hum');

  const textoClasesHum = `${textoDiasHum} (${horasHum.inicio} – ${horasHum.fin})`;
  const textoAtencionHoraHum = `${horasHum.inicio} – 12:00`;

  // 2. Técnica (Sede Central)
  const rawDiasTec = getSedeLsData('cea_tec_dias_activos', ['Miércoles', 'Jueves', 'Viernes', 'Sábado'], sedeCentralKey, 'tec');
  const diasTec = ordenarDiasCronologico(rawDiasTec);
  const textoDiasTec = formatearRangoDiasTexto(diasTec);
  const horasTec = calcularRangoHorasCentral('tec');

  const textoClasesTec = `${textoDiasTec} (${horasTec.inicio} – ${horasTec.fin})`;
  const textoAtencionHoraTec = `${horasTec.inicio} – 18:00`;

  // Manual overrides si existen guardados explícitamente por el director
  const customDias = lsGet('cea_dias_clase', null);
  const customAtencion = lsGet('cea_horarios_atencion', null);

  const finalClasesHum = (customDias && customDias.hum) ? customDias.hum : textoClasesHum;
  const finalClasesTec = (customDias && customDias.tec) ? customDias.tec : textoClasesTec;

  const finalAtencionDiaHum = (customAtencion && customAtencion.diaHum) ? customAtencion.diaHum : textoDiasHum;
  const finalAtencionHoraHum = (customAtencion && customAtencion.horaHum) ? customAtencion.horaHum : textoAtencionHoraHum;

  const finalAtencionDiaTec = (customAtencion && customAtencion.diaTec) ? customAtencion.diaTec : textoDiasTec;
  const finalAtencionHoraTec = (customAtencion && customAtencion.horaTec) ? customAtencion.horaTec : textoAtencionHoraTec;

  // Actualización DOM
  const elClasesHum = document.getElementById('display-dias-clase-hum');
  const elClasesTec = document.getElementById('display-dias-clase-tec');
  const elAtencionHoraHum = document.getElementById('td-atencion-hora-hum');
  const elAtencionHoraTec = document.getElementById('td-atencion-hora-tec');
  const elAtencionDiaHum = document.getElementById('td-atencion-dia-hum');
  const elAtencionDiaTec = document.getElementById('td-atencion-dia-tec');

  if (elClasesHum) elClasesHum.textContent = finalClasesHum;
  if (elClasesTec) elClasesTec.textContent = finalClasesTec;
  if (elAtencionHoraHum) elAtencionHoraHum.textContent = finalAtencionHoraHum;
  if (elAtencionHoraTec) elAtencionHoraTec.textContent = finalAtencionHoraTec;
  if (elAtencionDiaHum) elAtencionDiaHum.textContent = finalAtencionDiaHum;
  if (elAtencionDiaTec) elAtencionDiaTec.textContent = finalAtencionDiaTec;
}


