let formatoHorarioActualModal = '12';

function cambiarFormatoHorarioModal(fmt, forzar = false) {
  if (!forzar && formatoHorarioActualModal === fmt) return;
  const prevFmt = formatoHorarioActualModal;
  formatoHorarioActualModal = fmt;

  // Botones de toggle activo/inactivo
  const btn12 = document.getElementById('btn-formato-hora-12');
  const btn24 = document.getElementById('btn-formato-hora-24');
  if (btn12 && btn24) {
    if (fmt === '24') {
      btn24.style.background = '#2563eb';
      btn24.style.color = '#ffffff';
      btn12.style.background = 'transparent';
      btn12.style.color = 'var(--text-sec)';
    } else {
      btn12.style.background = '#2563eb';
      btn12.style.color = '#ffffff';
      btn24.style.background = 'transparent';
      btn24.style.color = 'var(--text-sec)';
    }
  }

  // Ocultar o mostrar selectores AM/PM
  const ampmSelects = [
    'modal-sel-clase-ini-ampm', 'modal-sel-clase-fin-ampm',
    'modal-sel-aten-ini-ampm', 'modal-sel-aten-fin-ampm'
  ];
  ampmSelects.forEach(id => {
    const el = document.getElementById(id);
    if (el) el.style.display = (fmt === '24') ? 'none' : 'block';
  });

  // Re-poblar horas y convertir valores existentes
  const horas12 = ['01','02','03','04','05','06','07','08','09','10','11','12'];
  const horas24 = Array.from({length: 24}, (_, i) => String(i).padStart(2, '0'));

  const selectPairs = [
    { hId: 'modal-sel-clase-ini-h', ampmId: 'modal-sel-clase-ini-ampm' },
    { hId: 'modal-sel-clase-fin-h', ampmId: 'modal-sel-clase-fin-ampm' },
    { hId: 'modal-sel-aten-ini-h', ampmId: 'modal-sel-aten-ini-ampm' },
    { hId: 'modal-sel-aten-fin-h', ampmId: 'modal-sel-aten-fin-ampm' }
  ];

  selectPairs.forEach(p => {
    const elH = document.getElementById(p.hId);
    const elAmpm = document.getElementById(p.ampmId);
    if (!elH) return;

    let hVal = parseInt(elH.value, 10);
    if (isNaN(hVal)) hVal = 8;
    let ampmVal = elAmpm ? elAmpm.value : 'AM';

    let nuevoH = hVal;
    if (!forzar) {
      if (prevFmt === '12' && fmt === '24') {
        // De 12h a 24h
        if (ampmVal === 'PM' && hVal < 12) nuevoH = hVal + 12;
        else if (ampmVal === 'AM' && hVal === 12) nuevoH = 0;
      } else if (prevFmt === '24' && fmt === '12') {
        // De 24h a 12h
        if (hVal === 0) { nuevoH = 12; if (elAmpm) elAmpm.value = 'AM'; }
        else if (hVal < 12) { nuevoH = hVal; if (elAmpm) elAmpm.value = 'AM'; }
        else if (hVal === 12) { nuevoH = 12; if (elAmpm) elAmpm.value = 'PM'; }
        else { nuevoH = hVal - 12; if (elAmpm) elAmpm.value = 'PM'; }
      }
    }

    const opciones = (fmt === '24') ? horas24 : horas12;
    elH.innerHTML = opciones.map(h => `<option value="${h}">${h}</option>`).join('');
    elH.value = String(nuevoH).padStart(2, '0');
  });
}

function poblarSelectsHorarioModal() {
  const minutos = ['00','05','10','15','20','25','30','35','40','45','50','55'];
  const selectIdsM = [
    'modal-sel-clase-ini-m', 'modal-sel-clase-fin-m',
    'modal-sel-aten-ini-m', 'modal-sel-aten-fin-m'
  ];
  selectIdsM.forEach(id => {
    const el = document.getElementById(id);
    if (el && el.options.length === 0) {
      el.innerHTML = minutos.map(m => `<option value="${m}">${m}</option>`).join('');
    }
  });
}

function parseHoraMinutoAmpm(str, defaultH, defaultM, defaultAmpm) {
  if (!str) return { h: defaultH, m: defaultM, ampm: defaultAmpm };
  const cleaned = str.trim().toUpperCase();
  const match = cleaned.match(/(\d{1,2}):(\d{2})(?:\s*(AM|PM))?/i);
  if (!match) return { h: defaultH, m: defaultM, ampm: defaultAmpm };
  
  let hNum = parseInt(match[1], 10);
  let mStr = match[2];
  let ampm = match[3];

  if (!ampm) {
    if (hNum >= 12) {
      ampm = 'PM';
      if (hNum > 12) hNum -= 12;
    } else {
      ampm = 'AM';
      if (hNum === 0) hNum = 12;
    }
  } else {
    ampm = ampm.toUpperCase();
  }
  const hStr = String(hNum).padStart(2, '0');
  return { h: hStr, m: mStr, ampm: ampm };
}

function parseHora24h(str, defaultH, defaultM) {
  if (!str) return { h: defaultH, m: defaultM };
  const cleaned = str.trim().toUpperCase();
  const match = cleaned.match(/(\d{1,2}):(\d{2})(?:\s*(AM|PM))?/i);
  if (!match) return { h: defaultH, m: defaultM };
  let hNum = parseInt(match[1], 10);
  let mStr = match[2];
  let ampm = match[3];
  if (ampm) {
    if (ampm.toUpperCase() === 'PM' && hNum < 12) hNum += 12;
    if (ampm.toUpperCase() === 'AM' && hNum === 12) hNum = 0;
  }
  return { h: String(hNum).padStart(2, '0'), m: mStr };
}

function parsearDiasString(str) {
  const norm = (str || '').toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
  if (norm.includes('lunes a viernes')) {
    return { lun: true, mar: true, mie: true, jue: true, vie: true, sab: false };
  }
  if (norm.includes('lunes a sabado')) {
    return { lun: true, mar: true, mie: true, jue: true, vie: true, sab: true };
  }
  return {
    lun: norm.includes('lun'),
    mar: norm.includes('mar'),
    mie: norm.includes('mie'),
    jue: norm.includes('jue'),
    vie: norm.includes('vie'),
    sab: norm.includes('sab')
  };
}

function formatearDiasDesdeChecks(pfx) {
  const lun = document.getElementById(`modal-chk-${pfx}-lun`)?.checked;
  const mar = document.getElementById(`modal-chk-${pfx}-mar`)?.checked;
  const mie = document.getElementById(`modal-chk-${pfx}-mie`)?.checked;
  const jue = document.getElementById(`modal-chk-${pfx}-jue`)?.checked;
  const vie = document.getElementById(`modal-chk-${pfx}-vie`)?.checked;
  const sab = document.getElementById(`modal-chk-${pfx}-sab`)?.checked;

  if (lun && mar && mie && jue && vie && sab) return 'Lunes a Sábado';
  if (lun && mar && mie && jue && vie && !sab) return 'Lunes a Viernes';

  const seleccionados = [];
  if (lun) seleccionados.push('Lunes');
  if (mar) seleccionados.push('Martes');
  if (mie) seleccionados.push('Miércoles');
  if (jue) seleccionados.push('Jueves');
  if (vie) seleccionados.push('Viernes');
  if (sab) seleccionados.push('Sábado');

  return seleccionados.length > 0 ? seleccionados.join(', ') : 'Lunes a Viernes';
}

