function abrirEditorHorarioArea(area = 'hum') {
  poblarSelectsHorarioModal();
  const tgt = (area === 'tec') ? 'tec' : 'hum';
  const inputTgt = document.getElementById('modal-horario-area-target');
  if (inputTgt) inputTgt.value = tgt;

  const titEl = document.getElementById('modal-horario-area-titulo');
  const subEl = document.getElementById('modal-horario-area-subtitulo');
  if (titEl) titEl.textContent = tgt === 'hum' ? 'Configurar Horario y Días — Área Humanística' : 'Configurar Horario y Días — Área Técnica';
  if (subEl) subEl.textContent = tgt === 'hum' ? 'GESTIÓN 2026 • HUMANÍSTICA (TURNO MAÑANA)' : 'GESTIÓN 2026 • CARRERAS TÉCNICAS (TURNO TARDE)';

  // Cargar títulos editables de la sección
  const titulosObj = obtenerTitulosHorarios();
  const inpHoraNom = document.getElementById('modal-inp-horario-nombre');
  const inpHoraBadge = document.getElementById('modal-inp-horario-badge');
  const inpHoraTurno = document.getElementById('modal-inp-horario-turno');

  if (inpHoraNom) inpHoraNom.value = tgt === 'hum' ? (titulosObj.humNombre || 'Área Humanística') : (titulosObj.tecNombre || 'Área Técnica');
  if (inpHoraBadge) inpHoraBadge.value = tgt === 'hum' ? (titulosObj.humBadge || 'GESTIÓN 2026 • HUMANÍSTICA') : (titulosObj.tecBadge || 'GESTIÓN 2026 • CARRERAS TÉCNICAS');
  if (inpHoraTurno) inpHoraTurno.value = tgt === 'hum' ? (titulosObj.humTurno || 'Turno Mañana') : (titulosObj.tecTurno || 'Turno Tarde');

  // 1. Clases
  const diasClasesObj = obtenerDiasClases();
  const claseStr = diasClasesObj[tgt] || (tgt === 'hum' ? 'Lunes a Viernes (08:00 – 12:20)' : 'Lunes a Viernes (14:00 – 18:20)');
  
  const mClase = claseStr.match(/^(.*?)\((.*?)[–\-](.*?)\)/);
  let diasClaseTexto = mClase ? mClase[1].trim() : claseStr;
  let horaClaseIniStr = mClase ? mClase[2].trim() : (tgt === 'hum' ? '08:00 AM' : '02:00 PM');
  let horaClaseFinStr = mClase ? mClase[3].trim() : (tgt === 'hum' ? '12:20 PM' : '06:20 PM');

  // 2. Atención
  const atenObj = obtenerHorariosAtencion();
  const diaAtenStr = (tgt === 'hum' ? atenObj.diaHum : atenObj.diaTec) || 'Lunes a Viernes';
  const horaAtenStr = (tgt === 'hum' ? atenObj.horaHum : atenObj.horaTec) || (tgt === 'hum' ? '08:00 – 12:00' : '14:00 – 18:00');
  const mAten = horaAtenStr.split(/[–\-]/);
  let horaAtenIniStr = (mAten[0] || '').trim();
  let horaAtenFinStr = (mAten[1] || '').trim();

  // Detectar formato: si contiene AM o PM, es 12h. Si no contiene AM/PM, es 24h.
  const tieneAmpm = /(AM|PM)/i.test(claseStr) || /(AM|PM)/i.test(horaAtenStr);
  const formatoDetectado = tieneAmpm ? '12' : '24';
  cambiarFormatoHorarioModal(formatoDetectado, true);

  // Parsear y asignar días
  const diasClaseParsed = parsearDiasString(diasClaseTexto);
  ['lun', 'mar', 'mie', 'jue', 'vie', 'sab'].forEach(d => {
    const chk = document.getElementById(`modal-chk-clase-${d}`);
    if (chk) chk.checked = !!diasClaseParsed[d];
  });

  const diasAtenParsed = parsearDiasString(diaAtenStr);
  ['lun', 'mar', 'mie', 'jue', 'vie', 'sab'].forEach(d => {
    const chk = document.getElementById(`modal-chk-aten-${d}`);
    if (chk) chk.checked = !!diasAtenParsed[d];
  });

  if (formatoDetectado === '24') {
    const defCIni = tgt === 'hum' ? { h: '08', m: '00' } : { h: '14', m: '00' };
    const defCFin = tgt === 'hum' ? { h: '12', m: '20' } : { h: '18', m: '20' };
    const pCIni = parseHora24h(horaClaseIniStr, defCIni.h, defCIni.m);
    const pCFin = parseHora24h(horaClaseFinStr, defCFin.h, defCFin.m);

    if (document.getElementById('modal-sel-clase-ini-h')) document.getElementById('modal-sel-clase-ini-h').value = pCIni.h;
    if (document.getElementById('modal-sel-clase-ini-m')) document.getElementById('modal-sel-clase-ini-m').value = pCIni.m;
    if (document.getElementById('modal-sel-clase-fin-h')) document.getElementById('modal-sel-clase-fin-h').value = pCFin.h;
    if (document.getElementById('modal-sel-clase-fin-m')) document.getElementById('modal-sel-clase-fin-m').value = pCFin.m;

    const defAIni = tgt === 'hum' ? { h: '08', m: '00' } : { h: '14', m: '00' };
    const defAFin = tgt === 'hum' ? { h: '12', m: '00' } : { h: '18', m: '00' };
    const pAIni = parseHora24h(horaAtenIniStr, defAIni.h, defAIni.m);
    const pAFin = parseHora24h(horaAtenFinStr, defAFin.h, defAFin.m);

    if (document.getElementById('modal-sel-aten-ini-h')) document.getElementById('modal-sel-aten-ini-h').value = pAIni.h;
    if (document.getElementById('modal-sel-aten-ini-m')) document.getElementById('modal-sel-aten-ini-m').value = pAIni.m;
    if (document.getElementById('modal-sel-aten-fin-h')) document.getElementById('modal-sel-aten-fin-h').value = pAFin.h;
    if (document.getElementById('modal-sel-aten-fin-m')) document.getElementById('modal-sel-aten-fin-m').value = pAFin.m;
  } else {
    const defCIni = tgt === 'hum' ? { h: '08', m: '00', ampm: 'AM' } : { h: '02', m: '00', ampm: 'PM' };
    const defCFin = tgt === 'hum' ? { h: '12', m: '20', ampm: 'PM' } : { h: '06', m: '20', ampm: 'PM' };
    const pCIni = parseHoraMinutoAmpm(horaClaseIniStr, defCIni.h, defCIni.m, defCIni.ampm);
    const pCFin = parseHoraMinutoAmpm(horaClaseFinStr, defCFin.h, defCFin.m, defCFin.ampm);

    if (document.getElementById('modal-sel-clase-ini-h')) document.getElementById('modal-sel-clase-ini-h').value = pCIni.h;
    if (document.getElementById('modal-sel-clase-ini-m')) document.getElementById('modal-sel-clase-ini-m').value = pCIni.m;
    if (document.getElementById('modal-sel-clase-ini-ampm')) document.getElementById('modal-sel-clase-ini-ampm').value = pCIni.ampm;

    if (document.getElementById('modal-sel-clase-fin-h')) document.getElementById('modal-sel-clase-fin-h').value = pCFin.h;
    if (document.getElementById('modal-sel-clase-fin-m')) document.getElementById('modal-sel-clase-fin-m').value = pCFin.m;
    if (document.getElementById('modal-sel-clase-fin-ampm')) document.getElementById('modal-sel-clase-fin-ampm').value = pCFin.ampm;

    const defAIni = tgt === 'hum' ? { h: '08', m: '00', ampm: 'AM' } : { h: '02', m: '00', ampm: 'PM' };
    const defAFin = tgt === 'hum' ? { h: '12', m: '00', ampm: 'PM' } : { h: '06', m: '00', ampm: 'PM' };
    const pAIni = parseHoraMinutoAmpm(horaAtenIniStr, defAIni.h, defAIni.m, defAIni.ampm);
    const pAFin = parseHoraMinutoAmpm(horaAtenFinStr, defAFin.h, defAFin.m, defAFin.ampm);

    if (document.getElementById('modal-sel-aten-ini-h')) document.getElementById('modal-sel-aten-ini-h').value = pAIni.h;
    if (document.getElementById('modal-sel-aten-ini-m')) document.getElementById('modal-sel-aten-ini-m').value = pAIni.m;
    if (document.getElementById('modal-sel-aten-ini-ampm')) document.getElementById('modal-sel-aten-ini-ampm').value = pAIni.ampm;

    if (document.getElementById('modal-sel-aten-fin-h')) document.getElementById('modal-sel-aten-fin-h').value = pAFin.h;
    if (document.getElementById('modal-sel-aten-fin-m')) document.getElementById('modal-sel-aten-fin-m').value = pAFin.m;
    if (document.getElementById('modal-sel-aten-fin-ampm')) document.getElementById('modal-sel-aten-fin-ampm').value = pAFin.ampm;
  }

  const modal = document.getElementById('modalEditorHorarioArea');
  if (modal) modal.style.display = 'flex';
}

