async function guardarMateriasHumanisticaDirecto() {
  const filasEpa = document.querySelectorAll('#tbody-hum-epa tr.hum-fila-editable');
  const filasEsa = document.querySelectorAll('#tbody-hum-esa tr.hum-fila-editable');

  const epa = [];
  filasEpa.forEach(tr => {
    const mat = tr.querySelector('.input-hum-materia')?.value.trim() || '';
    const doc = tr.querySelector('.select-hum-docente')?.value || '';
    const cic = tr.querySelector('.input-hum-ciclo')?.value.trim() || '';
    if (mat) epa.push({ materia: mat, docente: doc, ciclo: cic });
  });

  const esa = [];
  filasEsa.forEach(tr => {
    const mat = tr.querySelector('.input-hum-materia')?.value.trim() || '';
    const doc = tr.querySelector('.select-hum-docente')?.value || '';
    const cic = tr.querySelector('.input-hum-ciclo')?.value.trim() || '';
    if (mat) esa.push({ materia: mat, docente: doc, ciclo: cic });
  });

  const dataActual = lsGet('cea_humanistica_data', HUMANISTICA_DEFAULT);
  const nuevaData = {
    epa: epa.length ? epa : HUMANISTICA_DEFAULT.epa,
    esa: esa.length ? esa : HUMANISTICA_DEFAULT.esa,
    ciclos: dataActual.ciclos || HUMANISTICA_DEFAULT.ciclos || []
  };

  lsSet('cea_humanistica_data', nuevaData);

  // Sincronizar docentes de asignaturas humanísticas con el directorio del director
  const docentesGlobal = lsGet('cea_docentes', DOCENTES_DEFAULT);
  [...epa, ...esa].forEach(m => {
    if (!m.docente) return;
    const matLower = (m.materia || '').toLowerCase();
    if (matLower.includes('natural') || matLower.includes('biolog') || matLower.includes('físic') || matLower.includes('químic')) {
      docentesGlobal['hum-cn'] = m.docente;
    } else if (matLower.includes('matem') || matLower.includes('estadíst')) {
      docentesGlobal['hum-mat'] = m.docente;
    } else if (matLower.includes('social') || matLower.includes('cívic') || matLower.includes('histor')) {
      docentesGlobal['hum-cs'] = m.docente;
    } else if (matLower.includes('lengua') || matLower.includes('literat') || matLower.includes('comunic')) {
      docentesGlobal['hum-len'] = m.docente;
    }
  });
  lsSet('cea_docentes', docentesGlobal);
  if (typeof cargarDocentesUnificados === 'function') cargarDocentesUnificados();

  cancelarEdicionMateriasHumanistica();
  mostrarToastLive('Asignaturas y docentes del Área Humanística actualizados.');

  await enviarGoogleSheet({
    action: 'guardar-humanistica-malla',
    humanistica: nuevaData
  });
  await enviarGoogleSheet({
    action: 'guardar-docentes',
    docentes: docentesGlobal
  });
  mostrarToastLive('Área Humanística sincronizada en Google Sheets.');
}

