/* ─── REQUISITOS SEGÚN EL NIVEL A CURSAR (ETTP) ─── */
const REQ_NIVELES_TEC_DEFAULT = [
  { nivel: 'Técnico Básico (1 Semestre)', req: '15 años cumplidos y fotocopia simple de Cédula de Identidad (CI).' },
  { nivel: 'Técnico Auxiliar (1 Semestre)', req: 'Certificado de Técnico Básico o libreta/certificado aprobado del nivel anterior.' },
  { nivel: 'Técnico Medio (2 Semestres)', req: 'Certificado oficial de Técnico Auxiliar.' }
];

let edicionDirectaReqNivelesTecActiva = false;

function renderReqNivelesTec() {
  const cont = document.getElementById('contenedor-req-niveles-tec');
  if (!cont) return;

  const data = lsGet('cea_req_niveles_tec', REQ_NIVELES_TEC_DEFAULT);

  if (!edicionDirectaReqNivelesTecActiva) {
    cont.innerHTML = `
      <ul class="req-lista-sencilla">
        ${data.map(item => `<li><strong>${escapeHTML(item.nivel)}:</strong> ${escapeHTML(item.req)}</li>`).join('')}
      </ul>
    `;
  } else {
    cont.innerHTML = `
      <div style="display:flex;flex-direction:column;gap:8px" class="req-niveles-tec-edit-list">
        ${data.map((item, idx) => `
          <div class="req-nivel-edit-item" data-idx="${idx}" style="background:var(--bg-card);border:1px solid var(--verde);border-radius:6px;padding:8px">
            <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px">
              <input type="text" class="input-req-nivel-tit doc-input-compact" value="${escapeHTML(item.nivel)}" placeholder="Ej: Técnico Básico (1 Semestre)" style="font-weight:700;flex:1;margin-right:8px" />
              <button type="button" class="btn-doc-del" onclick="eliminarFilaReqNivelTec(${idx})" title="Eliminar nivel" style="background:transparent;border:none;color:#ef4444;cursor:pointer;padding:4px">
                <svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="2"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>
              </button>
            </div>
            <textarea class="input-req-nivel-desc doc-input-compact" rows="2" placeholder="Requisitos necesarios..." style="width:100%;box-sizing:border-box;resize:vertical">${escapeHTML(item.req)}</textarea>
          </div>
        `).join('')}
      </div>
    `;
  }
}

