/* ─── GESTIÓN DE GALERÍA FOTOGRÁFICA EN PANEL DIRECTOR ─── */
function cambiarVistaGaleriaAdmin(tipo) {
  const btnGal = document.getElementById('btn-admin-sub-galeria');
  const btnMuro = document.getElementById('btn-admin-sub-muro');
  const viewGal = document.getElementById('admin-subview-galeria');
  const viewMuro = document.getElementById('admin-subview-muro');

  if (tipo === 'galeria') {
    if (btnGal) {
      btnGal.style.background = 'var(--verde-dark)';
      btnGal.style.color = '#ffffff';
    }
    if (btnMuro) {
      btnMuro.style.background = 'var(--bg-body)';
      btnMuro.style.color = 'var(--text-main)';
    }
    if (viewGal) viewGal.style.display = 'block';
    if (viewMuro) viewMuro.style.display = 'none';
    cargarGaleriaFotosAdmin();
  } else {
    if (btnGal) {
      btnGal.style.background = 'var(--bg-body)';
      btnGal.style.color = 'var(--text-main)';
    }
    if (btnMuro) {
      btnMuro.style.background = 'var(--verde-dark)';
      btnMuro.style.color = '#ffffff';
    }
    if (viewGal) viewGal.style.display = 'none';
    if (viewMuro) viewMuro.style.display = 'block';
  }
}

function cargarGaleriaFotosAdmin(filtro = 'todas') {
  const container = document.getElementById('lista-fotos-galeria-admin');
  if (!container) return;

  const fotos = lsGet('cea_galeria_fotos', []);
  const filtradas = (filtro === 'todas') ? fotos : fotos.filter(f => f.carrera === filtro);

  if (!filtradas.length) {
    container.innerHTML = `<div style="grid-column:1/-1;text-align:center;padding:24px;color:var(--text-sec);background:var(--bg-body);border-radius:8px">No hay fotografías registradas en esta categoría aún.</div>`;
    return;
  }

  container.innerHTML = filtradas.map((f, idx) => `
    <div style="border:1px solid var(--border-col);border-radius:10px;overflow:hidden;background:var(--bg-card);box-shadow:0 2px 6px rgba(0,0,0,0.06);display:flex;flex-direction:column">
      <div style="height:140px;overflow:hidden;background:#000000;display:flex;align-items:center;justify-content:center">
        <img src="${f.url}" alt="${f.titulo}" style="width:100%;height:100%;object-fit:cover" onerror="this.src='FOTOGRAFIA DEL CEA .jpeg'" />
      </div>
      <div style="padding:10px;flex:1;display:flex;flex-direction:column;justify-content:space-between">
        <div>
          <span style="font-size:0.72rem;background:var(--verde-light);color:var(--verde-dark);padding:2px 6px;border-radius:4px;font-weight:700;text-transform:uppercase">${f.carrera || 'General'}</span>
          <h5 style="margin:6px 0 4px;font-size:0.86rem;color:var(--text-main);line-height:1.3">${f.titulo}</h5>
        </div>
        <div style="margin-top:10px;display:flex;justify-content:space-between;align-items:center">
          <span style="font-size:0.72rem;color:var(--text-sec)">${f.fecha || '2026'}</span>
          <button type="button" class="btn-doc-del" onclick="eliminarFotoGaleriaAdmin(${idx})" title="Eliminar fotografía" style="padding:4px 8px">
            <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>
          </button>
        </div>
      </div>
    </div>
  `).join('');
}

function filtrarGaleriaAdmin(cat) {
  cargarGaleriaFotosAdmin(cat);
}

async function guardarFotoGaleriaAdmin() {
  const titulo = (document.getElementById('gal-adm-titulo')?.value || '').trim();
  const carrera = document.getElementById('gal-adm-carrera')?.value || 'general';
  const url = (document.getElementById('gal-adm-url')?.value || '').trim();

  if (!titulo) {
    mostrarMsg('msg-galeria-admin', 'Por favor ingresa un título para la foto.', 'error');
    return;
  }
  if (!url) {
    mostrarMsg('msg-galeria-admin', 'Por favor selecciona una foto o introduce una URL.', 'error');
    return;
  }

  const fotos = lsGet('cea_galeria_fotos', []);
  const nueva = {
    id: 'foto_' + Date.now(),
    titulo: titulo,
    carrera: carrera,
    url: url,
    fecha: new Date().toLocaleDateString('es-BO', { month: 'short', year: 'numeric' })
  };

  fotos.unshift(nueva);
  lsSet('cea_galeria_fotos', fotos);

  const titEl = document.getElementById('gal-adm-titulo');
  const urlEl = document.getElementById('gal-adm-url');
  if (titEl) titEl.value = '';
  if (urlEl) urlEl.value = '';
  const fnSpan = document.getElementById('gal-adm-file-name');
  if (fnSpan) fnSpan.textContent = '';

  mostrarMsg('msg-galeria-admin', '¡Fotografía guardada con éxito!', 'success');
  cargarGaleriaFotosAdmin();

  // Sincronizar en línea
  await enviarGoogleSheet({ action: 'guardar-foto-galeria', foto: nueva });
}

async function eliminarFotoGaleriaAdmin(idx) {
  const fotos = lsGet('cea_galeria_fotos', []);
  if (!fotos[idx]) return;

  const ok = await mostrarConfirmModal(`¿Deseas eliminar la fotografía "${fotos[idx].titulo}"?`, 'Eliminar Fotografía', 'Eliminar', true);
  if (!ok) return;

  const eliminada = fotos.splice(idx, 1)[0];
  lsSet('cea_galeria_fotos', fotos);
  cargarGaleriaFotosAdmin();
  mostrarToastLive('Fotografía eliminada.');

  await enviarGoogleSheet({ action: 'eliminar-foto-galeria', id: eliminada.id });
}

/* ─── HORARIOS (día + hora editables) ─── */
function colorDia(dia) {
  return COLOR_DIA[dia.toLowerCase()] || '#555';
}

function cargarHorarios() {
  const customPeriodos = lsGet('cea_bth_periodos_custom', null);
  if (customPeriodos && Array.isArray(customPeriodos) && customPeriodos.length > 0) {
    HORARIOS_BTH_CANONICO.periodos = customPeriodos;
  }
  const saved = lsGet('cea_gestor_app_state', null);
  if (saved) {
    appStateGestor = Object.assign({}, appStateGestor, saved);
    if (appStateGestor.colores) {
      if (appStateGestor.colores.header) document.documentElement.style.setProperty('--color-header', appStateGestor.colores.header);
      if (appStateGestor.colores.headerTxt) document.documentElement.style.setProperty('--color-header-txt', appStateGestor.colores.headerTxt);
      if (appStateGestor.colores.dias) document.documentElement.style.setProperty('--color-dias', appStateGestor.colores.dias);
      if (appStateGestor.colores.diasTxt) document.documentElement.style.setProperty('--color-dias-txt', appStateGestor.colores.diasTxt);
      if (appStateGestor.colores.lineas) document.documentElement.style.setProperty('--color-lineas', appStateGestor.colores.lineas);
    }
    if (appStateGestor.titulo) HORARIOS_BTH_CANONICO.titulo = appStateGestor.titulo;
    if (appStateGestor.especialidad) HORARIOS_BTH_CANONICO.subtitulo = appStateGestor.especialidad;
  }
  cargarHorariosMatriz();
  cargarEditorHorariosMatriz();
}

function renderHorarioGrid(gridId, lista) {
  const grid = document.getElementById(gridId);
  if (!grid) return;
  grid.innerHTML = lista.map(item => `
    <div class="horario-dia">
      <span class="dia-label" style="background:${colorDia(item.dia)};color:#fff">${item.dia}</span>
      <span class="hora-rango">${item.hora}</span>
    </div>`).join('');
}

function renderHorarioAdminList(containerId, lista, area) {
  const c = document.getElementById(containerId);
  if (!c) return;
  const iconTrash = `<svg class="svg-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="width:16px;height:16px"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>`;
  c.innerHTML = lista.map((item, i) => `
    <div style="display:flex;gap:8px;align-items:center;margin-bottom:10px;flex-wrap:wrap">
      <input type="text" value="${item.dia}" placeholder="Día (ej: Lunes)"
        style="flex:1;min-width:120px;padding:8px 12px;border:2px solid var(--border-col);border-radius:8px;background:var(--bg-card);color:var(--text-main);font-family:inherit"
        id="hor-${area}-dia-${i}" />
      <input type="text" value="${item.hora}" placeholder="Hora (ej: 08:00 – 12:00)"
        style="flex:2;min-width:160px;padding:8px 12px;border:2px solid var(--border-col);border-radius:8px;background:var(--bg-card);color:var(--text-main);font-family:inherit"
        id="hor-${area}-hora-${i}" />
      <button onclick="eliminarDiaHorario('${area}',${i})"
        style="background:#c0392b;color:#fff;border:none;border-radius:8px;padding:8px 14px;cursor:pointer;font-weight:700;flex-shrink:0;display:flex;align-items:center;justify-content:center" title="Eliminar">${iconTrash}</button>
    </div>`).join('');
}

function agregarDiaHorario(area) {
  const h = lsGet('cea_horarios_v2', HORARIOS_DEFAULT_V2);
  if (!h[area]) h[area] = [];
  h[area].push({ dia: 'Nuevo día', hora: '08:00 – 12:00' });
  lsSet('cea_horarios_v2', h);
  cargarHorarios();
}

function eliminarDiaHorario(area, idx) {
  const h = lsGet('cea_horarios_v2', HORARIOS_DEFAULT_V2);
  if (h[area]) h[area].splice(idx, 1);
  lsSet('cea_horarios_v2', h);
  cargarHorarios();
}

async function guardarHorarios() {
  const h = lsGet('cea_horarios_v2', HORARIOS_DEFAULT_V2);
  ['hum','tec'].forEach(area => {
    const lista = h[area] || [];
    lista.forEach((_, i) => {
      const diaInp  = document.getElementById(`hor-${area}-dia-${i}`);
      const horaInp = document.getElementById(`hor-${area}-hora-${i}`);
      if (diaInp)  lista[i].dia  = diaInp.value.trim()  || lista[i].dia;
      if (horaInp) lista[i].hora = horaInp.value.trim() || lista[i].hora;
    });
    h[area] = lista;
  });
  lsSet('cea_horarios_v2', h);
  cargarHorarios();

  mostrarMsg('msg-horarios', 'Guardando...', 'success');
  await enviarGoogleSheet({ action: 'guardar-horarios', horarios: h });
  mostrarMsg('msg-horarios', '¡Guardado exitosamente!', 'success');
}

/* ─── MATERIAS HUMANÍSTICA ─── */
function cargarMaterias() {
  const lista = lsGet('cea_materias_hum', MATERIAS_DEFAULT);
  const ul = document.getElementById('lista-materias-hum');
  if (ul) ul.innerHTML = lista.map(m => `<li>${m}</li>`).join('');
  renderMateriasAdminList(lista);
}

function renderMateriasAdminList(lista) {
  const c = document.getElementById('materias-hum-list');
  if (!c) return;
  const iconTrash = `<svg class="svg-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="width:16px;height:16px"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>`;
  c.innerHTML = lista.map((m, i) => `
    <div style="display:flex;gap:8px;align-items:center;margin-bottom:10px">
      <input type="text" value="${m}" placeholder="Nombre de la materia"
        style="flex:1;padding:8px 12px;border:2px solid var(--border-col);border-radius:8px;background:var(--bg-card);color:var(--text-main);font-family:inherit"
        id="mat-hum-${i}" />
      <button onclick="eliminarMateria(${i})"
        style="background:#c0392b;color:#fff;border:none;border-radius:8px;padding:8px 14px;cursor:pointer;font-weight:700;flex-shrink:0;display:flex;align-items:center;justify-content:center" title="Eliminar">${iconTrash}</button>
    </div>`).join('');
}

function agregarMateria() {
  const lista = lsGet('cea_materias_hum', MATERIAS_DEFAULT);
  lista.push('Nueva materia');
  lsSet('cea_materias_hum', lista);
  cargarMaterias();
}

function eliminarMateria(idx) {
  const lista = lsGet('cea_materias_hum', MATERIAS_DEFAULT);
  lista.splice(idx, 1);
  lsSet('cea_materias_hum', lista);
  cargarMaterias();
}

async function guardarMaterias() {
  const lista = lsGet('cea_materias_hum', MATERIAS_DEFAULT);
  lista.forEach((_, i) => {
    const inp = document.getElementById(`mat-hum-${i}`);
    if (inp && inp.value.trim()) lista[i] = inp.value.trim();
  });
  lsSet('cea_materias_hum', lista);
  cargarMaterias();

  mostrarMsg('msg-materias', 'Guardando...', 'success');
  await enviarGoogleSheet({ action: 'guardar-materias', materias: lista });
  mostrarMsg('msg-materias', '¡Guardado exitosamente!', 'success');
}

/* ─── GENERADOR DE MALLA CURRICULAR EN FORMATO GRID OFICIAL (20 MÓDULOS) ─── */
function generarMallaCurricularOficialHTML(area) {
  const defaultAreaObj = BASE_CARRERAS_20.find(b => b.key === area.key || b.nombre.toLowerCase() === area.nombre.toLowerCase()) || BASE_CARRERAS_20[0];
  const mallaLista = (area.malla && area.malla.length > 0) ? area.malla : defaultAreaObj.malla;

  const basicoObj   = mallaLista.find(n => n.nivel.includes('Básico')) || mallaLista[0] || { modulos: [] };
  const auxiliarObj = mallaLista.find(n => n.nivel.includes('Auxiliar')) || mallaLista[1] || { modulos: [] };
  const medio1Obj   = mallaLista.find(n => (n.nivel.includes('Medio I') || n.nivel === 'Técnico Medio I') && !n.nivel.includes('Medio II')) || mallaLista[2] || { modulos: [] };
  const medio2Obj   = mallaLista.find(n => n.nivel.includes('Medio II') || n.nivel === 'Técnico Medio II') || mallaLista[3] || { modulos: [] };

  const modBasico   = basicoObj.modulos || [];
  const modAuxiliar = auxiliarObj.modulos || [];
  const modMedio1   = medio1Obj.modulos || [];
  const modMedio2   = medio2Obj.modulos || [];

  let rowsHTML = '';
  for (let i = 0; i < 5; i++) {
    const b = modBasico[i] || [`MÓDULO ${i+1}`, 'Emergente'];
    const a = modAuxiliar[i] || [`MÓDULO ${i+6}`, 'Emergente'];
    const m1 = modMedio1[i] || [`MÓDULO ${i+11}`, 'Emergente'];
    const m2 = modMedio2[i] || [`MÓDULO ${i+16}`, 'Emergente'];

    rowsHTML += `
      <tr>
        ${i === 0 ? `<td rowspan="15" class="campo-saber">TÉCNICA TECNOLÓGICA Y PRODUCTIVA</td>` : ''}
        <td class="mod-num">${b[0]}</td><td class="mod-num">${a[0]}</td><td class="mod-num">${m1[0]}</td><td class="mod-num">${m2[0]}</td>
        <td rowspan="3" class="mod-count" style="vertical-align:middle">4</td>
      </tr>
      <tr>
        <td>${b[1]}</td><td>${a[1]}</td><td>${m1[1]}</td><td>${m2[1]}</td>
      </tr>
      <tr class="horas-row">
        <td>100 Horas</td><td>100 Horas</td><td>100 Horas</td><td>100 Horas</td>
      </tr>
    `;
  }

  return `
    <div class="malla-sistemas-wrap" style="margin-top:10px">
      <table class="tabla-malla-oficial">
        <thead>
          <tr>
            <th rowspan="3">CAMPOS DE SABER Y CONOCIMIENTO</th>
            <th colspan="4">MALLA CURRICULAR: ${(area.nombre || '').toUpperCase()}</th>
            <th rowspan="3">N° DE MÓDULOS</th>
          </tr>
          <tr>
            <th colspan="2">PRIMER AÑO</th>
            <th colspan="2">SEGUNDO AÑO</th>
          </tr>
          <tr>
            <th>TÉCNICO BÁSICO</th>
            <th>TÉCNICO AUXILIAR</th>
            <th>TÉCNICO MEDIO I</th>
            <th>TÉCNICO MEDIO II</th>
          </tr>
        </thead>
        <tbody>
          ${rowsHTML}
        </tbody>
      </table>
    </div>
  `;
}

/* ─── CONTROL DE ACORDEÓN ÚNICO PARA MALLAS (Solo una abierta a la vez) ─── */
function cerrarOtrasMallas(element) {
  if (!element || !element.open) return;
  const allDetails = document.querySelectorAll('#carreras-grid-display details.malla-details');
  allDetails.forEach(det => {
    if (det !== element && det.open) {
      det.removeAttribute('open');
    }
  });
}

/* ─── ÁREAS TÉCNICAS (DINÁMICAS EN OFERTA Y TÉCNICA) ─── */
function cargarAreasTecSilencioso() {
  asegurarDatalistsDisponiblesCarrera();
  const areas = lsGet('cea_areas_tec', AREAS_TEC_DEFAULT);
  const docentes = lsGet('cea_docentes', DOCENTES_DEFAULT);
  const session = lsGet('cea_session', null);
  const isDirector = session && session.role === 'director';

  // 1. Renderizar bloque ETA dinámico en Oferta Formativa
  const etaContainer = document.getElementById('eta-carreras-display');
  if (etaContainer) {
    etaContainer.innerHTML = areas.map(a => `
      <div class="eta-carrera">
        <h4>${a.nombre.toUpperCase()}</h4>
        <div class="eta-niveles">
          <span class="eta-nivel basico">Técnico Básico</span>
          <span class="eta-nivel auxiliar">Técnico Auxiliar</span>
          <span class="eta-nivel medio">Técnico Medio I</span>
          <span class="eta-nivel medio">Técnico Medio II</span>
        </div>
      </div>
    `).join('');
  }

  // 2. Renderizar tarjetas con mallas oficiales en Área Técnica
  const grid = document.getElementById('carreras-grid-display');
  if (grid) {
    grid.innerHTML = areas.map((a) => {
      let fotoHTML = '';
      if (a.key === 'tec-sis') fotoHTML = '<img src="FOTOGRAFIA DE SISTEMAS.jpg" alt="Sistemas Informáticos" class="carrera-foto" />';

      const docenteActual = docentes[a.key] || docentes[a.docente] || a.docente || '—';

      return `
        <div class="carrera-card" id="card-carrera-tec-${a.key}">
          <div class="carrera-header">
            <div class="carrera-header-group">
              <div class="carrera-icon-badge">
                ${obtenerIconoCarreraTec(a.key, a.nombre, 22)}
              </div>
              <h4 class="carrera-header-title" id="carrera-nombre-display-${a.key}">${escapeHTML(a.nombre)}</h4>
            </div>
          </div>
          ${fotoHTML}
          <div class="carrera-body">
            <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:6px;margin-bottom:6px">
              <p style="margin:0;font-size:0.93rem"><strong>Docente:</strong> <span id="carrera-docente-display-${a.key}">${escapeHTML(docenteActual)}</span></p>
              ${isDirector ? `
                <button type="button" class="btn-submit" onclick="toggleEdicionCarreraTecInline('${a.key}')" style="font-size:0.75rem;padding:4px 10px;background:#2563eb;color:#ffffff;border:none;border-radius:6px;font-weight:700;display:inline-flex;align-items:center;gap:5px;cursor:pointer" title="Editar carrera, docente o descripción">
                  <svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="#ffffff" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
                  <span>Editar Datos</span>
                </button>
              ` : ''}
            </div>

            <!-- Panel de edición inline para el Director -->
            <div id="panel-edit-carrera-tec-${a.key}" class="inline-docente-edit-wrap" style="display:none;padding:12px;border:1.5px solid #2563eb;border-radius:8px;background:rgba(37,99,235,0.04);margin:8px 0;">
              <label style="font-size:0.75rem;font-weight:700;color:#2563eb;display:block;margin-bottom:3px">Nombre de la Carrera (seleccionar o escribir personalizado):</label>
              <input type="text" id="inp-edit-carrera-nombre-${a.key}" list="dl-carreras-disponibles" value="${escapeHTML(a.nombre)}" class="inline-docente-manual-input" placeholder="Nombre de la especialidad..." style="margin-bottom:8px;width:100%" />

              <label style="font-size:0.75rem;font-weight:700;color:#2563eb;display:block;margin-bottom:3px">Docente Asignado (seleccionar de la lista o escribir nuevo nombre):</label>
              <input type="text" id="inp-edit-carrera-docente-${a.key}" list="dl-docentes-disponibles" value="${escapeHTML(docenteActual === '—' ? '' : docenteActual)}" placeholder="Ej: Lic. Edmar Callisaya o escribir nuevo..." class="inline-docente-manual-input" style="margin-bottom:8px;width:100%" />

              <label style="font-size:0.75rem;font-weight:700;color:#2563eb;display:block;margin-bottom:3px">Descripción / Párrafo informativo:</label>
              <textarea id="inp-edit-carrera-resumen-${a.key}" class="inline-docente-manual-input" rows="3" style="margin-bottom:10px;width:100%">${escapeHTML(a.resumen || '')}</textarea>

              <div style="display:flex;gap:6px;justify-content:flex-end">
                <button type="button" class="btn-cancelar" onclick="toggleEdicionCarreraTecInline('${a.key}')" style="font-size:0.78rem;padding:5px 12px">Cancelar</button>
                <button type="button" class="btn-submit" onclick="guardarEdicionCarreraTecInline('${a.key}')" style="font-size:0.78rem;padding:5px 14px;background:#2563eb;color:#ffffff;border:none;border-radius:6px;font-weight:700">Guardar Cambios</button>
              </div>
            </div>

            <p id="carrera-resumen-display-${a.key}" style="margin-top:10px;font-size:0.93rem;color:var(--text-sec)">${escapeHTML(a.resumen || '')}</p>
            <span class="badge">20 módulos – 2000 horas</span>
            <div style="margin-top:16px">
              <button class="btn-download" onclick="abrirModalCarrera('${a.key}')" style="width:100%;text-align:center;padding:12px;background:var(--verde);color:#fff;border-radius:8px;border:none;font-weight:700;cursor:pointer;font-size:0.92rem;display:inline-flex;align-items:center;justify-content:center;gap:6px"><svg class="svg-icon" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor"><line x1="8" y1="6" x2="21" y2="6"/><line x1="8" y1="12" x2="21" y2="12"/><line x1="8" y1="18" x2="21" y2="18"/><line x1="3" y1="6" x2="3.01" y2="6"/><line x1="3" y1="12" x2="3.01" y2="12"/><line x1="3" y1="18" x2="3.01" y2="18"/></svg> Ver Malla Curricular Completa</button>
            </div>
          </div>
        </div>`;
    }).join('');
  }

  // 3. Sincronizar viñetas previas de carreras técnicas con sus íconos correspondientes
  const tecBullets = document.getElementById('oferta-tec-preview-bullets');
  if (tecBullets && areas && areas.length > 0) {
    tecBullets.classList.add('con-iconos');
    tecBullets.innerHTML = areas.map(a => `
      <li>
        <span class="oferta-carrera-bullet-icon">
          ${obtenerIconoCarreraTec(a.key, a.nombre, 14)}
        </span>
        <span>${escapeHTML(a.nombre)}</span>
      </li>
    `).join('');
  }
}

window.addEventListener('resize', () => {
  const container = document.getElementById('contenedor-casos-excepcionales');
  if (container && !edicionDirectaCasosActiva && container.style.display === 'grid') {
    container.style.gridTemplateColumns = (window.innerWidth <= 768) ? '1fr' : 'repeat(2, 1fr)';
  }
}, { passive: true });

function toggleEdicionCarreraTecInline(key) {
  const panel = document.getElementById(`panel-edit-carrera-tec-${key}`);
  if (panel) {
    panel.style.display = panel.style.display === 'none' ? 'block' : 'none';
  }
}

function asegurarDatalistsDisponiblesCarrera() {
  let dlDoc = document.getElementById('dl-docentes-disponibles');
  if (!dlDoc) {
    dlDoc = document.createElement('datalist');
    dlDoc.id = 'dl-docentes-disponibles';
    document.body.appendChild(dlDoc);
  }
  const docentesObj = lsGet('cea_docentes', DOCENTES_DEFAULT);
  const nombresLista = Array.isArray(docentesObj) ? docentesObj.map(d => d.nombre) : Object.values(docentesObj).map(d => (typeof d === 'string' ? d : d?.nombre));
  const defaults = [
    'Lic. Edmar Callisaya Tapia',
    'Lic. Marcela Choque Mamani',
    'Lic. María Estela Laura Tenorio',
    'Lic. Efraina Pajarito Ventura',
    'Lic. Ramiro Machaca',
    'Lic. Sonia Quispe Mamani'
  ];
  const setDoc = Array.from(new Set([...defaults, ...nombresLista].filter(Boolean)));
  dlDoc.innerHTML = setDoc.map(n => `<option value="${escapeHTML(n)}"></option>`).join('');

  let dlCar = document.getElementById('dl-carreras-disponibles');
  if (!dlCar) {
    dlCar = document.createElement('datalist');
    dlCar.id = 'dl-carreras-disponibles';
    document.body.appendChild(dlCar);
  }
  if (typeof BASE_CARRERAS_20 !== 'undefined') {
    dlCar.innerHTML = BASE_CARRERAS_20.map(c => `<option value="${escapeHTML(c.nombre)}"></option>`).join('');
  }
}

async function guardarEdicionCarreraTecInline(key) {
  const inpNom = document.getElementById(`inp-edit-carrera-nombre-${key}`);
  const inpDoc = document.getElementById(`inp-edit-carrera-docente-${key}`) || document.getElementById(`inp-edit-carrera-docente-manual-${key}`);
  const inpRes = document.getElementById(`inp-edit-carrera-resumen-${key}`);

  const nuevoNombre = inpNom ? inpNom.value.trim() : '';
  const nuevoDocente = inpDoc ? inpDoc.value.trim() : '';
  const nuevoResumen = inpRes ? inpRes.value.trim() : '';

  const areas = lsGet('cea_areas_tec', AREAS_TEC_DEFAULT);
  const docentes = lsGet('cea_docentes', DOCENTES_DEFAULT);

  const idx = areas.findIndex(a => a.key === key);
  const viejoNom = (idx !== -1 && areas[idx].docente) ? areas[idx].docente : (docentes[key] || '');

  if (idx !== -1) {
    if (nuevoNombre) areas[idx].nombre = nuevoNombre;
    areas[idx].docente = nuevoDocente;
    areas[idx].resumen = nuevoResumen;
  }

  docentes[key] = nuevoDocente;

  if (viejoNom && viejoNom !== nuevoDocente) {
    if (typeof actualizarNombreDocenteEnTodoElSistema === 'function') {
      actualizarNombreDocenteEnTodoElSistema(viejoNom, nuevoDocente, key);
    }
  }

  lsSet('cea_areas_tec', areas);
  lsSet('cea_docentes', docentes);

  // Sincronizar en segundo plano con Google Sheets
  await enviarGoogleSheet({ action: 'guardar-carreras', carreras: areas });
  await enviarGoogleSheet({ action: 'guardar-docentes', docentes: docentes });

  mostrarToastLive('Carrera y docente actualizados correctamente.');

  // Re-renderizar todas las vistas vinculadas
  cargarAreasTecSilencioso();
  if (typeof cargarDocentesUnificados === 'function') cargarDocentesUnificados();
  if (typeof renderDirectorioDocentes === 'function') renderDirectorioDocentes();
  if (typeof renderSeccionHumanistica === 'function') renderSeccionHumanistica();
}

function poblarSelectCarrerasOficiales() {
  asegurarDatalistsDisponiblesCarrera();
  const select = document.getElementById('select-carrera-oficial');
  const datalist = document.getElementById('lista-carreras-oficiales-sugerencias');
  const areasActivas = lsGet('cea_areas_tec', AREAS_TEC_DEFAULT);

  if (select) {
    select.innerHTML = '<option value="">-- Seleccionar de las 20 Carreras Oficiales --</option>' + BASE_CARRERAS_20.map(c => {
      const yaExiste = areasActivas.some(a => a.key === c.key || a.nombre.toLowerCase() === c.nombre.toLowerCase());
      return `<option value="${c.key}">${c.nombre} ${yaExiste ? '(Ya activa)' : ''}</option>`;
    }).join('');
  }

  if (datalist) {
    datalist.innerHTML = BASE_CARRERAS_20.map(c => `<option value="${c.nombre}"></option>`).join('');
  }
}

function sincronizarBusquedaConSelect() {
  const select = document.getElementById('select-carrera-oficial');
  const inp = document.getElementById('input-carrera-buscar');
  if (!select || !inp) return;
  const keySel = select.value;
  const carOficial = BASE_CARRERAS_20.find(c => c.key === keySel);
  if (carOficial) {
    inp.value = carOficial.nombre;
    mostrarMsg('msg-autocompletar-info', `[OK] Malla curricular oficial de 20 módulos detectada para "${carOficial.nombre}"`, 'success');
  }
}

function verificarSugerenciaEnTiempoReal() {
  const inp = document.getElementById('input-carrera-buscar');
  if (!inp) return;
  const val = inp.value.trim().toLowerCase();
  if (!val) return;
  const carMatch = BASE_CARRERAS_20.find(c => c.nombre.toLowerCase() === val || c.nombre.toLowerCase().includes(val));
  if (carMatch) {
    mostrarMsg('msg-autocompletar-info', `[OK] Coincidencia detectada: Malla oficial de "${carMatch.nombre}" (20 módulos)`, 'success');
    const select = document.getElementById('select-carrera-oficial');
    if (select && carMatch.key) select.value = carMatch.key;
  } else {
    mostrarMsg('msg-autocompletar-info', `[NUEVA] Se creará como nueva carrera personalizada`, 'success');
  }
}

function agregarCarreraDesdeSeleccionOBusqueda() {
  const select = document.getElementById('select-carrera-oficial');
  const inp = document.getElementById('input-carrera-buscar');
  
  let valBusqueda = inp ? inp.value.trim() : '';
  let keySel = select ? select.value : '';
  let carOficial = null;

  if (valBusqueda) {
    carOficial = BASE_CARRERAS_20.find(c => c.nombre.toLowerCase() === valBusqueda.toLowerCase());
    if (!carOficial) {
      const coincidencias = BASE_CARRERAS_20.filter(c => c.nombre.toLowerCase().includes(valBusqueda.toLowerCase()));
      if (coincidencias.length === 1) carOficial = coincidencias[0];
    }
  }

  if (!carOficial && keySel) {
    carOficial = BASE_CARRERAS_20.find(c => c.key === keySel);
  }

  const areas = lsGet('cea_areas_tec', AREAS_TEC_DEFAULT);

  if (carOficial) {
    const existe = areas.find(a => a.key === carOficial.key || a.nombre.toLowerCase() === carOficial.nombre.toLowerCase());
    if (existe) {
      mostrarMsg('msg-autocompletar-info', `La carrera "${carOficial.nombre}" ya está activa en la página web.`, 'error');
      return;
    }
    areas.push(JSON.parse(JSON.stringify(carOficial)));
    lsSet('cea_areas_tec', areas);
    cargarAreasTec();
    mostrarMsg('msg-autocompletar-info', `¡Carrera "${carOficial.nombre}" añadida exitosamente con su Malla Curricular oficial de 20 módulos!`, 'success');
  } else if (valBusqueda) {
    const nuevaKey = 'tec-custom-' + Date.now();
    areas.push({
      key: nuevaKey,
      nombre: valBusqueda,
      color: 'var(--verde-dark)',
      resumen: `Formación técnica integral en ${valBusqueda}.`,
      malla: []
    });
    lsSet('cea_areas_tec', areas);
    cargarAreasTec();
    mostrarMsg('msg-autocompletar-info', `Carrera "${valBusqueda}" añadida al sitio web.`, 'success');
  } else {
    mostrarMsg('msg-autocompletar-info', 'Por favor selecciona una carrera de la lista o escribe un nombre en el buscador.', 'error');
    return;
  }

  if (inp) inp.value = '';
  if (select) select.value = '';
}

function autoAsignarMallaPorNombre(idx, nuevoNombre) {
  if (!nuevoNombre) return;
  const val = nuevoNombre.trim().toLowerCase();
  const carOficial = BASE_CARRERAS_20.find(c => c.nombre.toLowerCase() === val);
  if (carOficial) {
    const areas = lsGet('cea_areas_tec', AREAS_TEC_DEFAULT);
    if (areas[idx] && areas[idx].key !== carOficial.key) {
      areas[idx].key = carOficial.key;
      areas[idx].nombre = carOficial.nombre;
      areas[idx].color = carOficial.color;
      areas[idx].resumen = carOficial.resumen;
      areas[idx].malla = JSON.parse(JSON.stringify(carOficial.malla));
      lsSet('cea_areas_tec', areas);
      cargarAreasTec();
      mostrarMsg('msg-areas-tec', `¡Malla curricular oficial de 20 módulos vinculada automáticamente para "${carOficial.nombre}"!`, 'success');
    }
  }
}

function restablecerMallaPorDefecto(idx) {
  const areas = lsGet('cea_areas_tec', AREAS_TEC_DEFAULT);
  if (!areas[idx]) return;
  const carOficial = BASE_CARRERAS_20.find(c => c.key === areas[idx].key || c.nombre.toLowerCase() === areas[idx].nombre.toLowerCase());
  if (carOficial) {
    areas[idx].malla = JSON.parse(JSON.stringify(carOficial.malla));
    lsSet('cea_areas_tec', areas);
    cargarAreasTec();
    mostrarMsg('msg-areas-tec', `Se restableció la malla curricular oficial de 20 módulos para "${areas[idx].nombre}".`, 'success');
  }
}

function cargarAreasTec() {
  const areas = lsGet('cea_areas_tec', AREAS_TEC_DEFAULT);
  cargarAreasTecSilencioso();
  renderAreasTecAdminList(areas);
  poblarSelectCarrerasOficiales();
  actualizarNiveles();
}

function conmutarSubvistaMallas(sub) {
  const vTec = document.getElementById('subvista-mallas-tecnicas');
  const vHum = document.getElementById('subvista-mallas-humanistica');
  const btnTec = document.getElementById('btn-subtab-malla-tec');
  const btnHum = document.getElementById('btn-subtab-malla-hum');

  if (sub === 'humanistica') {
    if (vTec) vTec.style.display = 'none';
    if (vHum) vHum.style.display = 'block';
    if (btnTec) {
      btnTec.style.background = 'var(--bg-body)';
      btnTec.style.color = 'var(--text-main)';
      btnTec.style.border = '1.5px solid var(--border-col)';
    }
    if (btnHum) {
      btnHum.style.background = 'var(--verde-dark)';
      btnHum.style.color = '#fff';
      btnHum.style.border = 'none';
    }
    if (typeof cargarMaterias === 'function') cargarMaterias();
  } else {
    if (vTec) vTec.style.display = 'block';
    if (vHum) vHum.style.display = 'none';
    if (btnTec) {
      btnTec.style.background = 'var(--verde-dark)';
      btnTec.style.color = '#fff';
      btnTec.style.border = 'none';
    }
    if (btnHum) {
      btnHum.style.background = 'var(--bg-body)';
      btnHum.style.color = 'var(--text-main)';
      btnHum.style.border = '1.5px solid var(--border-col)';
    }
    if (typeof cargarAreasTec === 'function') cargarAreasTec();
  }
}

function asegurarMallaOficialCarrera(a) {
  if (a.malla && Array.isArray(a.malla) && a.malla.length === 4) {
    return a.malla;
  }
  const match = BASE_CARRERAS_20.find(b => b.key === a.key || b.nombre.toLowerCase() === (a.nombre || '').toLowerCase());
  if (match && match.malla && match.malla.length === 4) {
    return JSON.parse(JSON.stringify(match.malla));
  }
  return [
    { nivel: 'Técnico Básico', modulos: [['Módulo I','Introducción y Fundamentos'],['Módulo II','Seguridad Ocupacional'],['Módulo III','Herramientas y Técnicas I'],['Módulo IV','Procesos Básicos'],['Módulo V','Emergente']] },
    { nivel: 'Técnico Auxiliar', modulos: [['Módulo VI','Técnicas Intermedias I'],['Módulo VII','Técnicas Intermedias II'],['Módulo VIII','Control de Calidad'],['Módulo IX','Normativas y Seguridad'],['Módulo X','Emergente']] },
    { nivel: 'Técnico Medio I', modulos: [['Módulo XI','Especialidad Avanzada I'],['Módulo XII','Especialidad Avanzada II'],['Módulo XIII','Gestión y Presupuestos'],['Módulo XIV','Taller Productivo I'],['Módulo XV','Emprendimiento Productivo']] },
    { nivel: 'Técnico Medio II', modulos: [['Módulo XVI','Especialidad Superior'],['Módulo XVII','Tecnologías Aplicadas'],['Módulo XVIII','Taller Productivo II'],['Módulo XIX','Práctica Laboral Institucional'],['Módulo XX','Modalidades de Graduación']] }
  ];
}

function toggleMallaAccordionAdmin(idx) {
  const acc = document.getElementById(`malla-accordion-admin-${idx}`);
  const btn = document.getElementById(`btn-toggle-malla-${idx}`);
  if (!acc) return;
  const isHidden = acc.style.display === 'none' || acc.style.display === '';
  acc.style.display = isHidden ? 'block' : 'none';
  if (btn) {
    btn.classList.toggle('abierto', isHidden);
    const span = btn.querySelector('span');
    if (span) {
      span.textContent = isHidden ? 'Cerrar Edición' : 'Editar Carrera';
    }
  }
}

