let edicionDirectaCasosActiva = false;

function renderCasosExcepcionales() {
  const container = document.getElementById('contenedor-casos-excepcionales');
  if (!container) return;

  const casos = lsGet('cea_casos_excepcionales', CASOS_EXCEPCIONALES_DEFAULT);

  if (!edicionDirectaCasosActiva) {
    container.style.display = 'grid';
    if (window.innerWidth <= 768) {
      container.style.gridTemplateColumns = '1fr';
    } else {
      container.style.gridTemplateColumns = 'repeat(2, 1fr)';
    }
    container.style.gap = '8px';
    container.innerHTML = casos.map((c, i) => `
      <div class="excep-pill-card ${i === casos.length - 1 && casos.length % 2 !== 0 ? 'excep-pill-full' : ''}">
        <div class="excep-pill-num">${i + 1}</div>
        <div class="excep-pill-text">
          <strong>${escapeHTML(c.situacion)}:</strong>
          <span>${escapeHTML(c.doc)}</span>
        </div>
      </div>
    `).join('');
  } else {
    // MODO EDICIÓN ESPACIOSO A ANCHO COMPLETO CON TEXTAREAS MULTILÍNEA
    container.style.display = 'flex';
    container.style.flexDirection = 'column';
    container.style.gap = '14px';
    container.innerHTML = casos.map((c, i) => `
      <div class="exc-card-editable" data-idx="${i}" style="display:flex;flex-direction:column;gap:10px;border:1.8px solid var(--verde);border-radius:10px;padding:16px;background:var(--bg-card);box-shadow:0 2px 8px rgba(0,0,0,0.05)">
        <div style="display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--border-col);padding-bottom:8px">
          <div style="display:flex;align-items:center;gap:8px">
            <span class="excep-pill-num" style="border-radius:6px;width:24px;height:24px;display:inline-flex;align-items:center;justify-content:center;font-weight:800;font-size:0.80rem">${i + 1}</span>
            <span style="font-size:0.86rem;font-weight:800;color:var(--verde-dark)">Caso Excepcional #${i + 1}</span>
          </div>
          <button type="button" class="btn-doc-del" onclick="eliminarCasoExcepcionalFila(${i})" title="Eliminar este caso" style="background:#fee2e2;border:none;color:#dc2626;cursor:pointer;padding:5px 12px;border-radius:6px;font-size:0.78rem;font-weight:700;display:inline-flex;align-items:center;gap:5px">
            <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.2"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>
            <span>Eliminar</span>
          </button>
        </div>
        <div>
          <label style="display:block;font-size:0.78rem;font-weight:800;color:var(--verde-dark);margin-bottom:4px">Situación / Caso Especial (puedes leer y escribir todo el texto):</label>
          <textarea class="input-exc-situacion" rows="3" placeholder="Ej: Personas con al menos un hijo..." style="width:100%;box-sizing:border-box;font-size:0.88rem;line-height:1.5;padding:10px 12px;border-radius:8px;border:1.5px solid var(--border-col);background:var(--bg-body, #fff);color:var(--text-main);font-family:inherit;resize:vertical;min-height:64px">${escapeHTML(c.situacion)}</textarea>
        </div>
        <div>
          <label style="display:block;font-size:0.78rem;font-weight:800;color:var(--text-sec);margin-bottom:4px">Documento(s) o Certificación de Respaldo Solicitada (Texto Completo):</label>
          <textarea class="input-exc-doc" rows="3" placeholder="Ej: Certificado de nacimiento original o fotocopia legalizada..." style="width:100%;box-sizing:border-box;font-size:0.88rem;line-height:1.5;padding:10px 12px;border-radius:8px;border:1.5px solid var(--border-col);background:var(--bg-body, #fff);color:var(--text-main);font-family:inherit;resize:vertical;min-height:64px">${escapeHTML(c.doc)}</textarea>
        </div>
      </div>
    `).join('');
  }
}

window.addEventListener('resize', () => {
  const container = document.getElementById('contenedor-casos-excepcionales');
  if (container && !edicionDirectaCasosActiva && container.style.display === 'grid') {
    container.style.gridTemplateColumns = (window.innerWidth <= 768) ? '1fr' : 'repeat(2, 1fr)';
  }
}, { passive: true });

function obtenerValoresCasosEnEdicion() {
  const container = document.getElementById('contenedor-casos-excepcionales');
  if (!container) return lsGet('cea_casos_excepcionales', CASOS_EXCEPCIONALES_DEFAULT);
  const cards = container.querySelectorAll('.exc-card-editable');
  if (!cards.length) return lsGet('cea_casos_excepcionales', CASOS_EXCEPCIONALES_DEFAULT);
  const arr = [];
  cards.forEach((card, i) => {
    const sit = card.querySelector('.input-exc-situacion')?.value.trim() || '';
    const doc = card.querySelector('.input-exc-doc')?.value.trim() || '';
    if (sit || doc) {
      arr.push({ num: i + 1, situacion: sit, doc });
    }
  });
  return arr.length ? arr : lsGet('cea_casos_excepcionales', CASOS_EXCEPCIONALES_DEFAULT);
}

