async function eliminarInscripcionPorCI(ciEncoded, nombreEncoded, idOpt) {
  const ci = decodeURIComponent(ciEncoded || '').trim().toLowerCase();
  const nombre = decodeURIComponent(nombreEncoded || '').trim().toLowerCase();
  const ins = lsGet('cea_inscripciones', []);

  const idx = ins.findIndex(item => {
    if (idOpt && item.id && String(item.id) === String(idOpt)) return true;
    const itemCi = (item.ci || '').toString().trim().toLowerCase();
    const itemNombre = (item.nombre || '').trim().toLowerCase();
    
    // Si tenemos tanto CI como nombre, exigir coincidencia de CI (o si CI coincide)
    if (ci && itemCi) {
      if (itemCi === ci) {
        if (!nombre || !itemNombre) return true;
        return itemNombre === nombre;
      }
      return false;
    }
    // Si no hay CI especificado en ninguno, usar nombre estricto
    if (nombre && itemNombre === nombre) return true;
    return false;
  });

  if (idx === -1) {
    mostrarToastLive('No se encontró el registro a eliminar.');
    return;
  }

  const item = ins[idx];
  const ok = await mostrarConfirmModal(`¿Estás seguro de eliminar la pre-inscripción de "${item.nombre || 'este estudiante'}"? También se eliminará de la base de datos en línea.`, 'Eliminar Pre-Inscripción', 'Eliminar', true);
  if (!ok) return;

  ins.splice(idx, 1);
  lsSet('cea_inscripciones', ins);
  cargarInscripciones();
  mostrarToastLive('Pre-inscripción eliminada.');

  // Sincronizar con Google Sheets (eliminación de fila y respaldo de paridad)
  try {
    await enviarGoogleSheet({
      action: 'eliminar-inscripcion',
      ci: item.ci || '',
      nombre: item.nombre || ''
    });
    await enviarGoogleSheet({
      action: 'guardar-todas-inscripciones',
      inscripciones: ins
    });
  } catch (err) {
    console.warn('Advertencia en sincronización al eliminar:', err);
  }
}

async function eliminarInscripcionPorIndice(idx) {
  const ins = lsGet('cea_inscripciones', []);
  const item = ins[idx];
  if (!item) return;
  return eliminarInscripcionPorCI(encodeURIComponent(item.ci || ''), encodeURIComponent(item.nombre || ''));
}

function abrirModalLimpiarInscripciones() {
  const ins = lsGet('cea_inscripciones', []);
  if (!ins.length) {
    mostrarAlertaModal('No hay pre-inscripciones registradas actualmente en el sistema.', 'Pre-Inscripciones');
    return;
  }
  const modal = document.getElementById('modal-limpiar-inscripciones-opciones');
  if (!modal) {
    ejecutarEliminacionInscripciones('todas');
    return;
  }
  const anioActivo = (estadoFiltroGestion && estadoFiltroGestion !== 'todas') ? estadoFiltroGestion : '2026';
  const lblGestion = document.getElementById('lbl-gestion-a-eliminar');
  if (lblGestion) lblGestion.textContent = anioActivo;

  const btnGest = document.getElementById('btn-limpiar-gestion-actual');
  if (btnGest) {
    btnGest.onclick = () => {
      cerrarModalLimpiarInscripciones();
      ejecutarEliminacionInscripciones(anioActivo);
    };
  }
  const btnTodas = document.getElementById('btn-limpiar-todas-gestiones');
  if (btnTodas) {
    btnTodas.onclick = () => {
      cerrarModalLimpiarInscripciones();
      ejecutarEliminacionInscripciones('todas');
    };
  }

  modal.style.display = 'flex';
}

function cerrarModalLimpiarInscripciones() {
  const modal = document.getElementById('modal-limpiar-inscripciones-opciones');
  if (modal) modal.style.display = 'none';
}

async function ejecutarEliminacionInscripciones(gestionTarget) {
  const ins = lsGet('cea_inscripciones', []);
  if (!ins.length) return;

  const esTodas = (gestionTarget === 'todas');
  const msgConfirm = esTodas
    ? '¿Estás seguro de que deseas eliminar TODAS las pre-inscripciones de TODAS las gestiones? Esta acción vaciará el historial completo y se sincronizará con Google Sheets.'
    : `¿Estás seguro de que deseas eliminar las pre-inscripciones de la Gestión ${gestionTarget}? Los registros de otros años se conservarán intactos.`;

  const ok = await mostrarConfirmModal(msgConfirm, 'Eliminar Pre-Inscripciones', esTodas ? 'Eliminar Todo el Historial' : `Eliminar Gestión ${gestionTarget}`, true);
  if (!ok) return;

  if (esTodas) {
    lsSet('cea_inscripciones', []);
    mostrarToastLive('Todas las pre-inscripciones del historial fueron eliminadas.');
  } else {
    const restantes = ins.filter(item => clasificarGestionRegistro(item) !== String(gestionTarget));
    lsSet('cea_inscripciones', restantes);
    mostrarToastLive(`Pre-inscripciones de la Gestión ${gestionTarget} eliminadas.`);
  }

  cargarInscripciones();

  try {
    await enviarGoogleSheet({
      action: 'limpiar-inscripciones',
      gestion: gestionTarget
    });
  } catch (err) {
    console.warn('Error al sincronizar eliminación con Google Sheets:', err);
  }
}

function limpiarInscripciones() {
  abrirModalLimpiarInscripciones();
}

/* ─── MODALES DE CONFIRMACIÓN Y ALERTA VISUALES INTEGRADOS (REEMPLAZO DE ALERT Y CONFIRM NATIVOS) ─── */
let _resolveConfirmModal = null;
let _resolveAlertModal = null;

function mostrarConfirmModal(mensaje, titulo = 'Confirmación Requerida', btnConfirmTexto = 'Eliminar', esPeligroso = true) {
  return new Promise((resolve) => {
    _resolveConfirmModal = resolve;
    const modal = document.getElementById('modal-custom-confirm');
    if (!modal) {
      resolve(window.confirm ? window.confirm(mensaje) : true);
      return;
    }
    const tEl = document.getElementById('confirm-modal-title');
    const mEl = document.getElementById('confirm-modal-msg');
    const btnOk = document.getElementById('confirm-modal-btn-ok');
    const btnCancel = document.getElementById('confirm-modal-btn-cancel');
    const iconBox = document.getElementById('confirm-modal-icon-box');

    if (tEl) tEl.textContent = titulo;
    if (mEl) mEl.textContent = mensaje;
    if (btnOk) {
      btnOk.textContent = btnConfirmTexto;
      btnOk.style.background = esPeligroso ? '#dc2626' : 'var(--verde-dark)';
      btnOk.onclick = () => cerrarConfirmModal(true);
    }
    if (btnCancel) {
      btnCancel.onclick = () => cerrarConfirmModal(false);
    }
    if (iconBox) {
      if (esPeligroso) {
        iconBox.style.background = '#fee2e2';
        iconBox.style.color = '#dc2626';
        iconBox.innerHTML = `<svg viewBox="0 0 24 24" width="28" height="28" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>`;
      } else {
        iconBox.style.background = 'var(--verde-light)';
        iconBox.style.color = 'var(--verde-dark)';
        iconBox.innerHTML = `<svg viewBox="0 0 24 24" width="28" height="28" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg>`;
      }
    }
    modal.style.display = 'flex';
  });
}

function cerrarConfirmModal(resultado) {
  const modal = document.getElementById('modal-custom-confirm');
  if (modal) modal.style.display = 'none';
  if (typeof _resolveConfirmModal === 'function') {
    const res = _resolveConfirmModal;
    _resolveConfirmModal = null;
    res(Boolean(resultado));
  }
}

function mostrarAlertaModal(mensaje, titulo = 'Aviso del Sistema', tipo = 'info') {
  return new Promise((resolve) => {
    _resolveAlertModal = resolve;
    const modal = document.getElementById('modal-custom-alert');
    if (!modal) {
      mostrarToastLive(mensaje);
      resolve(true);
      return;
    }
    const tEl = document.getElementById('alert-modal-title');
    const mEl = document.getElementById('alert-modal-msg');
    const btnOk = document.getElementById('alert-modal-btn-ok');
    const iconBox = document.getElementById('alert-modal-icon-box');

    if (tEl) tEl.textContent = titulo;
    if (mEl) mEl.textContent = mensaje;
    if (iconBox) {
      if (tipo === 'warning') {
        iconBox.style.background = '#fef3c7';
        iconBox.style.color = '#d97706';
        iconBox.innerHTML = `<svg viewBox="0 0 24 24" width="28" height="28" fill="none" stroke="currentColor" stroke-width="2.2"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>`;
      } else {
        iconBox.style.background = 'var(--verde-light)';
        iconBox.style.color = 'var(--verde-dark)';
        iconBox.innerHTML = `<svg viewBox="0 0 24 24" width="28" height="28" fill="none" stroke="currentColor" stroke-width="2.2"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/></svg>`;
      }
    }
    if (btnOk) {
      btnOk.onclick = () => cerrarAlertaModal();
    }
    modal.style.display = 'flex';
  });
}

function cerrarAlertaModal() {
  const modal = document.getElementById('modal-custom-alert');
  if (modal) modal.style.display = 'none';
  if (typeof _resolveAlertModal === 'function') {
    const res = _resolveAlertModal;
    _resolveAlertModal = null;
    res(true);
  }
}

// Reemplazar window.alert nativo para que nunca más aparezca el popup "Esta página dice"
window.alert = function(msg) {
  mostrarAlertaModal(msg);
};

/* ─── TOAST DE NOTIFICACIÓN FLOTANTE ─── */
function mostrarToastLive(mensaje) {
  let toast = document.getElementById('toast-live-notif');
  if (!toast) {
    toast = document.createElement('div');
    toast.id = 'toast-live-notif';
    toast.className = 'toast-live-edit';
    document.body.appendChild(toast);
  }
  toast.innerHTML = `
    <svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="#22c55e" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg>
    <span>${mensaje}</span>
  `;
  toast.style.display = 'flex';
  clearTimeout(toast._timeout);
  toast._timeout = setTimeout(() => {
    toast.style.display = 'none';
  }, 4000);
}

/* ─── SINCRONIZACIÓN CON EL SERVIDOR EN LÍNEA ─── */
let _timerSyncSilencioso = null;

function iniciarSincronizacionAutomatica() {
  if (_timerSyncSilencioso) clearInterval(_timerSyncSilencioso);
  _timerSyncSilencioso = setInterval(async () => {
    try {
      // No sobrescribir mientras el usuario está editando un texto en vivo o acaba de guardar algo hace menos de 12s
      if (elementoEditandoActivo) return;
      if (_ultimaEdicionLocalTimestamp && (Date.now() - _ultimaEdicionLocalTimestamp < 12000)) return;
      const url = obtenerGoogleSheetURL();
      if (!url) return;
      const fetchUrl = url + (url.includes('?') ? '&' : '?') + '_t=' + Date.now();
      const resp = await fetch(fetchUrl);
      const json = await resp.json();
      if (json && json.status === 'success' && json.data) {
        if (!elementoEditandoActivo && (!_ultimaEdicionLocalTimestamp || (Date.now() - _ultimaEdicionLocalTimestamp >= 12000))) {
          aplicarDatosGoogleSheets(json.data);
        }
      }
    } catch (e) {
      // Sincronización silenciosa en segundo plano
    }
  }, 25000); // Cada 25 segundos
}

async function sincronizarConGoogleSheetsManual() {
  const iconLive = document.getElementById('iconSyncLive');
  const iconAdmin = document.getElementById('iconSyncAdmin');
  const lblLive = document.getElementById('lblSyncLiveSheet');
  const lblAdmin = document.getElementById('lblSyncAdmin');

  if (iconLive) iconLive.classList.add('spinning-icon');
  if (iconAdmin) iconAdmin.classList.add('spinning-icon');
  if (lblLive) lblLive.textContent = 'Sincronizando...';
  if (lblAdmin) lblAdmin.textContent = 'Sincronizando...';

  try {
    const url = obtenerGoogleSheetURL();
    if (!url) {
      mostrarAlertaModal('Primero debes configurar la URL de conexión en la pestaña de Configuración.', 'Conexión Requerida', 'warning');
      return;
    }

    // Si hay una edición en vivo abierta sin guardar, guardarla primero automáticamente
    if (elementoEditandoActivo) {
      const todosT = [
        ...(typeof TARGETS_EDICION_DIRECTOR !== 'undefined' ? TARGETS_EDICION_DIRECTOR : []),
        ...(typeof TARGETS_SECCIONES_DIRECTAS !== 'undefined' ? TARGETS_SECCIONES_DIRECTAS : [])
      ];
      const tCfg = todosT.find(item => item.id === elementoEditandoActivo);
      if (tCfg) {
        await guardarEdicionEnVivo(tCfg.id, tCfg.key, tCfg.title || 'Texto');
      }
    }

    // PASO 1 (PUSH): Si el usuario tiene sesión activa, enviar todos los cambios locales a Google Sheets
    const session = getSession();
    const esDirector = session && (session.role === 'director' || session.role === 'admin' || session.role === 'comision' || session.role === 'docente' || session.loggedIn === true);
    if (esDirector) {
      if (lblLive) lblLive.textContent = 'Enviando cambios...';
      if (lblAdmin) lblAdmin.textContent = 'Enviando cambios...';

      // 1.1 Sincronizar Horarios y combinaciones actuales
      const hMatriz = getSedeLsData('cea_horarios_matriz', HORARIOS_MATRIZ_DEFAULT);
      const hMerges = getSedeLsData('cea_horarios_merges', {});
      await enviarGoogleSheet({
        action: 'guardar-horarios-matriz',
        sede: typeof getHorarioSedeActiveKey === 'function' ? getHorarioSedeActiveKey() : 'central',
        horariosMatriz: hMatriz,
        horariosMerges: hMerges
      });

      // 1.2 Sincronizar Textos vivos, Director y Configuración Global de Diseño/Colores/Horarios
      const textosVivos = lsGet('cea_textos_vivos', {});
      const textosDir = lsGet('cea_textos_director', {});
      const contenido = lsGet('cea_contenido', CONTENIDO_DEFAULT);
      const hAtencion = lsGet('cea_horarios_atencion', {});
      const dClase = lsGet('cea_dias_clase', {});
      const fInsc = lsGet('cea_fechas_limite_inscripcion', {});
      const cfgGlobalJson = JSON.stringify(empaquetarConfiguracionGlobalCEA());
      const gestorStateJson = JSON.stringify(lsGet('cea_gestor_app_state', {}));

      const payloadTextos = {
        action: 'guardar-textos',
        bienvenida_texto: contenido.bienvenida || '',
        bienvenida_titulo: contenido.bienvenida_titulo || '',
        hero_titulo: contenido.hero_titulo || '',
        hero_subtitulo: contenido.hero_subtitulo || '',
        oferta_desc: contenido.oferta_desc || '',
        humanistica_texto: contenido.humanistica || '',
        tecnica_texto: contenido.tecnica || '',
        horarios_atencion_dia_hum: hAtencion.diaHum || '',
        horarios_atencion_hora_hum: hAtencion.horaHum || '',
        horarios_atencion_dia_tec: hAtencion.diaTec || '',
        horarios_atencion_hora_tec: hAtencion.horaTec || '',
        dias_clase_hum: dClase.hum || '',
        dias_clase_tec: dClase.tec || '',
        insc_gestion: fInsc.gestion || '',
        insc_sem1_inicio: fInsc.semestre1_inicio || '',
        insc_sem1_fin: fInsc.semestre1_fin || '',
        insc_sem1_clases: fInsc.semestre1_clases || '',
        insc_sem2_inicio: fInsc.semestre2_inicio || '',
        insc_sem2_fin: fInsc.semestre2_fin || '',
        insc_sem2_clases: fInsc.semestre2_clases || '',
        config_global_cea_json: cfgGlobalJson,
        gestor_app_state_json: gestorStateJson,
        horario_paleta_colores: lsGet('cea_horario_paleta_colores', 'multicolor'),
        bth_dias_activos_json: JSON.stringify(getSedeLsData('cea_bth_dias_activos', ['Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes'])),
        tec_dias_activos_json: JSON.stringify(getSedeLsData('cea_tec_dias_activos', ['Miércoles', 'Jueves', 'Viernes', 'Sábado'])),
        hum_modo_dia_json: JSON.stringify(lsGet('cea_hum_modo_dia', {})),
        tec_modo_dia_json: JSON.stringify(lsGet('cea_tec_modo_dia', {})),
        bth_cursos_por_dia_json: JSON.stringify(getSedeLsData('cea_bth_cursos_por_dia', {})),
        ...textosDir,
        ...textosVivos
      };
      await enviarGoogleSheet(payloadTextos);

      // 1.3 Sincronizar Documentos Oficiales Dinámicos
      const docs = lsGet('cea_documentos_dinamicos', []);
      if (docs && docs.length > 0) {
        await enviarGoogleSheet({
          action: 'guardar-documentos-dinamicos',
          documentos: docs.map(d => ({
            ...d,
            descripcion: d.desc || d.descripcion || '',
            enlace: d.url || d.enlace || '#'
          }))
        });
      }

      // 1.4 Sincronizar Carreras y Docentes si existen
      const areasTec = lsGet('cea_areas_tec', []);
      if (areasTec && areasTec.length > 0) {
        await enviarGoogleSheet({
          action: 'guardar-carreras',
          carreras: areasTec
        });
      }
      const docentes = lsGet('cea_docentes', {});
      if (docentes && Object.keys(docentes).length > 0) {
        await enviarGoogleSheet({
          action: 'guardar-docentes',
          docentes: docentes
        });
      }

      // 1.5 Sincronizar Documentos de Especialidades y Materias a Google Sheets
      try {
        const todasClaves = Object.keys(localStorage || {});
        for (let k of todasClaves) {
          if (k.startsWith('cea_doc_niveles_')) {
            const carrK = k.replace('cea_doc_niveles_', '');
            const docList = lsGet(k, null);
            if (carrK && Array.isArray(docList) && docList.length > 0) {
              await enviarGoogleSheet({
                action: 'guardar-doc-niveles',
                carreraKey: carrK,
                docs: docList
              });
            }
          }
        }
      } catch (eDocSync) {}

      // Dar tiempo a Google Apps Script para terminar de escribir antes de hacer el GET
      await new Promise(r => setTimeout(r, 1500));
    }

    // PASO 2 (PULL): Descargar la última versión consolidada de Google Sheets con timestamp anti-caché
    if (lblLive) lblLive.textContent = 'Recibiendo datos...';
    if (lblAdmin) lblAdmin.textContent = 'Recibiendo datos...';
    const fetchUrl = url + (url.includes('?') ? '&' : '?') + '_t=' + Date.now();
    const resp = await fetch(fetchUrl);
    const json = await resp.json();
    if (json && json.status === 'success' && json.data) {
      aplicarDatosGoogleSheets(json.data);
      mostrarToastLive('¡Sincronización completa! La página web y Google Sheets están 100% actualizados.');
      if (lblLive) lblLive.textContent = 'Sincronizado';
      if (lblAdmin) lblAdmin.textContent = 'Sincronizado';
    } else {
      mostrarToastLive('Aviso: respuesta sin datos nuevos del sistema.');
    }
  } catch (err) {
    console.error(err);
    mostrarToastLive('No se pudo conectar con el servidor (verifica tu conexión a internet o el enlace del script).');
  } finally {
    setTimeout(() => {
      if (iconLive) iconLive.classList.remove('spinning-icon');
      if (iconAdmin) iconAdmin.classList.remove('spinning-icon');
      if (lblLive && lblLive.textContent === 'Sincronizado') {
        setTimeout(() => { if (lblLive) lblLive.textContent = 'Sincronizar Datos'; }, 2500);
      } else if (lblLive) {
        lblLive.textContent = 'Sincronizar Datos';
      }
      if (lblAdmin && lblAdmin.textContent === 'Sincronizado') {
        setTimeout(() => { if (lblAdmin) lblAdmin.textContent = 'Sincronizado'; }, 2500);
      } else if (lblAdmin) {
        lblAdmin.textContent = 'Sincronizar';
      }
    }, 1200);
  }
}

