function renderFeedActividades() {
  const container = document.getElementById('actividades-feed-display');
  if (!container) return;

  let rawActividades = lsGet('cea_actividades', null);
  if (!rawActividades || !Array.isArray(rawActividades) || rawActividades.length === 0) {
    rawActividades = ACTIVIDADES_DEFAULT;
    lsSet('cea_actividades', rawActividades);
  }
  const actividades = rawActividades;
  const filtroSel = document.getElementById('filtro-act-gestion');
  const gestionFiltro = filtroSel ? filtroSel.value : '2026';

  let filtradas = actividades;
  if (gestionFiltro !== 'todos') {
    filtradas = actividades.filter(a => String(a.gestion) === String(gestionFiltro));
  }

  // Filtrado jerárquico según la pestaña activa (Todo, Técnica, Humanística) y su subfiltro
  filtradas = filtradas.filter(act => {
    if (nivelGaleriaActivo === 'todos') return true;

    const texto = `${act.titulo || ''} ${act.descripcion || ''} ${act.autor || ''} ${act.areaKey || ''} ${act.carreraKey || ''}`.toLowerCase();

    if (nivelGaleriaActivo === 'tecnica') {
      const k = (act.areaKey || act.carreraKey || '').toLowerCase();
      const esTec = k.startsWith('tec-') || texto.includes('sistem') || texto.includes('secretari') || texto.includes('belleza') || texto.includes('confecc') || texto.includes('gastronom') || texto.includes('agropec') || texto.includes('técnica') || texto.includes('tecnica');
      if (!esTec) return false;
      if (subFiltroGaleriaActivo === 'todas') return true;
      const targetSub = subFiltroGaleriaActivo.replace('tec-', '').toLowerCase();
      return k === subFiltroGaleriaActivo.toLowerCase() || texto.includes(targetSub);
    }

    if (nivelGaleriaActivo === 'humanistica') {
      const k = (act.areaKey || act.carreraKey || '').toLowerCase();
      const esHum = k.startsWith('hum-') || k.includes('bth') || texto.includes('matem') || texto.includes('social') || texto.includes('natural') || texto.includes('lengua') || texto.includes('bth') || texto.includes('humaníst') || texto.includes('humanist') || texto.includes('dirección') || texto.includes('direccion');
      if (!esHum) return false;
      if (subFiltroGaleriaActivo === 'todas') return true;
      const targetSub = subFiltroGaleriaActivo.replace('hum-', '').toLowerCase();
      return k === subFiltroGaleriaActivo.toLowerCase() || texto.includes(targetSub);
    }

    return true;
  });

  if (!filtradas.length) {
    container.innerHTML = `
      <div class="actividad-card" style="text-align:center">
        <p style="color:var(--text-sec)">No hay publicaciones registradas para el filtro seleccionado.</p>
      </div>`;
    return;
  }

  container.innerHTML = filtradas.map(act => {
    let mediaHTML = '';
    if (act.tipoMedia === 'imagen' && act.urlMedia) {
      mediaHTML = `<div class="actividad-media"><img src="${act.urlMedia}" alt="${act.titulo}" loading="lazy" /></div>`;
    } else if (act.tipoMedia === 'youtube' && act.urlMedia) {
      const embedUrl = obtenerYoutubeEmbedUrl(act.urlMedia);
      const iconYt = `<svg class="svg-icon" viewBox="0 0 24 24" width="18" height="18" fill="currentColor"><path d="M23.498 6.186a3.016 3.016 0 0 0-2.122-2.136C19.505 3.545 12 3.545 12 3.545s-7.505 0-9.377.505A3.017 3.017 0 0 0 .502 6.186C0 8.07 0 12 0 12s0 3.93.502 5.814a3.016 3.016 0 0 0 2.122 2.136c1.871.505 9.376.505 9.376.505s7.505 0 9.377-.505a3.015 3.015 0 0 0 2.122-2.136C24 15.93 24 12 0 12s0-3.93-.502-5.814zM9.545 15.568V8.432L15.818 12l-6.273 3.568z"/></svg>`;
      mediaHTML = `
        <div class="actividad-media">
          ${embedUrl ? `<div class="actividad-media-video"><iframe src="${embedUrl}" title="${act.titulo || 'Video YouTube'}" allowfullscreen referrerpolicy="strict-origin-when-cross-origin" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"></iframe></div>` : ''}
          <div style="margin-top:8px">
            <a href="${act.urlMedia}" target="_blank" rel="noopener" class="btn-download" style="background:#cc0000;color:#fff;display:inline-flex;align-items:center;gap:6px;padding:8px 14px;border-radius:6px;text-decoration:none;font-weight:bold;font-size:0.85rem">${iconYt} Abrir y Ver Video directamente en YouTube</a>
          </div>
        </div>`;
    } else if (act.tipoMedia === 'tiktok' && act.urlMedia) {
      const iconTt = `<svg class="svg-icon" viewBox="0 0 24 24" width="18" height="18" fill="currentColor"><path d="M12.525.02c1.31-.02 2.61-.01 3.91-.02.08 1.53.63 3.09 1.75 4.17 1.12 1.11 2.7 1.62 4.24 1.79v4.03c-1.44-.05-2.89-.35-4.2-.97-.57-.26-1.1-.59-1.62-.96v8.4c.02 1.68-.45 3.39-1.41 4.77-1.42 2.05-3.83 3.29-6.33 3.23-2.58-.02-5.01-1.39-6.36-3.58-1.37-2.22-1.4-5.06-.06-7.3 1.3-2.2 3.67-3.6 6.22-3.62.46.01.92.06 1.37.16v4.11c-.42-.12-.87-.16-1.31-.13-1.2.06-2.34.69-2.97 1.73-.64 1.05-.63 2.41.01 3.46.65 1.03 1.83 1.62 3.06 1.52 1.25-.07 2.37-.8 2.87-1.95.27-.6.39-1.26.38-1.92V.02z"/></svg>`;
      mediaHTML = `
        <div class="actividad-media">
          <a href="${act.urlMedia}" target="_blank" rel="noopener" class="btn-tiktok-link" style="display:inline-flex;align-items:center;gap:6px">
            ${iconTt} Ver Video en TikTok
          </a>
        </div>`;
    }

    const iconCal = `<svg class="svg-icon" viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor"><rect x="3" y="4" width="18" height="18" rx="2" ry="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>`;

    // Acciones de edición y eliminación: Director puede todo, Docente solo su propia área
    const session = lsGet('cea_session', null);
    const esDirector = session && (session.role === 'director' || session.role === 'admin');
    const esDocente = session && session.role === 'docente';
    const puedeGestionarAct = esDirector || (esDocente && session.areaKey && (act.areaKey === session.areaKey || act.carreraKey === session.areaKey));

    let authActionsHTML = '';
    if (puedeGestionarAct) {
      authActionsHTML = `
        <div style="display:flex;gap:8px;justify-content:flex-end;margin-top:12px;border-top:1px dashed var(--border-col);padding-top:10px">
          <button type="button" onclick="abrirModalEditarActividad('${act.id}')" style="display:inline-flex;align-items:center;gap:6px;background:#2563eb;color:#ffffff;border:none;padding:6px 12px;border-radius:6px;font-size:0.80rem;font-weight:700;cursor:pointer;transition:background 0.2s" title="Editar publicación">
            <svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2.4"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
            <span>Editar</span>
          </button>
          <button type="button" onclick="eliminarActividad('${act.id}')" style="display:inline-flex;align-items:center;gap:6px;background:#dc2626;color:#ffffff;border:none;padding:6px 12px;border-radius:6px;font-size:0.80rem;font-weight:700;cursor:pointer;transition:background 0.2s" title="Eliminar publicación">
            <svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2.4"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>
            <span>Eliminar</span>
          </button>
        </div>`;
    }

    const fechaLimpia = formatearSoloFechaUniversal(act.fecha || (act.mes + ' ' + act.gestion));

    return `
      <div class="actividad-card">
        <div class="actividad-header">
          <h3 class="actividad-titulo">${escapeHTML(act.titulo || '')}</h3>
          <div class="actividad-meta">
            <span class="actividad-badge-fecha">${iconCal} ${fechaLimpia}</span>
          </div>
        </div>
        <p class="actividad-desc">${escapeHTML(act.descripcion || '')}</p>
        ${mediaHTML}
        ${authActionsHTML}
      </div>`;
  }).join('');
}

