async function eliminarActividad(actId) {
  const session = getAdminSession();
  const esDirector = session && (session.role === 'admin' || session.role === 'director');
  const esDocente = session && session.role === 'docente';
  let actividades = lsGet('cea_actividades', ACTIVIDADES_DEFAULT);
  const act = actividades.find(a => a.id === actId);
  if (!act) return;

  if (!esDirector && (!esDocente || act.areaKey !== session.areaKey)) {
    mostrarToast('No tienes permisos para eliminar publicaciones de otra área', 'error');
    return;
  }

  const ok = await mostrarConfirmModal('¿Estás seguro de que deseas eliminar esta publicación y actividad?', 'Eliminar Publicación', 'Eliminar', true);
  if (!ok) return;
  actividades = actividades.filter(a => a.id !== actId);
  lsSet('cea_actividades', actividades);
  renderFeedActividades();
  renderListaActividadesAdmin();
  await enviarGoogleSheet({ action: 'eliminar-actividad', id: actId });
}

/* ─── MENÚ DESPLEGABLE EN INICIO (PORTADA, GALERÍA, ACTIVIDADES) ─── */
function toggleInicioDropdown(e) {
  if (e) {
    e.preventDefault();
    e.stopPropagation();
  }
  const dropdown = document.getElementById('inicioDropdownMenu');
  const btn = document.getElementById('nav-link-inicio');
  const container = document.getElementById('navInicioContainer');
  if (!dropdown) return;

  const currentHash = (window.location.hash || '').toLowerCase();
  const scrollY = window.scrollY || window.pageYOffset || 0;
  // Si el usuario está en otra sección (ej. Horarios) o scrolleado hacia abajo,
  // el primer clic lo lleva a Inicio limpiamente sin abrir el menú desplegable
  const estaFueraDeInicio = (scrollY > 250) || (currentHash && currentHash !== '#inicio' && currentHash !== '#');

  if (estaFueraDeInicio) {
    cerrarInicioDropdown();
    window.location.hash = '#inicio';
    const secInicio = document.getElementById('inicio');
    if (secInicio) {
      secInicio.scrollIntoView({ behavior: 'smooth' });
    } else {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
    document.querySelectorAll('.nav-main-item').forEach(item => item.classList.remove('active'));
    if (btn) btn.classList.add('active');
    return;
  }

  // Si ya está en Inicio (o es el segundo clic en Inicio), alternamos el menú desplegable
  const estaAbierto = dropdown.classList.contains('activo');
  if (estaAbierto) {
    cerrarInicioDropdown();
  } else {
    dropdown.style.display = 'flex';
    dropdown.classList.add('activo');
    if (btn) {
      btn.classList.add('open');
      btn.setAttribute('aria-expanded', 'true');
    }
    if (container) container.classList.add('open');
  }
}

function cerrarInicioDropdown() {
  const dropdown = document.getElementById('inicioDropdownMenu');
  const btn = document.getElementById('nav-link-inicio');
  const container = document.getElementById('navInicioContainer');
  if (dropdown) {
    dropdown.classList.remove('activo');
    dropdown.style.display = 'none';
  }
  if (btn) {
    btn.classList.remove('open');
    btn.setAttribute('aria-expanded', 'false');
  }
  if (container) container.classList.remove('open');
}

document.addEventListener('click', function(e) {
  const navInicioContainer = document.getElementById('navInicioContainer');
  if (navInicioContainer && !navInicioContainer.contains(e.target)) {
    cerrarInicioDropdown();
  }
});

/* ─── MENÚ HAMBURGUESA MÓVIL ─── */
function toggleHamburgerMenu() {
  const dropdown = document.getElementById('hamburgerDropdown');
  const btn = document.getElementById('btnHamburger');
  if (dropdown) {
    dropdown.classList.toggle('activo');
    if (btn) btn.classList.toggle('abierto');
  }
}

function closeHamburgerMenu() {
  const dropdown = document.getElementById('hamburgerDropdown');
  const btn = document.getElementById('btnHamburger');
  if (dropdown) dropdown.classList.remove('activo');
  if (btn) btn.classList.remove('abierto');
}

document.addEventListener('click', function(e) {
  const container = document.getElementById('navMoreContainer');
  if (container && !container.contains(e.target)) {
    closeHamburgerMenu();
  }
});

