/* ─── RESTAURACIÓN DE TEXTOS EN VIVO ─── */
function cargarTextosEnVivoLocales() {
  const textosVivos = lsGet('cea_textos_vivos', {});
  const textosDir = lsGet('cea_textos_director', {});
  const mapaUnificado = Object.assign({}, textosDir, textosVivos);

  const targets = [
    ...(typeof TARGETS_EDICION_DIRECTOR !== 'undefined' ? TARGETS_EDICION_DIRECTOR : []),
    ...(typeof TARGETS_SECCIONES_DIRECTAS !== 'undefined' ? TARGETS_SECCIONES_DIRECTAS : [])
  ];

  targets.forEach(item => {
    if (mapaUnificado[item.key] !== undefined && mapaUnificado[item.key] !== '') {
      const el = document.getElementById(item.id);
      if (el) {
        if (item.type === 'html') el.innerHTML = mapaUnificado[item.key];
        else el.textContent = mapaUnificado[item.key];
      }
    }
  });
}

/* ─── PREGUNTAS FRECUENTES (FAQ ACCORDION) ─── */
function toggleFaqItem(btn) {
  if (!btn) return;
  const item = btn.closest('.faq-item');
  if (!item) return;
  const isActivo = item.classList.contains('active');

  // Cerrar todos los items del acordeón
  const todos = document.querySelectorAll('.faq-accordion-container .faq-item');
  todos.forEach(it => {
    it.classList.remove('active');
    const icon = it.querySelector('.faq-icon');
    if (icon) icon.textContent = '+';
  });

  // Si no estaba activo, abrirlo
  if (!isActivo) {
    item.classList.add('active');
    const icon = item.querySelector('.faq-icon');
    if (icon) icon.textContent = '−';
  }
}

/* ─── FORMATO DE FECHA DE GALERÍA (Ej: 19 - dic - 2026) ─── */
function formatearFechaGaleria(fechaStr) {
  if (!fechaStr) return '';
  const meses = ['ene', 'feb', 'mar', 'abr', 'may', 'jun', 'jul', 'ago', 'sep', 'oct', 'nov', 'dic'];

  const clean = fechaStr.trim();
  if (/\d{1,2}\s*-\s*[a-z]{3}\s*-\s*\d{4}/i.test(clean)) {
    return clean.toLowerCase();
  }

  let day = '', monthIdx = -1, year = '';

  if (clean.includes('/')) {
    const parts = clean.split('/');
    if (parts.length === 3) {
      if (parts[0].length === 4) {
        year = parts[0];
        monthIdx = parseInt(parts[1], 10) - 1;
        day = parts[2].padStart(2, '0');
      } else {
        day = parts[0].padStart(2, '0');
        monthIdx = parseInt(parts[1], 10) - 1;
        year = parts[2];
      }
    }
  } else if (clean.includes('-')) {
    const parts = clean.split('-');
    if (parts.length === 3) {
      if (parts[0].length === 4) {
        year = parts[0];
        monthIdx = parseInt(parts[1], 10) - 1;
        day = parts[2].padStart(2, '0');
      } else {
        day = parts[0].padStart(2, '0');
        monthIdx = parseInt(parts[1], 10) - 1;
        year = parts[2];
      }
    }
  }

  if (day && monthIdx >= 0 && monthIdx < 12 && year) {
    return `${day} - ${meses[monthIdx]} - ${year}`;
  }

  return clean;
}

