let nivelGaleriaActivo = 'todos'; // 'todos' | 'tecnica' | 'humanistica'
let subFiltroGaleriaActivo = 'todas';

function cambiarNivelGaleria(nivel) {
  nivelGaleriaActivo = nivel;
  subFiltroGaleriaActivo = 'todas';

  const btnTodas = document.getElementById('subtab-gal-todas');
  const btnTec = document.getElementById('subtab-gal-tec');
  const btnHum = document.getElementById('subtab-gal-hum');
  if (btnTodas) btnTodas.classList.toggle('active', nivel === 'todos');
  if (btnTec) btnTec.classList.toggle('active', nivel === 'tecnica');
  if (btnHum) btnHum.classList.toggle('active', nivel === 'humanistica');

  const subBar = document.getElementById('galeria-subfiltros-dinamicos');
  if (subBar) {
    if (nivel === 'todos') {
      subBar.style.display = 'none';
      subBar.innerHTML = '';
    } else if (nivel === 'tecnica') {
      subBar.style.display = 'flex';
      const areasTec = lsGet('cea_areas_tec', AREAS_TEC_DEFAULT);
      let html = `<span class="gal-subfiltro-label">Carrera Técnica:</span>`;
      html += `<button type="button" class="gal-subfiltro-pill active" onclick="filtrarSubCategoriaGaleria('todas', this)">Todas las Carreras</button>`;
      areasTec.forEach(c => {
        html += `<button type="button" class="gal-subfiltro-pill" onclick="filtrarSubCategoriaGaleria('${c.key}', this)">${c.nombre}</button>`;
      });
      subBar.innerHTML = html;
    } else if (nivel === 'humanistica') {
      subBar.style.display = 'flex';
      const materiasHum = [
        { key: 'hum-cn', nombre: 'Ciencias Naturales' },
        { key: 'hum-mat', nombre: 'Matemática' },
        { key: 'hum-cs', nombre: 'Ciencias Sociales' },
        { key: 'hum-len', nombre: 'Comunicación y Lenguajes' },
        { key: 'bth-agro', nombre: 'BTH Agropecuaria' }
      ];
      let html = `<span class="gal-subfiltro-label">Materia Humanística:</span>`;
      html += `<button type="button" class="gal-subfiltro-pill active" onclick="filtrarSubCategoriaGaleria('todas', this)">Todas las Materias</button>`;
      materiasHum.forEach(m => {
        html += `<button type="button" class="gal-subfiltro-pill" onclick="filtrarSubCategoriaGaleria('${m.key}', this)">${m.nombre}</button>`;
      });
      subBar.innerHTML = html;
    }
  }

  cargarGaleriaFotos();
  if (typeof cargarActividadesFeed === 'function') {
    cargarActividadesFeed();
  }
}

function filtrarSubCategoriaGaleria(subCat, btnEl) {
  subFiltroGaleriaActivo = subCat;
  if (btnEl) {
    const pills = document.querySelectorAll('.gal-subfiltro-pill');
    pills.forEach(p => p.classList.remove('active'));
    btnEl.classList.add('active');
  }
  cargarGaleriaFotos();
  if (typeof cargarActividadesFeed === 'function') {
    cargarActividadesFeed();
  }
}

function abrirModalPublicacionDirecta() {
  const session = lsGet('cea_session', null);
  if (session && session.role === 'director') {
    window.location.hash = '#admin';
    switchAdminSubTab('noticias');
    setTimeout(() => {
      const inp = document.getElementById('act-titulo');
      if (inp) {
        inp.focus();
        inp.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }
    }, 250);
  } else if (session && session.role === 'docente') {
    mostrarPanelDocente(session.areaKey);
    setTimeout(() => {
      const inp = document.getElementById('doc-act-titulo');
      if (inp) {
        inp.focus();
        inp.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }
    }, 250);
  } else {
    window.location.hash = '#admin';
    setTimeout(() => {
      const inp = document.getElementById('admin-usuario');
      if (inp) inp.focus();
    }, 200);
  }
}

function cargarGaleriaFotos() {
  const session = lsGet('cea_session', null);
  const isDirector = session && session.role === 'director';
  const isDocente = session && session.role === 'docente';

  const authBtnArea = document.getElementById('galeria-auth-btn-area');
  if (authBtnArea) {
    authBtnArea.style.display = (isDirector || isDocente) ? 'block' : 'none';
  }

  let rawFotos = lsGet('cea_galeria_fotos', null);
  if (!rawFotos || !Array.isArray(rawFotos) || rawFotos.length === 0) {
    rawFotos = GALERIA_FOTOS_DEFAULT;
    lsSet('cea_galeria_fotos', rawFotos);
  }
  const fotos = rawFotos;

  // Filtrado jerárquico por nivel y subcategoría
  const fotosFiltradas = fotos.filter(f => {
    if (nivelGaleriaActivo === 'todos') return true;

    if (nivelGaleriaActivo === 'tecnica') {
      const k = (f.carreraKey || '').toLowerCase();
      const nom = (f.carreraNombre || '').toLowerCase();
      const esTec = k.startsWith('tec-') || nom.includes('sistem') || nom.includes('secretari') || nom.includes('belleza') || nom.includes('confecc') || nom.includes('gastronom') || nom.includes('agropec');
      if (!esTec) return false;
      if (subFiltroGaleriaActivo === 'todas') return true;
      return k === subFiltroGaleriaActivo || nom.includes(subFiltroGaleriaActivo.replace('tec-', ''));
    }

    if (nivelGaleriaActivo === 'humanistica') {
      const k = (f.carreraKey || '').toLowerCase();
      const nom = (f.carreraNombre || '').toLowerCase();
      const esHum = k.startsWith('hum-') || k.includes('bth') || nom.includes('matem') || nom.includes('social') || nom.includes('natural') || nom.includes('lengua') || nom.includes('bth') || k === 'general';
      if (!esHum) return false;
      if (subFiltroGaleriaActivo === 'todas') return true;
      return k === subFiltroGaleriaActivo || nom.includes(subFiltroGaleriaActivo.replace('hum-', ''));
    }

    return true;
  });

  const grid = document.getElementById('galeria-fotos-grid');
  if (!grid) return;

  if (fotosFiltradas.length === 0) {
    grid.innerHTML = `
      <div class="galeria-empty" style="grid-column: 1 / -1; text-align: center; padding: 40px 20px; background: var(--bg-card); border-radius: 12px; border: 2px dashed var(--border-col);">
        <svg viewBox="0 0 24 24" width="48" height="48" fill="none" stroke="currentColor" stroke-width="1.5" style="color: var(--text-muted); margin-bottom: 12px;"><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><polyline points="21 15 16 10 5 21"/></svg>
        <p style="font-weight: 700; color: var(--text-main); margin-bottom: 6px;">No hay fotografías registradas en esta especialidad aún.</p>
        <p style="font-size: 0.88rem; color: var(--text-muted); margin-bottom: 0;">${(isDirector || isDocente) ? 'Presiona el botón "Subir Fotografía" arriba para agregar una nueva.' : 'Pronto compartiremos más capturas de talleres y actividades formativas.'}</p>
      </div>
    `;
    return;
  }

  grid.innerHTML = fotosFiltradas.map(foto => {
    let puedeEditar = false;
    let puedeEliminar = false;
    if (isDirector) {
      puedeEditar = true;
      puedeEliminar = true;
    } else if (isDocente) {
      const docAreaKey = session.areaKey;
      if (foto.carreraKey === docAreaKey || (foto.autor && foto.autor.includes(session.name))) {
        puedeEditar = true;
        puedeEliminar = true;
      }
    }

    const editBtnHtml = puedeEditar ? `
      <button type="button" class="galeria-edit-btn" title="Editar fotografía" onclick="event.stopPropagation(); abrirModalEditarFotoGaleria('${foto.id}')" aria-label="Editar fotografía">
        <svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2.4"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
      </button>
    ` : '';

    const deleteBtnHtml = puedeEliminar ? `
      <button type="button" class="galeria-del-btn" title="Eliminar fotografía" onclick="event.stopPropagation(); eliminarFotoGaleria('${foto.id}')" aria-label="Eliminar fotografía">
        <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.2"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/><line x1="10" y1="11" x2="10" y2="17"/><line x1="14" y1="11" x2="14" y2="17"/></svg>
      </button>
    ` : '';

    const encTitulo = (foto.titulo || '').replace(/'/g, "\\'").replace(/"/g, '&quot;');
    const carreraTexto = obtenerEtiquetaCarreraGaleria(foto);
    const fechaLimpia = formatearSoloFechaUniversal(foto.fecha || '');
    const encCarrera = carreraTexto.replace(/'/g, "\\'").replace(/"/g, '&quot;');

    return `
      <div class="galeria-card" onclick="abrirLightboxFoto('${foto.urlFoto}', '${encTitulo}', '', '${fechaLimpia}', '${encCarrera}')">
        <div class="galeria-img-wrap">
          <img src="${foto.urlFoto}" alt="${foto.titulo}" loading="lazy" onerror="this.onerror=null;this.src='FOTOGRAFIA DEL CEA .jpeg';" />
          <div class="galeria-zoom-hint" title="Ampliar fotografía">
            <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2.5"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/><line x1="11" y1="8" x2="11" y2="14"/><line x1="8" y1="11" x2="14" y2="11"/></svg>
          </div>
          ${editBtnHtml}
          ${deleteBtnHtml}
        </div>
        <div class="galeria-info" style="padding:14px 16px;">
          <h4 style="margin:0 0 8px 0; font-size:0.95rem; font-weight:800; color:var(--text-main); line-height:1.38;">${escapeHTML(foto.titulo || '')}</h4>
          <div style="display:flex; justify-content:space-between; align-items:center; font-size:0.82rem; color:var(--text-sec); margin-top:10px; border-top:1px dashed var(--border-col); padding-top:8px;">
            <span style="font-weight:800; color:var(--verde-dark); font-size:0.84rem;">${escapeHTML(carreraTexto)}</span>
            <span style="font-weight:700; color:#64748b; font-size:0.80rem;">${fechaLimpia}</span>
          </div>
        </div>
      </div>
    `;
  }).join('');
}

function filtrarGaleria(carreraKey, btn) {
  subFiltroGaleriaActivo = carreraKey;
  cargarGaleriaFotos();
}

function abrirModalSubirFotoGaleria() {
  const session = lsGet('cea_session', null);
  if (!session || (session.role !== 'director' && session.role !== 'docente')) {
    mostrarAlertaModal('Debes iniciar sesión como Director(a) o Docente para subir fotos a la galería.', 'Acceso Restringido', 'warning');
    window.location.hash = '#administracion';
    return;
  }

  const modal = document.getElementById('modalSubirFotoGaleria');
  if (!modal) return;

  const titAccion = document.getElementById('modalGaleriaTituloAccion');
  const selCarrera = document.getElementById('gal-foto-carrera');
  const areasTec = lsGet('cea_areas_tec', AREAS_TEC_DEFAULT);

  if (selCarrera) {
    if (session.role === 'director') {
      if (titAccion) titAccion.innerHTML = `<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><polyline points="21 15 16 10 5 21"/></svg> Subir Fotografía (Director)`;
      let optionsHtml = `<option value="general">General / Institucional</option>`;
      areasTec.forEach(c => {
        optionsHtml += `<option value="${c.key}">${c.nombre}</option>`;
      });
      selCarrera.innerHTML = optionsHtml;
      selCarrera.disabled = false;
    } else if (session.role === 'docente') {
      const areaKey = session.areaKey;
      const carrAsoc = areasTec.find(a => a.key === areaKey);
      const carrNom = carrAsoc ? carrAsoc.nombre : areaKey;
      if (titAccion) titAccion.innerHTML = `<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><polyline points="21 15 16 10 5 21"/></svg> Subir Fotografía - ${carrNom}`;
      selCarrera.innerHTML = `<option value="${areaKey}" selected>${carrNom}</option>`;
      selCarrera.disabled = true;
    }
  }

  const inpId = document.getElementById('gal-foto-id');
  if (inpId) inpId.value = '';
  const inpFechaOrig = document.getElementById('gal-foto-fecha-original');
  if (inpFechaOrig) inpFechaOrig.value = '';
  const inpAutor = document.getElementById('gal-foto-autor');
  if (inpAutor) inpAutor.value = '';

  const btnSubmit = document.getElementById('btn-submit-foto-galeria');
  if (btnSubmit) btnSubmit.textContent = 'Subir Fotografía';

  document.getElementById('gal-foto-titulo').value = '';
  document.getElementById('gal-foto-url').value = '';
  const fileInp = document.getElementById('gal-foto-file');
  if (fileInp) fileInp.value = '';
  delete window._galeriaFotoBase64;
  const fnSpan = document.getElementById('gal-foto-filename');
  if (fnSpan) fnSpan.textContent = '';
  const prevBox = document.getElementById('gal-foto-preview-box');
  if (prevBox) prevBox.style.display = 'none';
  const msgEl = document.getElementById('msg-galeria-modal');
  if (msgEl) { msgEl.className = 'form-msg'; msgEl.textContent = ''; }

  modal.style.display = 'flex';
}

function abrirModalEditarFotoGaleria(fotoId) {
  const session = lsGet('cea_session', null);
  if (!session || (session.role !== 'director' && session.role !== 'docente')) {
    mostrarAlertaModal('Debes iniciar sesión como Director(a) o Docente para editar fotos de la galería.', 'Acceso Restringido', 'warning');
    return;
  }

  const fotos = lsGet('cea_galeria_fotos', GALERIA_FOTOS_DEFAULT);
  const foto = fotos.find(f => f.id === fotoId);
  if (!foto) {
    mostrarToastLive('No se encontró la fotografía a editar.');
    return;
  }

  const modal = document.getElementById('modalSubirFotoGaleria');
  if (!modal) return;

  const titAccion = document.getElementById('modalGaleriaTituloAccion');
  const selCarrera = document.getElementById('gal-foto-carrera');
  const areasTec = lsGet('cea_areas_tec', AREAS_TEC_DEFAULT);

  if (selCarrera) {
    let optionsHtml = `<option value="general">General / Institucional</option>`;
    areasTec.forEach(c => {
      optionsHtml += `<option value="${c.key}">${c.nombre}</option>`;
    });
    selCarrera.innerHTML = optionsHtml;
    selCarrera.value = foto.carreraKey || 'general';
    selCarrera.disabled = (session.role === 'docente');
  }

  if (titAccion) {
    titAccion.innerHTML = `<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg> Editar Fotografía de Galería`;
  }

  const inpId = document.getElementById('gal-foto-id');
  if (inpId) inpId.value = foto.id;
  const inpFechaOrig = document.getElementById('gal-foto-fecha-original');
  if (inpFechaOrig) inpFechaOrig.value = foto.fecha || '';
  const inpAutor = document.getElementById('gal-foto-autor');
  if (inpAutor) inpAutor.value = foto.autor || '';

  document.getElementById('gal-foto-titulo').value = foto.titulo || '';
  document.getElementById('gal-foto-url').value = foto.urlFoto || '';

  const fileInp = document.getElementById('gal-foto-file');
  if (fileInp) fileInp.value = '';
  delete window._galeriaFotoBase64;
  const fnSpan = document.getElementById('gal-foto-filename');
  if (fnSpan) fnSpan.textContent = '';

  const prevBox = document.getElementById('gal-foto-preview-box');
  const prevImg = document.getElementById('gal-foto-preview-img');
  if (foto.urlFoto && prevBox && prevImg) {
    prevImg.src = foto.urlFoto;
    prevBox.style.display = 'block';
  } else if (prevBox) {
    prevBox.style.display = 'none';
  }

  const btnSubmit = document.getElementById('btn-submit-foto-galeria');
  if (btnSubmit) btnSubmit.textContent = 'Guardar Cambios';

  const msgEl = document.getElementById('msg-galeria-modal');
  if (msgEl) { msgEl.className = 'form-msg'; msgEl.textContent = ''; }

  modal.style.display = 'flex';
}

function cerrarModalSubirFotoGaleria() {
  const modal = document.getElementById('modalSubirFotoGaleria');
  if (modal) modal.style.display = 'none';
  delete window._galeriaFotoBase64;
}

async function procesarArchivoGaleria(input) {
  if (!input || !input.files || !input.files[0]) return;
  const file = input.files[0];
  const fnSpan = document.getElementById('gal-foto-filename');
  if (fnSpan) fnSpan.textContent = `Procesando: ${file.name}...`;

  let compressed = null;
  if (file.type.startsWith('image/')) {
    compressed = await comprimirImagenCanvas(file, 1280, 1280, 0.78);
  }

  if (compressed) {
    window._galeriaFotoBase64 = compressed;
    if (fnSpan) fnSpan.textContent = `Archivo optimizado: ${file.name} (${Math.round(compressed.length * 0.75 / 1024)} KB)`;
    const prevBox = document.getElementById('gal-foto-preview-box');
    const prevImg = document.getElementById('gal-foto-preview-img');
    if (prevImg) prevImg.src = compressed;
    if (prevBox) prevBox.style.display = 'block';
  } else {
    const reader = new FileReader();
    reader.onload = function(e) {
      window._galeriaFotoBase64 = e.target.result;
      if (fnSpan) fnSpan.textContent = `Archivo: ${file.name} (${Math.round(file.size / 1024)} KB)`;
      const prevBox = document.getElementById('gal-foto-preview-box');
      const prevImg = document.getElementById('gal-foto-preview-img');
      if (prevImg) prevImg.src = e.target.result;
      if (prevBox) prevBox.style.display = 'block';
    };
    reader.readAsDataURL(file);
  }
}

function previsualizarUrlGaleria(url) {
  const prevBox = document.getElementById('gal-foto-preview-box');
  const prevImg = document.getElementById('gal-foto-preview-img');
  if (url && url.startsWith('http')) {
    if (prevImg) prevImg.src = url;
    if (prevBox) prevBox.style.display = 'block';
  } else if (!window._galeriaFotoBase64 && prevBox) {
    prevBox.style.display = 'none';
  }
}

async function guardarFotoGaleria() {
  const session = lsGet('cea_session', null);
  if (!session) return;

  const idExistente = (document.getElementById('gal-foto-id')?.value || '').trim();
  const fechaOriginal = (document.getElementById('gal-foto-fecha-original')?.value || '').trim();
  const autorExistente = (document.getElementById('gal-foto-autor')?.value || '').trim();

  const titulo = (document.getElementById('gal-foto-titulo')?.value || '').trim();
  const selCarrera = document.getElementById('gal-foto-carrera');
  const carreraKey = (session.role === 'docente') ? session.areaKey : (selCarrera?.value || 'general');

  const areasTec = lsGet('cea_areas_tec', AREAS_TEC_DEFAULT);
  const carrObj = areasTec.find(a => a.key === carreraKey);
  const carreraNombre = (carreraKey === 'general') ? 'General / Institucional' : (carrObj ? carrObj.nombre : carreraKey);

  const urlInput = (document.getElementById('gal-foto-url')?.value || '').trim();
  const urlFinal = window._galeriaFotoBase64 || urlInput;

  if (!titulo) {
    mostrarMsg('msg-galeria-modal', 'Por favor ingresa un título para la fotografía.', 'error');
    return;
  }
  if (!urlFinal) {
    mostrarMsg('msg-galeria-modal', 'Por favor selecciona una imagen o introduce un enlace de foto.', 'error');
    return;
  }

  const btnSubmit = document.getElementById('btn-submit-foto-galeria');
  if (btnSubmit) {
    btnSubmit.disabled = true;
    btnSubmit.textContent = idExistente ? 'Guardando...' : 'Subiendo...';
  }

  let autor = autorExistente || 'Dirección CEA';
  if (!autorExistente && session.role === 'docente') {
    const docentes = lsGet('cea_docentes', DOCENTES_DEFAULT);
    const nomDoc = docentes[session.areaKey] || session.name || 'Docente';
    autor = `Docente: ${nomDoc}`;
  }

  const meses = ['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
  const fechaActual = new Date();
  const mesActual = meses[fechaActual.getMonth()];
  const gestionActual = String(fechaActual.getFullYear());
  const fechaStr = fechaOriginal || fechaActual.toLocaleDateString('es-BO'); // NUNCA ALTERA LA FECHA ORIGINAL SI SE EDITA

  const fotoId = idExistente || ('foto-' + Date.now());
  const fotoObj = {
    id: fotoId,
    gestion: gestionActual,
    mes: mesActual,
    fecha: fechaStr,
    titulo: titulo,
    carreraKey: carreraKey,
    carreraNombre: carreraNombre,
    urlFoto: urlFinal,
    autor: autor
  };

  // 1. Guardar localmente
  let fotos = lsGet('cea_galeria_fotos', GALERIA_FOTOS_DEFAULT);
  const idx = fotos.findIndex(f => f.id === fotoId);
  if (idx >= 0) {
    fotos[idx] = fotoObj;
  } else {
    fotos.unshift(fotoObj);
  }
  lsSet('cea_galeria_fotos', fotos);
  cargarGaleriaFotos();

  mostrarToastLive(idExistente ? 'Fotografía actualizada correctamente' : 'Fotografía agregada a la galería');
  cerrarModalSubirFotoGaleria();

  if (btnSubmit) {
    btnSubmit.disabled = false;
    btnSubmit.textContent = idExistente ? 'Guardar Cambios' : 'Subir Fotografía';
  }

  // 2. Enviar a Google Sheets
  try {
    const resp = await enviarGoogleSheet({
      action: 'guardar-foto-galeria',
      foto: fotoObj
    });
    if (resp && resp.driveUrl && resp.driveUrl !== urlFinal) {
      fotos = lsGet('cea_galeria_fotos', []);
      const f = fotos.find(x => x.id === fotoId);
      if (f) {
        f.urlFoto = resp.driveUrl;
        lsSet('cea_galeria_fotos', fotos);
        cargarGaleriaFotos();
      }
    }
  } catch (err) {
    console.error('Error enviando foto a Google Sheets:', err);
  }
}

async function eliminarFotoGaleria(fotoId) {
  const ok = await mostrarConfirmModal('¿Estás seguro de que deseas eliminar esta fotografía de la galería institucional?', 'Eliminar Fotografía', 'Eliminar', true);
  if (!ok) return;

  let fotos = lsGet('cea_galeria_fotos', GALERIA_FOTOS_DEFAULT);
  fotos = fotos.filter(f => f.id !== fotoId);
  lsSet('cea_galeria_fotos', fotos);
  cargarGaleriaFotos();
  mostrarToastLive('Fotografía eliminada');

  await enviarGoogleSheet({
    action: 'eliminar-foto-galeria',
    id: fotoId
  });
}

function abrirLightboxFoto(url, encTitulo, encAutor, fecha, encCarrera) {
  const modal = document.getElementById('modalLightboxFoto');
  if (!modal) return;

  const img = document.getElementById('lightbox-img');
  const tit = document.getElementById('lightbox-titulo');
  const meta = document.getElementById('lightbox-meta');

  if (img) img.src = url;
  if (tit) tit.textContent = encTitulo;
  if (meta) meta.textContent = `${encCarrera} • ${fecha}`;

  modal.style.display = 'flex';
}

function cerrarLightboxFoto() {
  const modal = document.getElementById('modalLightboxFoto');
  if (modal) modal.style.display = 'none';
}

/* ─── OFERTA ACADÉMICA INTERACTIVA ─── */
function switchOfertaTab(tipo) {
  const btnHum = document.getElementById('btn-oferta-hum');
  const btnTec = document.getElementById('btn-oferta-tec');
  const panelHum = document.getElementById('panel-oferta-hum');
  const panelTec = document.getElementById('panel-oferta-tec');

  if (tipo === 'hum') {
    if (btnHum) btnHum.classList.add('active');
    if (btnTec) btnTec.classList.remove('active');
    if (panelHum) panelHum.style.display = 'block';
    if (panelTec) panelTec.style.display = 'none';
  } else {
    if (btnTec) btnTec.classList.add('active');
    if (btnHum) btnHum.classList.remove('active');
    if (panelTec) panelTec.style.display = 'block';
    if (panelHum) panelHum.style.display = 'none';
  }
  if (typeof renderLapicesDirectosDirector === 'function') {
    renderLapicesDirectosDirector();
  }
}

function toggleMasDetallesOferta(tipo, forceOpen = null) {
  const idDetalles = tipo === 'hum' ? 'detalles-oferta-hum' : 'detalles-oferta-tec';
  const idBtn = tipo === 'hum' ? 'btn-toggle-detalles-hum' : 'btn-toggle-detalles-tec';
  const idTxt = tipo === 'hum' ? 'txt-btn-detalles-hum' : 'txt-btn-detalles-tec';

  const detalles = document.getElementById(idDetalles);
  const btn = document.getElementById(idBtn);
  const txt = document.getElementById(idTxt);
  if (!detalles) return;

  const deberiaAbrir = forceOpen !== null ? forceOpen : (detalles.style.display === 'none' || !detalles.style.display);

  if (deberiaAbrir) {
    if (tipo === 'hum' && typeof renderSeccionHumanistica === 'function') {
      renderSeccionHumanistica();
    }
    detalles.style.display = 'block';
    if (btn) btn.classList.add('abierto');
    if (txt) txt.textContent = 'Ocultar detalles';
  } else {
    detalles.style.display = 'none';
    if (btn) btn.classList.remove('abierto');
    if (txt) txt.textContent = 'Más detalles';
  }
  if (typeof renderLapicesDirectosDirector === 'function') {
    renderLapicesDirectosDirector();
  }
}

function sincronizarHashNavegacion() {
  const hash = window.location.hash;
  if (hash === '#humanistica') {
    switchOfertaTab('hum');
  } else if (hash === '#tecnica') {
    switchOfertaTab('tec');
  } else if (hash === '#inscripcion' || hash === '#inscripciones') {
    setTimeout(() => {
      const formWrap = document.getElementById('contenedor-formulario-inscripcion');
      const estaAbierto = formWrap && formWrap.style.display === 'block';
      const el = estaAbierto ? formWrap : document.getElementById('inscripcion');
      if (el) {
        const topY = el.getBoundingClientRect().top + window.pageYOffset - 80;
        window.scrollTo({ top: Math.max(0, topY), behavior: 'smooth' });
      }
    }, 150);
  } else if (hash === '#requisitos') {
    setTimeout(() => {
      const el = document.getElementById('bloque-requisitos-integrado') || document.getElementById('requisitos');
      if (el) el.scrollIntoView({ behavior: 'smooth' });
    }, 150);
  } else if (hash === '#faq') {
    setTimeout(() => {
      const el = document.getElementById('faq');
      if (el) el.scrollIntoView({ behavior: 'smooth' });
    }, 150);
  } else if (hash === '#galeria' || hash === '#actividades') {
    if (typeof cargarGaleriaFotos === 'function') cargarGaleriaFotos();
    if (typeof renderFeedActividades === 'function') renderFeedActividades();
    setTimeout(() => {
      const targetId = hash === '#actividades' ? 'actividades-feed-display' : 'galeria';
      const el = document.getElementById(targetId);
      if (el) {
        const topY = el.getBoundingClientRect().top + window.pageYOffset - 80;
        window.scrollTo({ top: Math.max(0, topY), behavior: 'smooth' });
      }
    }, 120);
  }

  if (typeof renderLapicesDirectosDirector === 'function') {
    renderLapicesDirectosDirector();
  }
}

/* ─── MENÚ MÓVIL Y TABLET INTUITIVO ─── */
function toggleMenuMovil() {
  const drawer = document.getElementById('mobile-drawer-menu');
  if (!drawer) return;
  const estaAbierto = drawer.classList.contains('activo');
  if (estaAbierto) {
    cerrarMenuMovil();
  } else {
    abrirMenuMovil();
  }
}

function abrirMenuMovil() {
  const drawer = document.getElementById('mobile-drawer-menu');
  const btn = document.getElementById('btn-mobile-hamburger');
  if (!drawer) return;
  drawer.classList.add('activo');
  drawer.setAttribute('aria-hidden', 'false');
  if (btn) {
    btn.classList.add('activo');
    btn.setAttribute('aria-expanded', 'true');
  }
  document.body.classList.add('menu-movil-abierto');
}

function cerrarMenuMovil() {
  const drawer = document.getElementById('mobile-drawer-menu');
  const btn = document.getElementById('btn-mobile-hamburger');
  if (!drawer) return;
  drawer.classList.remove('activo');
  drawer.setAttribute('aria-hidden', 'true');
  if (btn) {
    btn.classList.remove('activo');
    btn.setAttribute('aria-expanded', 'false');
  }
  document.body.classList.remove('menu-movil-abierto');
}

function navegarDesdeMenuMovil(selector) {
  cerrarMenuMovil();
  if (!selector) return;
  window.location.hash = selector;
  setTimeout(() => {
    const el = document.querySelector(selector);
    if (el) {
      const topY = el.getBoundingClientRect().top + window.pageYOffset - 70;
      window.scrollTo({ top: Math.max(0, topY), behavior: 'smooth' });
    }
  }, 80);
}

function navegarAGaleriaDesdeMovil(e) {
  if (e && e.preventDefault) e.preventDefault();
  cerrarMenuMovil();
  navegarAGaleria(e);
}

document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape') {
    cerrarMenuMovil();
  }
});

function navegarAGaleria(e) {
  if (e && e.preventDefault) e.preventDefault();
  window.location.hash = '#galeria';
  if (typeof cargarGaleriaFotos === 'function') cargarGaleriaFotos();
  if (typeof renderFeedActividades === 'function') renderFeedActividades();
  setTimeout(() => {
    const el = document.getElementById('galeria');
    if (el) {
      const topY = el.getBoundingClientRect().top + window.pageYOffset - 80;
      window.scrollTo({ top: Math.max(0, topY), behavior: 'smooth' });
    }
  }, 80);
}

function navegarAActividades(e) {
  if (e && e.preventDefault) e.preventDefault();
  window.location.hash = '#actividades';
  if (typeof cargarGaleriaFotos === 'function') cargarGaleriaFotos();
  if (typeof renderFeedActividades === 'function') renderFeedActividades();
  setTimeout(() => {
    const el = document.getElementById('actividades-feed-display') || document.getElementById('actividades');
    if (el) {
      const topY = el.getBoundingClientRect().top + window.pageYOffset - 80;
      window.scrollTo({ top: Math.max(0, topY), behavior: 'smooth' });
    }
  }, 80);
}


function inicializarScrollSpyNavegacion() {
  const secciones = [
    { id: 'inicio', linkId: 'nav-link-inicio' },
    { id: 'oferta', linkId: 'nav-link-oferta' },
    { id: 'horarios', linkId: 'nav-link-horarios' },
    { id: 'inscripcion', linkId: 'nav-link-inscripciones' },
    { id: 'bloque-requisitos-integrado', linkId: 'nav-link-inscripciones' },
    { id: 'contacto', linkId: 'nav-link-contacto' }
  ];

  const actualizarNavActivo = () => {
    const hash = window.location.hash;
    const scrollPos = window.scrollY + 200;
    let actualId = 'inicio';

    if (hash === '#requisitos' || hash === '#inscripcion' || hash === '#inscripciones') {
      actualId = 'inscripcion';
    } else if (hash === '#oferta' || hash === '#humanistica' || hash === '#tecnica') {
      actualId = 'oferta';
    } else if (hash === '#horarios') {
      actualId = 'horarios';
    } else if (hash === '#contacto' || hash === '#faq') {
      actualId = 'contacto';
    } else if (hash === '#inicio') {
      actualId = 'inicio';
    } else {
      secciones.forEach(sec => {
        const el = document.getElementById(sec.id);
        if (el) {
          const top = el.offsetTop;
          const height = el.offsetHeight;
          if (scrollPos >= top && scrollPos < top + height) {
            actualId = (sec.id === 'bloque-requisitos-integrado') ? 'inscripcion' : sec.id;
          }
        }
      });
    }

    secciones.forEach(sec => {
      const a = document.getElementById(sec.linkId) || (sec.linkId === 'nav-link-inscripciones' ? document.getElementById('nav-link-requisitos') : null);
      if (a) {
        if (sec.id === actualId || (actualId === 'inscripcion' && sec.linkId === 'nav-link-inscripciones')) {
          a.classList.add('active');
        } else {
          a.classList.remove('active');
        }
      }
    });
  };

  window.addEventListener('scroll', actualizarNavActivo, { passive: true });
  window.addEventListener('hashchange', () => {
    setTimeout(actualizarNavActivo, 120);
  });
  actualizarNavActivo();
}

