function getKardexDocentesStorage() {
  const estaVacio = lsGet('cea_kardex_docentes_vacio', false);
  if (estaVacio) {
    const km = lsGet('cea_kardex_docentes', {});
    return (km && typeof km === 'object') ? km : {};
  }
  let kardexMap = lsGet('cea_kardex_docentes', null);
  if (!kardexMap || typeof kardexMap !== 'object' || Object.keys(kardexMap).length === 0) {
    kardexMap = {
      'hum-mat': JSON.parse(JSON.stringify(KARDEX_CHOQUE_MAMANI_SAMPLE)),
      'tec-sis': JSON.parse(JSON.stringify(KARDEX_GUALBERTO_CHOQUE_SAMPLE)),
      'condori': JSON.parse(JSON.stringify(KARDEX_CONDORI_SAMPLE))
    };
    lsSet('cea_kardex_docentes', kardexMap);
  } else {
    if (!kardexMap['tec-sis']) {
      kardexMap['tec-sis'] = JSON.parse(JSON.stringify(KARDEX_GUALBERTO_CHOQUE_SAMPLE));
      lsSet('cea_kardex_docentes', kardexMap);
    }
    if (!kardexMap['condori']) {
      kardexMap['condori'] = JSON.parse(JSON.stringify(KARDEX_CONDORI_SAMPLE));
      lsSet('cea_kardex_docentes', kardexMap);
    }
  }
  return kardexMap;
}

function setKardexDocentesStorage(map) {
  lsSet('cea_kardex_docentes', map);
  if (map && Object.keys(map).length > 0) {
    lsRemove('cea_kardex_docentes_vacio');
  }
}

