function obtenerDocentesParaKardex() {
  const d = lsGet('cea_docentes', DOCENTES_DEFAULT);
  const areasTec = lsGet('cea_areas_tec', AREAS_TEC_DEFAULT);
  const kardexMap = getKardexDocentesStorage();

  // Helper: build display name from Kardex entry (prefer Kardex names, fall back to docentes map)
  function nombreDesdeKardex(id, fallback) {
    const k = kardexMap[id];
    if (k) {
      const partes = [k.nombres, k.paterno, k.materno].filter(Boolean);
      if (partes.length > 0) return partes.join(' ');
    }
    return d[id] || fallback;
  }

  const list = [
    { id: 'hum-cn',  nombre: nombreDesdeKardex('hum-cn',  'Lic. Edmar Callisaya Tapia'), area: 'Ciencias Naturales (Humanística)', tipo: 'hum' },
    { id: 'hum-mat', nombre: nombreDesdeKardex('hum-mat', 'Lic. Marcela Choque Mamani'), area: 'Matemática (Humanística)', tipo: 'hum' },
    { id: 'hum-cs',  nombre: nombreDesdeKardex('hum-cs',  'Lic. María Estela Laura Tenorio'), area: 'Ciencias Sociales (Humanística)', tipo: 'hum' },
    { id: 'hum-len', nombre: nombreDesdeKardex('hum-len', 'Lic. Efraina Pajarito Ventura'), area: 'Lenguaje y Literatura (Humanística)', tipo: 'hum' },
    { id: 'tec-sis', nombre: nombreDesdeKardex('tec-sis', 'Lic. Gualberto Choque'), area: 'Sistemas Informáticos (Técnica)', tipo: 'tec' },
    { id: 'tec-sec', nombre: nombreDesdeKardex('tec-sec', 'Lic. Ofelia Flores'), area: 'Secretariado Ejecutivo (Técnica)', tipo: 'tec' },
    { id: 'tec-bel', nombre: nombreDesdeKardex('tec-bel', 'Lic. Maritza Ojeda Conde'), area: 'Belleza Integral (Técnica)', tipo: 'tec' },
    { id: 'tec-tex', nombre: nombreDesdeKardex('tec-tex', 'Lic. Maritza Ojeda Conde'), area: 'Corte y Confección (Técnica)', tipo: 'tec' },
    { id: 'tec-gas', nombre: nombreDesdeKardex('tec-gas', 'Lic. Lourdes Chambi'), area: 'Gastronomía (Técnica)', tipo: 'tec' },
    { id: 'tec-agr', nombre: nombreDesdeKardex('tec-agr', 'Lic. Macario Ticonipa'), area: 'Agropecuaria (Técnica)', tipo: 'tec' }
  ];

  // Agregar registros adicionales que puedan existir en el kardex map
  Object.keys(kardexMap).forEach(key => {
    if (!list.some(item => item.id === key)) {
      const k = kardexMap[key];
      const nom = [k.nombres, k.paterno, k.materno].filter(Boolean).join(' ') || 'Personal Docente';
      list.push({
        id: key,
        nombre: nom,
        area: k.ue || 'Personal CEA',
        tipo: 'general'
      });
    }
  });

  return list;
}

function calcularEstadoKardex(k) {
  if (!k) return 'pendiente';
  const tieneDatosBasicos = (k.nombres && k.ci && k.fechaNacimiento);
  const tienePlanillas = (k.item || k.rda);
  const tieneFormacion = (k.formacionProf && k.formacionProf.length > 0) || (k.formacionComp && k.formacionComp.length > 0);

  if (tieneDatosBasicos && tienePlanillas && tieneFormacion) {
    return 'completo';
  } else if (tieneDatosBasicos || tienePlanillas) {
    return 'proceso';
  }
  return 'pendiente';
}

function actualizarBadgeKardexDocenteSelf(areaKey) {
  const badge = document.getElementById('kardex-docente-self-badge');
  if (!badge) return;
  const kardexMap = getKardexDocentesStorage();
  const k = kardexMap[areaKey];
  const estado = calcularEstadoKardex(k);

  if (estado === 'completo') {
    badge.className = 'kardex-status-badge kardex-status-completo';
    badge.innerHTML = `<svg viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg> Completado (Oficial)`;
  } else if (estado === 'proceso') {
    badge.className = 'kardex-status-badge kardex-status-proceso';
    badge.innerHTML = `<svg viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/></svg> En Proceso`;
  } else {
    badge.className = 'kardex-status-badge kardex-status-pendiente';
    badge.innerHTML = `<svg viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg> Pendiente de Llenado`;
  }
}

function cargarKardexDocentesAdmin() {
  const tbody = document.getElementById('kardex-docentes-tbody');
  if (!tbody) return;

  const kardexMap = getKardexDocentesStorage();
  const docentes = obtenerDocentesParaKardex();

  const searchVal = (document.getElementById('kardex-search-input')?.value || '').toLowerCase().trim();
  const filterArea = document.getElementById('kardex-filter-area')?.value || 'todas';

  let total = docentes.length;
  let completados = 0;
  let pendientes = 0;

  docentes.forEach(d => {
    const k = kardexMap[d.id];
    const est = calcularEstadoKardex(k);
    if (est === 'completo') completados++;
    else pendientes++;
  });

  const statTot = document.getElementById('kardex-stat-total');
  const statComp = document.getElementById('kardex-stat-completados');
  const statPend = document.getElementById('kardex-stat-pendientes');
  if (statTot) statTot.textContent = total;
  if (statComp) statComp.textContent = completados;
  if (statPend) statPend.textContent = pendientes;

  const filtrados = docentes.filter(d => {
    if (filterArea === 'hum' && d.tipo !== 'hum') return false;
    if (filterArea === 'tec' && d.tipo !== 'tec') return false;
    if (searchVal) {
      const k = kardexMap[d.id] || {};
      const matchNom = (d.nombre || '').toLowerCase().includes(searchVal);
      const matchArea = (d.area || '').toLowerCase().includes(searchVal);
      const matchCI = (k.ci || '').toLowerCase().includes(searchVal);
      const matchRDA = (k.rda || '').toLowerCase().includes(searchVal);
      return matchNom || matchArea || matchCI || matchRDA;
    }
    return true;
  });

  if (filtrados.length === 0) {
    tbody.innerHTML = `
      <tr>
        <td colspan="6" style="text-align:center;padding:24px;color:var(--text-sec)">
          No se encontraron docentes con el criterio de búsqueda.
        </td>
      </tr>
    `;
    return;
  }

  tbody.innerHTML = filtrados.map(d => {
    const k = kardexMap[d.id] || {};
    const estado = calcularEstadoKardex(k);

    let estadoBadge = `<span class="kardex-status-badge kardex-status-pendiente">Pendiente</span>`;
    if (estado === 'completo') {
      estadoBadge = `<span class="kardex-status-badge kardex-status-completo"><svg viewBox="0 0 24 24" width="11" height="11" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg> Completo</span>`;
    } else if (estado === 'proceso') {
      estadoBadge = `<span class="kardex-status-badge kardex-status-proceso"><svg viewBox="0 0 24 24" width="11" height="11" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/></svg> En Proceso</span>`;
    }

    const rdaStr = k.rda ? `RDA: ${k.rda}` : (k.ci ? `C.I. ${k.ci}` : '<span style="color:var(--text-sec)">Sin registro</span>');
    const ultimaMod = k.ultimaModificacion || '<span style="color:var(--text-sec)">No registrado</span>';

    return `
      <tr style="border-bottom:1px solid var(--border-col);transition:background 0.15s ease">
        <td style="padding:12px 14px">
          <div style="font-weight:800;color:var(--text-main);font-size:0.92rem">${escapeHTML(d.nombre)}</div>
          <span style="font-size:0.75rem;color:var(--text-sec)">ID: ${d.id}</span>
        </td>
        <td style="padding:12px 14px">
          <span style="font-size:0.84rem;color:var(--verde-dark);font-weight:700">${escapeHTML(d.area)}</span>
        </td>
        <td style="padding:12px 14px;font-size:0.82rem;font-weight:600">
          ${rdaStr}
        </td>
        <td style="padding:12px 14px">
          ${estadoBadge}
        </td>
        <td style="padding:12px 14px;font-size:0.8rem;color:var(--text-sec)">
          ${ultimaMod}
        </td>
        <td style="padding:12px 14px;text-align:center">
          <div style="display:inline-flex;gap:8px;align-items:center">
            <button type="button" class="btn-kardex-editar" onclick="abrirEditorKardex('${d.id}', true)" title="Editar Kardex de ${escapeHTML(d.nombre)}" style="background:var(--verde);color:#ffffff;border:none;padding:7px 14px;font-size:0.82rem;font-weight:800;display:inline-flex;align-items:center;gap:6px;border-radius:6px;cursor:pointer">
              <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="#ffffff" stroke-width="2.3"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg>
              <span>Editar</span>
            </button>
            <button type="button" class="btn-kardex-imprimir" onclick="prepararEImprimirKardex('${d.id}', 1)" title="Imprimir Kárdex (Diseño 1 Oficial)" style="background:#b45309;color:#ffffff;border:none;padding:7px 11px;font-size:0.80rem;font-weight:800;display:inline-flex;align-items:center;gap:4px;border-radius:6px;cursor:pointer">
              <svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="#ffffff" stroke-width="2.3"><polyline points="6 9 6 2 18 2 18 9"/><path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"/><rect x="6" y="14" width="12" height="8"/></svg>
              <span>Imprimir D1</span>
            </button>
            <button type="button" class="btn-kardex-imprimir" onclick="prepararEImprimirKardex('${d.id}', 2)" title="Imprimir Kárdex (Diseño 2 Verde Institucional)" style="background:#15803d;color:#ffffff;border:none;padding:7px 11px;font-size:0.80rem;font-weight:800;display:inline-flex;align-items:center;gap:4px;border-radius:6px;cursor:pointer">
              <svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="#ffffff" stroke-width="2.3"><polyline points="6 9 6 2 18 2 18 9"/><path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"/><rect x="6" y="14" width="12" height="8"/></svg>
              <span>Imprimir D2</span>
            </button>
          </div>
        </td>
      </tr>
    `;
  }).join('');
}

