/* ─── HELPERS PARA SELECTS CON OPCIÓN "OTRO" Y FECHA AUTOMÁTICA DEL SISTEMA ─── */
function manejarSelectConOpcionOtro(selectId, manualInputId) {
  const sel = document.getElementById(selectId);
  const inp = document.getElementById(manualInputId);
  if (!sel || !inp) return;
  if (sel.value === 'OTRO') {
    inp.style.display = 'block';
    inp.focus();
  } else {
    inp.style.display = 'none';
  }
}

function setSelectConOpcionOtro(selectId, manualInputId, valor, fallback = '') {
  const sel = document.getElementById(selectId);
  const inp = document.getElementById(manualInputId);
  if (!sel) return;
  const val = (valor !== undefined && valor !== null && String(valor).trim() !== '') ? String(valor).trim() : fallback;
  if (!val) {
    if (sel.options.length > 0) sel.selectedIndex = 0;
    if (inp) { inp.style.display = 'none'; inp.value = ''; }
    return;
  }

  let found = false;
  for (let i = 0; i < sel.options.length; i++) {
    if (sel.options[i].value && sel.options[i].value.toUpperCase() === val.toUpperCase()) {
      sel.selectedIndex = i;
      found = true;
      break;
    }
  }

  if (found) {
    if (inp) {
      inp.style.display = 'none';
      inp.value = '';
    }
  } else {
    // Si no coincide con las opciones fijas, marcar "OTRO" y llenar el campo manual
    sel.value = 'OTRO';
    if (inp) {
      inp.style.display = 'block';
      inp.value = val;
    }
  }
}

function getSelectConOpcionOtro(selectId, manualInputId, fallback = '') {
  const sel = document.getElementById(selectId);
  const inp = document.getElementById(manualInputId);
  if (!sel) return fallback;
  if (sel.value === 'OTRO') {
    const custom = inp?.value?.trim() || '';
    return custom || fallback || 'OTRO';
  }
  return sel.value || fallback;
}

function alCambiarFechaSistemaKardex(fechaStr) {
  if (!fechaStr) return;
  const partes = fechaStr.split('-');
  if (partes.length === 3) {
    const anio = partes[0];
    const mesNum = parseInt(partes[1], 10) - 1;
    const dia = parseInt(partes[2], 10);
    const MESES_BOL = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];
    const diaEl = document.getElementById('kardex-lugar-fecha-dia');
    const mesEl = document.getElementById('kardex-lugar-fecha-mes');
    const anoLbl = document.getElementById('kardex-lugar-fecha-ano-lbl');
    if (diaEl) diaEl.value = String(dia);
    if (mesEl) mesEl.value = MESES_BOL[mesNum] || '';
    if (anoLbl) anoLbl.textContent = anio;
  }
}

function establecerFechaHoyKardex() {
  const hoy = new Date();
  const yyyy = hoy.getFullYear();
  const mm = String(hoy.getMonth() + 1).padStart(2, '0');
  const dd = String(hoy.getDate()).padStart(2, '0');
  const fechaIso = `${yyyy}-${mm}-${dd}`;
  const picker = document.getElementById('kardex-fecha-sistema-picker');
  if (picker) {
    picker.value = fechaIso;
  }
  alCambiarFechaSistemaKardex(fechaIso);
}

window.manejarSelectConOpcionOtro = manejarSelectConOpcionOtro;
window.setSelectConOpcionOtro = setSelectConOpcionOtro;
window.getSelectConOpcionOtro = getSelectConOpcionOtro;
window.alCambiarFechaSistemaKardex = alCambiarFechaSistemaKardex;
window.establecerFechaHoyKardex = establecerFechaHoyKardex;

/* ─── EDITOR CONTINUO DE KARDEX ─── */
let kardexDocenteActualId = '';
let kardexFotoBase64Actual = '';

function abrirEditorKardex(docenteId, esModoDirector) {
  kardexDocenteActualId = docenteId || 'hum-mat';
  const modal = document.getElementById('modal-kardex-editor');
  if (!modal) return;

  const kardexMap = getKardexDocentesStorage();
  const docentes = lsGet('cea_docentes', DOCENTES_DEFAULT);

  let data = kardexMap[kardexDocenteActualId];
  if (!data) {
    data = JSON.parse(JSON.stringify(KARDEX_MODEL_DEFAULT));
    // Prellenar nombre si es docente conocido
    if (docentes[kardexDocenteActualId]) {
      const parts = docentes[kardexDocenteActualId].replace(/^(Lic\.|Prof\.|Ing\.)\s+/i, '').trim().split(' ');
      if (parts.length >= 3) {
        data.nombres = parts.slice(0, parts.length - 2).join(' ');
        data.paterno = parts[parts.length - 2];
        data.materno = parts[parts.length - 1];
      } else if (parts.length === 2) {
        data.nombres = parts[0];
        data.paterno = parts[1];
      } else {
        data.nombres = parts.join(' ');
      }
    }
  }

  // Establecer IDs en campos ocultos
  document.getElementById('kardex-docente-id').value = kardexDocenteActualId;
  document.getElementById('kardex-area-key').value = kardexDocenteActualId;

  const nombreCompleto = [data.nombres, data.paterno, data.materno].filter(Boolean).join(' ') || docentes[kardexDocenteActualId] || 'Docente / Personal';
  const subTit = document.getElementById('kardex-modal-subtitulo');
  if (subTit) {
    subTit.textContent = `Personal: ${nombreCompleto} ${esModoDirector ? '(Modo Director)' : '(Modo Docente)'}`;
  }

  // Foto
  kardexFotoBase64Actual = data.foto || '';
  const imgEl = document.getElementById('kardex-preview-foto-img');
  const phEl = document.getElementById('kardex-preview-foto-placeholder');
  if (kardexFotoBase64Actual) {
    if (imgEl) { imgEl.src = kardexFotoBase64Actual; imgEl.style.display = 'block'; }
    if (phEl) phEl.style.display = 'none';
  } else {
    if (imgEl) { imgEl.src = ''; imgEl.style.display = 'none'; }
    if (phEl) phEl.style.display = 'flex';
  }

  // Gestión y Código Institucional
  const anioAuto = new Date().getFullYear();
  const elGestion = document.getElementById('kardex-gestion');
  if (elGestion) elGestion.value = data.gestion || String(anioAuto);
  const elCodigo = document.getElementById('kardex-codigo');
  if (elCodigo) elCodigo.value = data.codigoKardex || '245';

  // II. Unidad Educativa
  document.getElementById('kardex-cod-nucleo').value = data.codNucleo || '10084';
  document.getElementById('kardex-nucleo').value = data.nucleo || 'CRISPIN ANDRADE PORTUGAL';
  document.getElementById('kardex-cod-ue').value = data.codUE || '80630044';
  document.getElementById('kardex-ue').value = data.ue || 'CEA MADRE MARIE POUSSEPIN';

  // I. Datos Generales
  document.getElementById('kardex-paterno').value = data.paterno || '';
  document.getElementById('kardex-materno').value = data.materno || '';
  document.getElementById('kardex-conyuge').value = data.conyuge || '';
  document.getElementById('kardex-nombres').value = data.nombres || '';
  setSelectConOpcionOtro('kardex-genero', 'kardex-genero-manual', data.genero, 'F');

  // Filiación
  document.getElementById('kardex-fecha-nac').value = data.fechaNacimiento || '';
  document.getElementById('kardex-edad').value = data.edad || '';
  document.getElementById('kardex-ci').value = data.ci || '';
  setSelectConOpcionOtro('kardex-ci-exp', 'kardex-ci-exp-manual', data.expedido, 'LP');
  const elDepto = document.getElementById('kardex-departamento');
  if (elDepto) elDepto.value = data.departamento || (data.expedido === 'LP' ? 'LA PAZ' : data.expedido) || 'LA PAZ';
  document.getElementById('kardex-provincia').value = data.provincia || 'SUD YUNGAS';
  document.getElementById('kardex-localidad').value = data.localidad || 'CHULUMANI';
  setSelectConOpcionOtro('kardex-estado-civil', 'kardex-estado-civil-manual', data.estadoCivil, 'SOLTERO(A)');
  document.getElementById('kardex-libreta-militar').value = data.libretaMilitar || '';
  document.getElementById('kardex-tipo-sangre').value = data.tipoSangre || '';

  // Domicilio
  document.getElementById('kardex-domicilio-calle').value = data.domicilioCalle || '';
  document.getElementById('kardex-domicilio-num').value = data.domicilioNum || '';
  document.getElementById('kardex-telefono').value = data.telefono || '';
  document.getElementById('kardex-celular').value = data.celular || '';

  // III. Planillas
  setSelectConOpcionOtro('kardex-servicio', 'kardex-servicio-manual', data.servicio, 'URBANO');
  document.getElementById('kardex-item').value = data.item || '';
  document.getElementById('kardex-rda').value = data.rda || '';
  setSelectConOpcionOtro('kardex-categoria', 'kardex-categoria-manual', data.categoria, 'SEGUNDA');
  document.getElementById('kardex-ano-egreso').value = data.anoEgreso || '';
  document.getElementById('kardex-anos-servicio').value = data.anosServicio || '';
  document.getElementById('kardex-anos-distrito').value = data.anosDistrito || '';

  // Unidades Educativas de Trabajo (dinámico)
  const tbodyUE = document.getElementById('kardex-tbody-ultimas-ue');
  if (tbodyUE) {
    tbodyUE.innerHTML = '';
    const ues = Array.isArray(data.ultimasUE) && data.ultimasUE.length > 0
      ? data.ultimasUE
      : [{ distrito: '', ue: '' }, { distrito: '', ue: '' }, { distrito: '', ue: '' }];
    ues.forEach(it => agregarFilaUltimaUE(it));
  }

  // IV. Formación Profesional
  const tbodyFP = document.getElementById('kardex-tbody-formacion-prof');
  if (tbodyFP) {
    tbodyFP.innerHTML = '';
    (data.formacionProf && data.formacionProf.length > 0 ? data.formacionProf : [{}]).forEach(it => agregarFilaFormacionProf(it));
  }

  // V. Formación Complementaria
  const tbodyFC = document.getElementById('kardex-tbody-formacion-comp');
  if (tbodyFC) {
    tbodyFC.innerHTML = '';
    (data.formacionComp && data.formacionComp.length > 0 ? data.formacionComp : [{}]).forEach(it => agregarFilaFormacionComp(it));
  }
  document.getElementById('kardex-aclaraciones-v').value = data.aclaracionesV || '';

  // VI. Capacitaciones
  const tbodyCap = document.getElementById('kardex-tbody-capacitacion');
  if (tbodyCap) {
    tbodyCap.innerHTML = '';
    (data.capacitaciones && data.capacitaciones.length > 0 ? data.capacitaciones : [{}]).forEach(it => agregarFilaCapacitacion(it));
  }

  // VII. Experiencia
  const tbodyExp = document.getElementById('kardex-tbody-experiencia');
  if (tbodyExp) {
    tbodyExp.innerHTML = '';
    (data.experiencia && data.experiencia.length > 0 ? data.experiencia : [{}]).forEach(it => agregarFilaExperiencia(it));
  }

  // VIII. Familiares y Referencias
  const tbodyFam = document.getElementById('kardex-tbody-familiares');
  if (tbodyFam) {
    tbodyFam.innerHTML = '';
    (data.familiaresUrgencia && data.familiaresUrgencia.length > 0 ? data.familiaresUrgencia : [{}]).forEach(it => agregarFilaFamiliarUrgencia(it));
  }

  const tbodyRef = document.getElementById('kardex-tbody-referencias');
  if (tbodyRef) {
    tbodyRef.innerHTML = '';
    (data.referenciasPersonales && data.referenciasPersonales.length > 0 ? data.referenciasPersonales : [{}]).forEach(it => agregarFilaReferenciaPersonal(it));
  }

  // Cierre fecha automática del sistema
  const hoy = new Date();
  const MESES_BOL = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];
  const diaAuto = String(hoy.getDate());
  const mesAuto = MESES_BOL[hoy.getMonth()] || (MESES && MESES[hoy.getMonth()]) || 'octubre';
  const yyyyAuto = String(hoy.getFullYear());
  const mmAuto = String(hoy.getMonth() + 1).padStart(2, '0');
  const ddAuto = String(hoy.getDate()).padStart(2, '0');
  const fechaIsoHoy = `${yyyyAuto}-${mmAuto}-${ddAuto}`;

  const pickerEl = document.getElementById('kardex-fecha-sistema-picker');
  if (pickerEl) {
    pickerEl.value = data.fechaSistema || fechaIsoHoy;
  }
  const diaInp = document.getElementById('kardex-lugar-fecha-dia');
  const mesInp = document.getElementById('kardex-lugar-fecha-mes');
  const anoLbl = document.getElementById('kardex-lugar-fecha-ano-lbl');
  if (diaInp) diaInp.value = data.lugarFechaDia || diaAuto;
  if (mesInp) mesInp.value = data.lugarFechaMes || mesAuto;
  if (anoLbl) anoLbl.textContent = (data.fechaSistema ? data.fechaSistema.split('-')[0] : yyyyAuto);

  const msgG = document.getElementById('kardex-msg-guardado');
  if (msgG) msgG.innerHTML = '';

  modal.style.display = 'flex';
  document.body.style.overflow = 'hidden';
}

function cerrarModalKardexEditor() {
  const modal = document.getElementById('modal-kardex-editor');
  if (modal) modal.style.display = 'none';
  document.body.style.overflow = '';
}

function autoCalcularEdadKardex() {
  const fnacVal = document.getElementById('kardex-fecha-nac')?.value;
  if (!fnacVal) return;
  const nac = new Date(fnacVal);
  const hoy = new Date();
  let edad = hoy.getFullYear() - nac.getFullYear();
  const m = hoy.getMonth() - nac.getMonth();
  if (m < 0 || (m === 0 && hoy.getDate() < nac.getDate())) {
    edad--;
  }
  if (edad >= 10 && edad <= 99) {
    const edadInp = document.getElementById('kardex-edad');
    if (edadInp) edadInp.value = edad;
  }
}

function procesarFotoKardex(event) {
  const file = event.target.files?.[0];
  if (!file) return;

  const reader = new FileReader();
  reader.onload = (e) => {
    const img = new Image();
    img.onload = () => {
      // Redimensionar para no saturar localStorage (máx 350x450px)
      const canvas = document.createElement('canvas');
      const maxW = 350;
      const maxH = 450;
      let w = img.width;
      let h = img.height;
      if (w > maxW || h > maxH) {
        const ratio = Math.min(maxW / w, maxH / h);
        w = Math.round(w * ratio);
        h = Math.round(h * ratio);
      }
      canvas.width = w;
      canvas.height = h;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(img, 0, 0, w, h);
      kardexFotoBase64Actual = canvas.toDataURL('image/jpeg', 0.85);

      const imgEl = document.getElementById('kardex-preview-foto-img');
      const phEl = document.getElementById('kardex-preview-foto-placeholder');
      if (imgEl) {
        imgEl.src = kardexFotoBase64Actual;
        imgEl.style.display = 'block';
      }
      if (phEl) phEl.style.display = 'none';
    };
    img.src = e.target.result;
  };
  reader.readAsDataURL(file);
}

function quitarFotoKardex() {
  kardexFotoBase64Actual = '';
  const imgEl = document.getElementById('kardex-preview-foto-img');
  const phEl = document.getElementById('kardex-preview-foto-placeholder');
  const inpEl = document.getElementById('kardex-inp-foto');
  if (imgEl) { imgEl.src = ''; imgEl.style.display = 'none'; }
  if (phEl) phEl.style.display = 'flex';
  if (inpEl) inpEl.value = '';
}

/* ─── FILAS DINÁMICAS ─── */
function renumerarFilasUltimaUE() {
  const tbody = document.getElementById('kardex-tbody-ultimas-ue');
  if (!tbody) return;
  tbody.querySelectorAll('tr').forEach((tr, idx) => {
    const tdNum = tr.querySelector('td:first-child');
    if (tdNum) tdNum.textContent = idx + 1;
  });
}

function agregarFilaUltimaUE(item = {}) {
  const tbody = document.getElementById('kardex-tbody-ultimas-ue');
  if (!tbody) return;
  const num = tbody.querySelectorAll('tr').length + 1;
  const tr = document.createElement('tr');
  tr.innerHTML = `
    <td style="text-align:center;font-weight:700;color:#15803d">${num}</td>
    <td><input type="text" class="kue-dist" placeholder="Ej. CHULUMANI" value="${escapeHTML(item.distrito || '')}" /></td>
    <td><input type="text" class="kue-nombre" placeholder="Ej. CEA MADRE MARIE POUSSEPIN" value="${escapeHTML(item.ue || '')}" /></td>
    <td style="text-align:center">
      <button type="button" class="btn-del-fila-kardex" onclick="eliminarFilaUltimaUE(this)" title="Eliminar fila">
        <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2.2"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
      </button>
    </td>
  `;
  tbody.appendChild(tr);
  renumerarFilasUltimaUE();
}

function eliminarFilaUltimaUE(btn) {
  const tr = btn.closest('tr');
  if (tr) {
    tr.remove();
    renumerarFilasUltimaUE();
  }
}

