function prepararEImprimirTodosLosKardex(filtradosSolamente = false, diseno = 1) {
  if (typeof window.aplicarOrientacionKardex === 'function') {
    window.aplicarOrientacionKardex(diseno);
  } else {
    aplicarOrientacionImpresion('portrait');
  }

  const kardexMap = getKardexDocentesStorage();
  const docentesAll = obtenerDocentesParaKardex();

  let listaDocentes = docentesAll;
  if (filtradosSolamente) {
    const searchVal = (document.getElementById('kardex-search-input')?.value || '').toLowerCase().trim();
    const filterArea = document.getElementById('kardex-filter-area')?.value || 'todas';
    listaDocentes = docentesAll.filter(d => {
      if (filterArea === 'hum' && d.tipo !== 'hum') return false;
      if (filterArea === 'tec' && d.tipo !== 'tec') return false;
      if (searchVal) {
        const k = kardexMap[d.id] || {};
        const matchNom = (d.nombre || '').toLowerCase().includes(searchVal);
        const matchArea = (d.area || '').toLowerCase().includes(searchVal);
        const matchCI = (k.ci || '').toLowerCase().includes(searchVal);
        const matchRDA = (k.rda || '').toLowerCase().includes(searchVal);
        return matchNom || matchArea || matchCI || matchRDA;
      }
      return true;
    });
  }

  if (listaDocentes.length === 0) {
    if (typeof mostrarAlertaModal === 'function') {
      mostrarAlertaModal('No hay registros de Kardex disponibles para imprimir o guardar.', 'Kardex Docente', 'warning');
    } else if (typeof mostrarToastLive === 'function') {
      mostrarToastLive('No hay registros de Kardex disponibles.');
    }
    return;
  }

  const printArea = document.getElementById('kardex-print-area');
  if (!printArea) return;

  const page1 = document.createElement('div');
  page1.style.display = 'none';
  const page2 = document.createElement('div');
  page2.style.display = 'none';
  document.body.appendChild(page1);
  document.body.appendChild(page2);

  let htmlBatch = '';
  listaDocentes.forEach((docenteObj, idx) => {
    const docenteId = docenteObj.id;
    const data = kardexMap[docenteId] || JSON.parse(JSON.stringify(KARDEX_MODEL_DEFAULT));

    prepararContenidoKardexDOM(data, page1, page2);
    const p1HTML = page1.innerHTML;
    const p2HTML = page2.innerHTML;

    htmlBatch += `
      <div class="kardex-docente-batch-wrap">
        <div class="kardex-print-page kardex-page-1">
          ${p1HTML}
        </div>
        <div class="kardex-print-page kardex-page-2" style="${idx < listaDocentes.length - 1 ? 'page-break-after:always !important; break-after:page !important;' : ''}">
          ${p2HTML}
        </div>
      </div>
    `;
  });

  page1.remove();
  page2.remove();

  printArea.innerHTML = htmlBatch;

  document.body.classList.add('printing-kardex');
  document.body.classList.remove('printing-horario', 'printing-comprobante', 'printing-reporte');

  const limpiarKardexBatch = () => {
    document.body.classList.remove('printing-kardex');
    window.removeEventListener('afterprint', limpiarKardexBatch);
  };
  window.addEventListener('afterprint', limpiarKardexBatch);

  setTimeout(() => {
    window.print();
    setTimeout(limpiarKardexBatch, 800);
  }, 100);
}

